INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86480, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "目前；当前。", "primary_collocate": null, "pronunciation": "shí xià", "ipa": "ʂɻ̩˧˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "时下最流行的歌，你听过吗？", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时下的房价比去年高很多。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时下大家最关心的是工作问题。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时下很多年轻人喜欢在网上买东西。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时下市场上的水果又多又便宜。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时下这家公司的生意不太好。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时下很多学生在学汉语。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太了解时下的流行音乐。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时下的电影比以前好看。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时下最受欢迎的运动是跑步。", "target_word": "时下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "目前当前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人的容貌，不能用来修饰“流行的歌”。"}, {"text": "时下", "is_correct": true, "explanation": "正确：“时下”指目前、当前，与“最流行的歌，你听过吗”的当前语境相符。"}, {"text": "姓名", "is_correct": false, "explanation": "搭配：“姓名”指名称，不能用来修饰“流行的歌”。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”指品格特点，不能用来修饰“流行的歌”。"}], "explanations": {"外貌": "体貌：“外貌”指人的容貌，不能用来修饰“流行的歌”。", "时下": "正确：“时下”指目前、当前，与“最流行的歌，你听过吗”的当前语境相符。", "姓名": "搭配：“姓名”指名称，不能用来修饰“流行的歌”。", "性格": "搭配：“性格”指品格特点，不能用来修饰“流行的歌”。"}, "sentence_index": 0, "correct_answer": "时下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "高中时，他时下很喜欢数学。", "explanation": "这里应该用〈那时〉。时下指目前，不能用于“高中时”这样的过去时间，与句中的过去时间冲突。"}, {"text": "去年他时下还在读大学，后来才开始创业。", "explanation": "这里应该用〈当时〉。时下指目前，不能用于“去年”这样的过去时间，与“后来才开始创业”的过去经历矛盾。"}, {"text": "2000年时下，他还是个学生。", "explanation": "这里应该用〈那时〉。时下指目前，不能与具体的过去年份“2000年”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，不能作“很多学生在学汉语”的时间主语。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”指色彩，不能作时间主语。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”指岁数，不能作时间主语。"}, {"text": "时下", "is_correct": true, "explanation": "正确：“时下”指目前，与“很多学生在学汉语”的当前情况相符。"}], "explanations": {"身材": "体貌：“身材”指人的体型，不能作“很多学生在学汉语”的时间主语。", "颜色": "搭配：“颜色”指色彩，不能作时间主语。", "年龄": "搭配：“年龄”指岁数，不能作时间主语。", "时下": "正确：“时下”指目前，与“很多学生在学汉语”的当前情况相符。"}, "sentence_index": 6, "correct_answer": "时下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那天晚上，我时下在吃饭，电话响了。", "explanation": "这里应该用〈当时〉。时下指目前，不能用来指过去的某个时刻，与“那天晚上”冲突。"}, {"text": "下个月我时下要搬家。", "explanation": "这里应该用〈将来〉。时下指目前，不能与“下个月”这样的未来时间搭配。"}, {"text": "十年前时下这里没有地铁，大家都坐公交车。", "explanation": "这里应该用〈从前〉。时下指目前，不能用于“十年前”这样的过去时间，与“大家都坐公交车”的过去情形矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "时下过，很多人都在关注这件事。", "corrected_sentence": "时下，很多人都在关注这件事。", "error_description": "“时下”是时间词，后面不能加“过”，应删去“过”，改为“时下，很多人都在关注这件事。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "时下了，大家都在等待消息。", "corrected_sentence": "时下，大家都在等待消息。", "error_description": "“时下”是时间词，后面不能加“了”，应删去“了”，改为“时下，大家都在等待消息。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
