INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86481, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "医院是生病的人去看病的地方。", "primary_collocate": null, "pronunciation": "yī yuàn", "ipa": "i˥ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我发烧了，得去医院看病。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶生病了，爸爸送她去医院。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院离我家不远，走路十分钟。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天在医院住了一晚。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子咳嗽，妈妈带他去医院。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的脸色不好，最好去医院检查一下。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿受伤了，现在在医院躺着。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里很安静，病人都在休息。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我去医院看望生病的朋友。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附近有医院吗？我肚子很疼。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "所", "label": "量词"}, {"form": "儿童医院", "label": "复合"}, {"form": "醫院", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生病的人去看病的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86481, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议院", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是国家的立法机构，如“参议院”。"}, {"text": "遗愿", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是人在去世前留下的愿望。"}, {"text": "医院", "is_correct": true, "explanation": "医院：生病的人去看病的地方。"}, {"text": "一员", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是团体中的一个成员。"}, {"text": "亿元", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是一亿元人民币。"}], "explanations": {"议院": "yì（第四声）与 yī（第一声）声调不同，意思是国家的立法机构，如“参议院”。", "遗愿": "yí（第二声）与 yī（第一声）声调不同，意思是人在去世前留下的愿望。", "医院": "医院：生病的人去看病的地方。", "一员": "yuán（第二声）与 yuàn（第四声）声调不同，意思是团体中的一个成员。", "亿元": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是一亿元人民币。"}, "sentence_index": null, "correct_answer": "医院"}, "level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：银行办理存取款等业务，不能用来看病。"}, {"text": "医院", "is_correct": true, "explanation": "医院：与“看病”相符，是生病的人看病的地方。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园供人游玩休息，与“发烧、得去看病”的语境不相符。"}, {"text": "药店", "is_correct": false, "explanation": "搭配：“看病”一般去医院或诊所，药店只能买药或咨询，不能说“去药店看病”。"}], "explanations": {"银行": "语义：银行办理存取款等业务，不能用来看病。", "医院": "医院：与“看病”相符，是生病的人看病的地方。", "公园": "语义：公园供人游玩休息，与“发烧、得去看病”的语境不相符。", "药店": "搭配：“看病”一般去医院或诊所，药店只能买药或咨询，不能说“去药店看病”。"}, "sentence_index": 0, "correct_answer": "医院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的车很脏，我去医院洗车。", "explanation": "这里应该用〈洗车店〉。洗车要去洗车店，医院不给车洗车，不能用来洗车。"}, {"text": "周末我们去医院打篮球。", "explanation": "这里应该用〈体育馆〉。打篮球要去体育馆或球场，医院是看病的地方，不能用来打球。"}, {"text": "我昨天去医院买了一双鞋。", "explanation": "这里应该用〈鞋店〉。买鞋要去鞋店，医院不卖鞋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86481, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意愿", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是心愿、愿望。"}, {"text": "一元", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是人民币的单位“元”。"}, {"text": "医院", "is_correct": true, "explanation": "医院：生病的人去看病的地方。"}, {"text": "艺员", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是从事表演的人。"}], "explanations": {"意愿": "yì（第四声）与 yī（第一声）声调不同，意思是心愿、愿望。", "一元": "yuán（第二声）与 yuàn（第四声）声调不同，意思是人民币的单位“元”。", "医院": "医院：生病的人去看病的地方。", "艺员": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是从事表演的人。"}, "sentence_index": null, "correct_answer": "医院"}, "level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，与“腿受伤、需要治疗”的语境不相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是看书学习的地方，与“腿受伤、躺着”的语境不相符。"}, {"text": "医院", "is_correct": true, "explanation": "医院：与“腿受伤了”“躺着”相符，受伤的人需要在医院治疗休息。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行办理存取款等业务，受伤的人不会在银行躺着休养，与“腿受伤了”的语境不相符。"}], "explanations": {"厨房": "语义：厨房是做饭的地方，与“腿受伤、需要治疗”的语境不相符。", "图书馆": "语义：图书馆是看书学习的地方，与“腿受伤、躺着”的语境不相符。", "医院": "医院：与“腿受伤了”“躺着”相符，受伤的人需要在医院治疗休息。", "银行": "语义：银行办理存取款等业务，受伤的人不会在银行躺着休养，与“腿受伤了”的语境不相符。"}, "sentence_index": 6, "correct_answer": "医院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们去医院喝酒。", "explanation": "这里应该用〈酒吧〉。喝酒要去酒吧或饭馆，医院是看病的地方，不能用来喝酒。"}, {"text": "他的生日礼物是一家医院。", "explanation": "这里应该用〈蛋糕〉一类的物品。“医院”是机构，不能当作礼物送人。"}, {"text": "我把钱存进了医院。", "explanation": "这里应该用〈银行〉。存钱要去银行，医院不办理存款业务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐下午医院陪了奶奶。", "corrected_sentence": "姐姐下午在医院陪了奶奶。", "error_description": "漏掉了介词“在”。“医院”作地点时前面要加“在”，应说“在医院陪奶奶”，不能直接说“医院陪奶奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在一只医院做志愿者。", "corrected_sentence": "他在一家医院做志愿者。", "error_description": "量词错误：“医院”是机构，应用量词“家”或“所”，不能用“只”（“只”用于动物或成对的物品）。应为“在一家医院做志愿者”，写成“在一只医院”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
