INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。", "primary_collocate": null, "pronunciation": "yī yuàn", "ipa": "i˥ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这家医院有很多好医生。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王医生在市中心的医院工作。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有医生、护士和病房。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所医院今年新建了一栋楼。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在医院当护士已经十年了。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院门口有一家小药店。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的急诊室很忙。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院每天都要接待很多病人。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市最大的医院就在河边。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有内科、外科和儿科。", "target_word": "医院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "所", "label": "量词"}, {"form": "儿童医院", "label": "复合"}, {"form": "醫院", "label": "繁体"}], "register": "中性", "sense_fingerprint": "诊治疾病、设有医生护士病房的医疗机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 内科 (Zipf 3.49), 外科 (Zipf 3.88), 儿科 (Zipf 3.35)']::text[], 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意愿", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是心愿、愿望。"}, {"text": "医院", "is_correct": true, "explanation": "医院：专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。"}, {"text": "遗愿", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是人在去世前留下的愿望。"}, {"text": "一员", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是团体中的一个成员。"}, {"text": "亿元", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是一亿元人民币。"}], "explanations": {"意愿": "yì（第四声）与 yī（第一声）声调不同，意思是心愿、愿望。", "医院": "医院：专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。", "遗愿": "yí（第二声）与 yī（第一声）声调不同，意思是人在去世前留下的愿望。", "一员": "yuán（第二声）与 yuàn（第四声）声调不同，意思是团体中的一个成员。", "亿元": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是一亿元人民币。"}, "sentence_index": null, "correct_answer": "医院"}, "level_3": {"options": [{"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的地方，与“有很多好医生”的语境不相符。"}, {"text": "医院", "is_correct": true, "explanation": "医院：与“有很多好医生”相符，指专门看病的机构，量词“家”可用于医院。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：量词“家”一般不用于学校，学校通常说“所”，“这家学校”不地道。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行办理存取款等业务，与“有很多好医生”无关。"}], "explanations": {"超市": "语义：超市是卖东西的地方，与“有很多好医生”的语境不相符。", "医院": "医院：与“有很多好医生”相符，指专门看病的机构，量词“家”可用于医院。", "学校": "搭配：量词“家”一般不用于学校，学校通常说“所”，“这家学校”不地道。", "银行": "语义：银行办理存取款等业务，与“有很多好医生”无关。"}, "sentence_index": 0, "correct_answer": "医院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车没油了，我去医院加油。", "explanation": "这里应该用〈加油站〉。加油要去加油站，医院不给车加油，不能用来加油。"}, {"text": "我想当医院，帮助病人。", "explanation": "这里应该用〈医生〉。医院是场所，说要当某种职业时要用〈医生〉，不能说“当医院”。"}, {"text": "我把工资存进了医院。", "explanation": "这里应该用〈银行〉。存工资要去银行，医院是看病的地方，不能用来存钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议院", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是国家的立法机构，如“参议院”。"}, {"text": "医院", "is_correct": true, "explanation": "医院：专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。"}, {"text": "一元", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是人民币的单位“元”。"}, {"text": "艺员", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是从事表演的人。"}], "explanations": {"议院": "yì（第四声）与 yī（第一声）声调不同，意思是国家的立法机构，如“参议院”。", "医院": "医院：专门给病人诊断和治疗疾病的机构，设有医生、护士和病房。", "一元": "yuán（第二声）与 yuàn（第四声）声调不同，意思是人民币的单位“元”。", "艺员": "yì（第四声）与 yī（第一声），yuán（第二声）与 yuàn（第四声）声调都不同，意思是从事表演的人。"}, "sentence_index": null, "correct_answer": "医院"}, "level_3": {"options": [{"text": "花店", "is_correct": false, "explanation": "语义：花店经营鲜花，没有急诊室，与“急诊室很忙”不相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行办理存取款等业务，没有急诊室，与“急诊室很忙”不相符。"}, {"text": "医院", "is_correct": true, "explanation": "医院：设有急诊室，与“急诊室很忙”相符。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店经营书籍，没有急诊室，与“急诊室很忙”不相符。"}], "explanations": {"花店": "语义：花店经营鲜花，没有急诊室，与“急诊室很忙”不相符。", "银行": "语义：银行办理存取款等业务，没有急诊室，与“急诊室很忙”不相符。", "医院": "医院：设有急诊室，与“急诊室很忙”相符。", "书店": "语义：书店经营书籍，没有急诊室，与“急诊室很忙”不相符。"}, "sentence_index": 6, "correct_answer": "医院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末常去医院看电影。", "explanation": "这里应该用〈电影院〉。看电影要去电影院，医院是看病的地方，不能用来看电影。"}, {"text": "我今天要去医院买菜。", "explanation": "这里应该用〈超市〉。买菜要去超市或菜场，医院不卖菜。"}, {"text": "我下午去医院剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店，医院不提供这项服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天医院做了检查。", "corrected_sentence": "我昨天在医院做了检查。", "error_description": "漏掉了地点介词“在”。“医院”作地点时前面要加“在”，应说“在医院做检查”，不能说“医院做检查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张医院的护士很耐心。", "corrected_sentence": "这家医院的护士很耐心。", "error_description": "量词用错。“张”用于桌子、纸张等平面或片状的东西，不能修饰医院；医院应用量词“家”或“所”，说“这家医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
