INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86483, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "冲是很快地向前跑。", "primary_collocate": null, "pronunciation": "chōng", "ipa": "tʂʰʊŋ˥", "syllable_count": 1, "sentences": [{"text": "听到铃声，学生们都冲出教室。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听到消息，就往门口冲。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始了，选手们向前冲。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看见我，一下子冲过来了。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们冲向海边，想马上下水。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮了，那辆车还往前冲。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他冲上楼去拿了手机，又下来了。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课了，我们冲到食堂去吃饭。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到妈妈回来，弟弟冲了过去。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员接到球，一直冲到门前。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冲了", "label": "体标"}, {"form": "冲过", "label": "体标"}, {"form": "衝", "label": "繁体"}], "register": "口语", "sense_fingerprint": "很快地向前跑，冲向某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86483, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冲", "is_correct": true, "explanation": "chōng（第一声）是本词，意思是很快地向前跑。"}, {"text": "中", "is_correct": false, "explanation": "zhōng（第一声）与 chōng 声母不同（zh 与 ch），意思是中间。"}, {"text": "葱", "is_correct": false, "explanation": "cōng（第一声）与 chōng 声母不同（c 与 ch），意思是葱，一种蔬菜。"}, {"text": "虫", "is_correct": false, "explanation": "chóng（第二声）与 chōng 声调不同，意思是昆虫。"}, {"text": "宠", "is_correct": false, "explanation": "chǒng（第三声）与 chōng 声调不同，意思是宠爱。"}], "explanations": {"冲": "chōng（第一声）是本词，意思是很快地向前跑。", "中": "zhōng（第一声）与 chōng 声母不同（zh 与 ch），意思是中间。", "葱": "cōng（第一声）与 chōng 声母不同（c 与 ch），意思是葱，一种蔬菜。", "虫": "chóng（第二声）与 chōng 声调不同，意思是昆虫。", "宠": "chǒng（第三声）与 chōng 声调不同，意思是宠爱。"}, "sentence_index": null, "correct_answer": "冲"}, "level_3": {"options": [{"text": "冲", "is_correct": true, "explanation": "冲出：很快地向外跑，与“听到铃声”后快速离开的语境相符。"}, {"text": "飘", "is_correct": false, "explanation": "语义：“飘”指轻轻浮动，与学生听到铃声后急速离开的情境不符。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”表示停留，不能说“站出教室”来表示离开。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指跌倒，学生并非跌出去，与语境不符。"}], "explanations": {"冲": "冲出：很快地向外跑，与“听到铃声”后快速离开的语境相符。", "飘": "语义：“飘”指轻轻浮动，与学生听到铃声后急速离开的情境不符。", "站": "搭配：“站”表示停留，不能说“站出教室”来表示离开。", "摔": "语义：“摔”指跌倒，学生并非跌出去，与语境不符。"}, "sentence_index": 0, "correct_answer": "冲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛时，他冲得很慢，最后一个到终点。", "explanation": "这里应该用〈跑〉。冲表示很快地向前跑，不能与“很慢”搭配。"}, {"text": "他每天早上冲了一个小时，身体很好。", "explanation": "这里应该用〈跑〉。冲强调很快地向前猛冲，不能用来指长时间的慢跑锻炼。"}, {"text": "他慢慢地冲进了教室。", "explanation": "这里应该用〈走〉。冲表示很快地向前跑，与“慢慢地”互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86483, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冲", "is_correct": true, "explanation": "chōng（第一声）是本词，意思是很快地向前跑。"}, {"text": "钟", "is_correct": false, "explanation": "zhōng（第一声）与 chōng 声母不同（zh 与 ch），意思是钟表。"}, {"text": "聪", "is_correct": false, "explanation": "cōng（第一声）与 chōng 声母不同（c 与 ch），意思是聪明。"}, {"text": "崇", "is_correct": false, "explanation": "chóng（第二声）与 chōng 声调不同，意思是崇拜。"}, {"text": "撑", "is_correct": false, "explanation": "chēng（第一声）与 chōng 韵母不同（e 与 o），意思是撑开。"}], "explanations": {"冲": "chōng（第一声）是本词，意思是很快地向前跑。", "钟": "zhōng（第一声）与 chōng 声母不同（zh 与 ch），意思是钟表。", "聪": "cōng（第一声）与 chōng 声母不同（c 与 ch），意思是聪明。", "崇": "chóng（第二声）与 chōng 声调不同，意思是崇拜。", "撑": "chēng（第一声）与 chōng 韵母不同（e 与 o），意思是撑开。"}, "sentence_index": null, "correct_answer": "冲"}, "level_3": {"options": [{"text": "冲", "is_correct": true, "explanation": "冲上：很快地向上跑，与“上楼去拿手机，又下来了”的快速往返相符。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中划行，人不能游上楼，与语境不符。"}, {"text": "躺", "is_correct": false, "explanation": "体貌：“躺”表示静止的平卧，与“上楼去拿手机”的持续移动不符。"}, {"text": "跪", "is_correct": false, "explanation": "体貌：“跪”表示屈膝静止的姿态，与上楼的移动不符。"}], "explanations": {"冲": "冲上：很快地向上跑，与“上楼去拿手机，又下来了”的快速往返相符。", "游": "语义：“游”指在水中划行，人不能游上楼，与语境不符。", "躺": "体貌：“躺”表示静止的平卧，与“上楼去拿手机”的持续移动不符。", "跪": "体貌：“跪”表示屈膝静止的姿态，与上楼的移动不符。"}, "sentence_index": 6, "correct_answer": "冲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他倒着冲出了房间。", "explanation": "这里应该用〈退〉。冲表示向前猛冲，与“倒着”的后退方向相反。"}, {"text": "他躺在床上冲了一个下午。", "explanation": "这里应该用〈休息〉。冲表示很快地向前跑，不能和“躺在床上”同时发生。"}, {"text": "他一直冲在队伍最后，没有超过任何人。", "explanation": "这里应该用〈落〉。冲在前面表示领先、带头，与“最后”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门一开，孩子们就冲着出来。", "corrected_sentence": "门一开，孩子们就冲了出来。", "error_description": "动态助词误用：“冲”后表示完成的动作要用“了”，写成“冲着出来”是错误；“着”表示持续状态，不表示完成。正确形式是“冲了出来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听到消息，就往门口冲上。", "corrected_sentence": "他听到消息，就往门口冲去。", "error_description": "趋向补语误用：门口不是向上的方向，“冲上”与“往门口”矛盾，应用表示朝向远处的“去”。正确形式是“往门口冲去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
