INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86484, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水浇洗；水流猛烈地把东西冲走。", "primary_collocate": null, "pronunciation": "chōng", "ipa": "tʂʰʊŋ˥", "syllable_count": 1, "sentences": [{"text": "他用水把脚上的泥冲干净了。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，把路边的小车冲走了。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭后请把碗冲一冲。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开水龙头，冲了冲手。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水冲进了村子。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很急，把岸边的泥土冲掉了一大块。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水冲走了河上的桥。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动后，我想先冲个澡。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用热水把头发冲了一遍，然后擦干。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用清水把菜冲一下。", "target_word": "冲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冲了", "label": "体标"}, {"form": "冲一冲", "label": "重叠"}, {"form": "沖", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用水浇洗，或水流猛烈冲走东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86484, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冲", "is_correct": true, "explanation": "chōng（第一声）是本词，意思是用水浇洗，或水流猛烈冲走东西。"}, {"text": "钟", "is_correct": false, "explanation": "zhōng（第一声）与 chōng 声母不同（zh 与 ch），意思是钟表。"}, {"text": "聪", "is_correct": false, "explanation": "cōng（第一声）与 chōng 声母不同（c 与 ch），意思是聪明。"}, {"text": "虫", "is_correct": false, "explanation": "chóng（第二声）与 chōng 声调不同，意思是昆虫。"}, {"text": "宠", "is_correct": false, "explanation": "chǒng（第三声）与 chōng 声调不同，意思是宠爱。"}], "explanations": {"冲": "chōng（第一声）是本词，意思是用水浇洗，或水流猛烈冲走东西。", "钟": "zhōng（第一声）与 chōng 声母不同（zh 与 ch），意思是钟表。", "聪": "cōng（第一声）与 chōng 声母不同（c 与 ch），意思是聪明。", "虫": "chóng（第二声）与 chōng 声调不同，意思是昆虫。", "宠": "chǒng（第三声）与 chōng 声调不同，意思是宠爱。"}, "sentence_index": null, "correct_answer": "冲"}, "level_3": {"options": [{"text": "冲", "is_correct": true, "explanation": "冲干净：用水流把泥冲掉，与“用水”的语境相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火焚烧，与“用水”清洗的语境不符。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”的动作不能用水来完成，“用水吹泥”不成立。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚撞击，与“用水把泥”清洗的情境不符。"}], "explanations": {"冲": "冲干净：用水流把泥冲掉，与“用水”的语境相符。", "烧": "语义：“烧”指用火焚烧，与“用水”清洗的语境不符。", "吹": "搭配：“吹”的动作不能用水来完成，“用水吹泥”不成立。", "踢": "语义：“踢”指用脚撞击，与“用水把泥”清洗的情境不符。"}, "sentence_index": 0, "correct_answer": "冲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用干毛巾把杯子冲干净了。", "explanation": "这里应该用〈擦〉。冲要用水流，用干毛巾只能擦。"}, {"text": "他不小心把盘子冲碎了。", "explanation": "这里应该用〈摔〉。冲指用水浇或水流冲，不能表示撞击后摔碎。"}, {"text": "她用湿布冲干净了桌子。", "explanation": "这里应该用〈擦〉。冲需要水流，用湿布擦拭桌面应使用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86484, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冲", "is_correct": true, "explanation": "chōng（第一声）是本词，意思是用水浇洗，或水流猛烈冲走东西。"}, {"text": "中", "is_correct": false, "explanation": "zhōng（第一声）与 chōng 声母不同（zh 与 ch），意思是中间。"}, {"text": "葱", "is_correct": false, "explanation": "cōng（第一声）与 chōng 声母不同（c 与 ch），意思是葱，一种蔬菜。"}, {"text": "崇", "is_correct": false, "explanation": "chóng（第二声）与 chōng 声调不同，意思是崇拜。"}, {"text": "撑", "is_correct": false, "explanation": "chēng（第一声）与 chōng 韵母不同（e 与 o），意思是撑开。"}], "explanations": {"冲": "chōng（第一声）是本词，意思是用水浇洗，或水流猛烈冲走东西。", "中": "zhōng（第一声）与 chōng 声母不同（zh 与 ch），意思是中间。", "葱": "cōng（第一声）与 chōng 声母不同（c 与 ch），意思是葱，一种蔬菜。", "崇": "chóng（第二声）与 chōng 声调不同，意思是崇拜。", "撑": "chēng（第一声）与 chōng 韵母不同（e 与 o），意思是撑开。"}, "sentence_index": null, "correct_answer": "冲"}, "level_3": {"options": [{"text": "冲", "is_correct": true, "explanation": "冲走：水流猛烈地把桥冲离原处，与“大水”的语境相符。"}, {"text": "抬", "is_correct": false, "explanation": "语义：“抬”指用手或肩托起，大水不能抬走桥，与语境不符。"}, {"text": "扛", "is_correct": false, "explanation": "语义：“扛”指用肩膀承担，与“大水”的动作不符。"}, {"text": "窃", "is_correct": false, "explanation": "语域：“窃”为书面语且含偷盗义，与“大水”这一自然现象的语境不合。"}], "explanations": {"冲": "冲走：水流猛烈地把桥冲离原处，与“大水”的语境相符。", "抬": "语义：“抬”指用手或肩托起，大水不能抬走桥，与语境不符。", "扛": "语义：“扛”指用肩膀承担，与“大水”的动作不符。", "窃": "语域：“窃”为书面语且含偷盗义，与“大水”这一自然现象的语境不合。"}, "sentence_index": 6, "correct_answer": "冲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用扫帚把地上的土冲走了。", "explanation": "这里应该用〈扫〉。冲要靠水流，用扫帚应该说“扫”。"}, {"text": "他走路时冲了个跟头，摔在地上。", "explanation": "这里应该用〈栽〉。冲不能与“跟头”搭配表示跌倒，应说“栽了个跟头”。"}, {"text": "他把书冲进了书包。", "explanation": "这里应该用〈放〉。冲是向前猛闯或用水浇，不能表示把东西装进包里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把碗用水冲干净着。", "corrected_sentence": "我把碗用水冲干净了。", "error_description": "动态助词误用：“冲干净”是已完成的结果，应用“了”；写成“冲干净着”是错误，“着”表示持续状态，不表示动作完成。正确形式是“冲干净了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出门前，我把热水冲了个澡。", "corrected_sentence": "出门前，我用热水冲了个澡。", "error_description": "介词用法错误：表示工具要用“用”，不能用“把”；“把热水”不能被“冲”处置，正确形式是“用热水冲了个澡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
