INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "可是用在话的中间，说前面的话和后面的话不一样。", "primary_collocate": null, "pronunciation": "kě shì", "ipa": "kʰɤ˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服很好看，可是太贵了。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想去，可是今天没有时间。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说汉语，可是不会写汉字。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，可是他只穿了一件衬衫。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜看起来不好，可是味道很香。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等了很久，可是他还没来。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很聪明，可是不太努力。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子不大，可是很干净。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道答案，可是不想说。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想帮忙，可是不知道怎么做。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用在分句之间，前后两句意思不同的转折连词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "科室", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是医院或机关里按专业划分的部门。"}, {"text": "可是", "is_correct": true, "explanation": "可是：连词，用在前后两句之间，表示转折。"}, {"text": "客室", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是车厢或房间里供乘客、客人使用的空间。"}, {"text": "可数", "is_correct": false, "explanation": "shǔ（第三声）与 shì（第四声）韵母和声调都不同，意思是能够一个一个数出来的。"}, {"text": "可治", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是能够治好的。"}], "explanations": {"科室": "kě（第三声）与 kē（第一声）声调不同，意思是医院或机关里按专业划分的部门。", "可是": "可是：连词，用在前后两句之间，表示转折。", "客室": "kě（第三声）与 kè（第四声）声调不同，意思是车厢或房间里供乘客、客人使用的空间。", "可数": "shǔ（第三声）与 shì（第四声）韵母和声调都不同，意思是能够一个一个数出来的。", "可治": "shì 与 zhì 声母不同（sh 与 zh），意思是能够治好的。"}, "sentence_index": null, "correct_answer": "可是"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“太贵”不是“好看”的原因，句子说不通。"}, {"text": "可是", "is_correct": true, "explanation": "可是：“好看”与“太贵”前后意思相反，正好用于转折。"}, {"text": "否则", "is_correct": false, "explanation": "搭配：“否则”前面要有命令或条件，不能接在陈述句“这件衣服很好看”之后。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“好看”推不出“太贵”，逻辑不通。"}], "explanations": {"因为": "语义：“因为”表示原因，“太贵”不是“好看”的原因，句子说不通。", "可是": "可是：“好看”与“太贵”前后意思相反，正好用于转折。", "否则": "搭配：“否则”前面要有命令或条件，不能接在陈述句“这件衣服很好看”之后。", "所以": "语义：“所以”表示结果，“好看”推不出“太贵”，逻辑不通。"}, "sentence_index": 0, "correct_answer": "可是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很喜欢音乐，可是我每天都听音乐。", "explanation": "这里应该用〈所以〉。喜欢音乐和每天听音乐是因果关系，没有转折，“可是”不能用。"}, {"text": "他没来，可是他生病了。", "explanation": "这里应该用〈因为〉。表示原因要用“因为”，“可是”只表示转折，不表示原因。"}, {"text": "我先吃了饭，可是去上课了。", "explanation": "这里应该用〈然后〉。前后是先后顺序，没有转折，“可是”不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "课时", "is_correct": false, "explanation": "kè（第四声）与 kě（第三声）声调不同，shí（第二声）与 shì（第四声）声调也不同，意思是一节课的时间。"}, {"text": "可是", "is_correct": true, "explanation": "可是：连词，用在前后两句之间，表示转折。"}, {"text": "课室", "is_correct": false, "explanation": "kè（第四声）与 kě（第三声）声调不同，意思是教室。"}, {"text": "卡式", "is_correct": false, "explanation": "kǎ（第三声）与 kě（第三声）韵母不同（a 与 e），意思是磁带式的，如卡式录音机。"}], "explanations": {"课时": "kè（第四声）与 kě（第三声）声调不同，shí（第二声）与 shì（第四声）声调也不同，意思是一节课的时间。", "可是": "可是：连词，用在前后两句之间，表示转折。", "课室": "kè（第四声）与 kě（第三声）声调不同，意思是教室。", "卡式": "kǎ（第三声）与 kě（第三声）韵母不同（a 与 e），意思是磁带式的，如卡式录音机。"}, "sentence_index": null, "correct_answer": "可是"}, "level_3": {"options": [{"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示顺承或结果，“很聪明”与“不太努力”之间没有先后或因果关系。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，“很聪明”不能导致“不太努力”，句子不通。"}, {"text": "可是", "is_correct": true, "explanation": "可是：“很聪明”与“不太努力”前后意思相反，用于转折。"}, {"text": "要不然", "is_correct": false, "explanation": "搭配：“要不然”表示选择，前面要有命令或条件，不能接在陈述句“她很聪明”之后。"}], "explanations": {"于是": "语义：“于是”表示顺承或结果，“很聪明”与“不太努力”之间没有先后或因果关系。", "因此": "语义：“因此”表示结果，“很聪明”不能导致“不太努力”，句子不通。", "可是": "可是：“很聪明”与“不太努力”前后意思相反，用于转折。", "要不然": "搭配：“要不然”表示选择，前面要有命令或条件，不能接在陈述句“她很聪明”之后。"}, "sentence_index": 6, "correct_answer": "可是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边工作，可是一边学习。", "explanation": "这里应该删去〈可是〉。“一边……一边……”表示两件事同时进行，没有反差，不能加“可是”。"}, {"text": "我们吃完饭以后，可是去散步了。", "explanation": "这里应该删去〈可是〉。前后是先后顺序，没有反差，“可是”是多余的。"}, {"text": "他不仅会说汉语，可是还会写汉字。", "explanation": "这里应该用〈还〉，与“不仅”搭配表示递进；“可是”只表示转折，不能用在递进结构里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店很近，但是可是东西不便宜。", "corrected_sentence": "这家店很近，可是东西不便宜。", "error_description": "“可是”与“但是”叠用，两个转折连词重复。这里只需保留“可是”，应删去“但是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想去，可是可是没有钱。", "corrected_sentence": "我想去，可是没有钱。", "error_description": "“可是”被重复写成“可是可是”。“可是”只需出现一次，这里应写作“我想去，可是没有钱。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
