INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示转折的连词，引出与前面所说相反或有出入的意思。", "primary_collocate": null, "pronunciation": "kě shì", "ipa": "kʰɤ˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他说今天来，可是到现在也没有来。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给他打了电话。可是没有人接。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法很简单，可是没有人想到。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学了三年汉语，可是还不敢开口说。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格便宜，可是质量不太好。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他生气了。可是他一直在笑。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们很努力，可是结果不太好。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人很有钱，可是过得并不快乐。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪不大，可是懂得很多。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买那本书，可是书店已经关门了。", "target_word": "可是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "引出与前文相反或有出入的内容的转折连词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "客室", "is_correct": false, "explanation": "kě（第三声）与 kè（第四声）声调不同，意思是车厢或房间里供乘客、客人使用的空间。"}, {"text": "科室", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是医院或机关里按专业划分的部门。"}, {"text": "可是", "is_correct": true, "explanation": "可是：连词，表示转折，引出与前面所说相反或有出入的意思。"}, {"text": "可数", "is_correct": false, "explanation": "shǔ（第三声）与 shì（第四声）韵母和声调都不同，意思是能够一个一个数出来的。"}, {"text": "可治", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是能够治好的。"}], "explanations": {"客室": "kě（第三声）与 kè（第四声）声调不同，意思是车厢或房间里供乘客、客人使用的空间。", "科室": "kě（第三声）与 kē（第一声）声调不同，意思是医院或机关里按专业划分的部门。", "可是": "可是：连词，表示转折，引出与前面所说相反或有出入的意思。", "可数": "shǔ（第三声）与 shì（第四声）韵母和声调都不同，意思是能够一个一个数出来的。", "可治": "shì 与 zhì 声母不同（sh 与 zh），意思是能够治好的。"}, "sentence_index": null, "correct_answer": "可是"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“到现在也没来”不是“说今天来”的原因。"}, {"text": "可是", "is_correct": true, "explanation": "可是：“说今天来”与“到现在也没有来”前后有出入，用于转折。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示顺承或结果，与前后的反差不符。"}, {"text": "况且", "is_correct": false, "explanation": "语域：“况且”偏书面，且表示追加理由，与这里的转折不合。"}], "explanations": {"因为": "语义：“因为”表示原因，“到现在也没来”不是“说今天来”的原因。", "可是": "可是：“说今天来”与“到现在也没有来”前后有出入，用于转折。", "于是": "语义：“于是”表示顺承或结果，与前后的反差不符。", "况且": "语域：“况且”偏书面，且表示追加理由，与这里的转折不合。"}, "sentence_index": 0, "correct_answer": "可是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到了，可是堵车了。", "explanation": "这里应该用〈因为〉。表示原因要用“因为”，“可是”不表示原因。"}, {"text": "我们先吃了饭，可是去散步了。", "explanation": "这里应该用〈然后〉。前后是先后顺序，没有反差，用“可是”不通。"}, {"text": "如果你来，可是我就去。", "explanation": "这里应该用〈那么〉。“如果”后面引出结果要用“那么”或直接接结果，“可是”表示转折，不能引出结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“很努力”不能导致“结果不太好”，逻辑不通。"}, {"text": "可是", "is_correct": true, "explanation": "可是：“很努力”与“结果不太好”前后有反差，用于转折。"}, {"text": "否则", "is_correct": false, "explanation": "搭配：“否则”前面要有命令或条件，不能接在“我们很努力”这样的陈述句后面。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，“很努力”推不出“结果不太好”，句子不通。"}], "explanations": {"所以": "语义：“所以”表示结果，“很努力”不能导致“结果不太好”，逻辑不通。", "可是": "可是：“很努力”与“结果不太好”前后有反差，用于转折。", "否则": "搭配：“否则”前面要有命令或条件，不能接在“我们很努力”这样的陈述句后面。", "因此": "语义：“因此”表示结果，“很努力”推不出“结果不太好”，句子不通。"}, "sentence_index": 6, "correct_answer": "可是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很努力，可是很有礼貌。", "explanation": "这里应该用〈并且〉。前后是并列补充，没有转折，“可是”不适用。"}, {"text": "我喜欢看书，可是喜欢运动。", "explanation": "这里应该用〈而且〉。两项爱好是并列关系，没有反差，“可是”用在这里不通。"}, {"text": "为了健康，可是他每天跑步。", "explanation": "这里应该删去〈可是〉。“为了健康”后面直接接主语和动作，表示目的；“可是”只表示转折，前面没有相反的内容，所以不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题很难，但是可是他还是做出来了。", "corrected_sentence": "这道题很难，可是他还是做出来了。", "error_description": "“可是”与“但是”叠用，两个转折连词重复。这里只需保留“可是”，应删去“但是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他身体不好，可是可是很喜欢运动。", "corrected_sentence": "他身体不好，可是很喜欢运动。", "error_description": "“可是”重复使用，两个连词叠用。这里只需保留一个“可是”，应删去多余的那个，写作“他身体不好，可是很喜欢运动。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
