INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86488, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表演（戏剧、歌舞等）给观众看。", "primary_collocate": null, "pronunciation": "yǎn chū", "ipa": "jɛn˨˩˦ tʂʰu˥", "syllable_count": 2, "sentences": [{"text": "剧团今晚演出一出新戏。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在剧院演出京剧。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞蹈队去年到国外演出过。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她演出了一段很美的舞蹈。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐队明天晚上在体育馆演出。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那出话剧已经演出了一百多场。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们演出的歌舞很受观众欢迎。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧团准备在春节演出新节目。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手们在台上演出，观众都站起来了。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们在剧场里演出了三个小时。", "target_word": "演出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演出了", "label": "体标"}, {"form": "演出过", "label": "体标"}, {"form": "演出者", "label": "复合"}], "register": "中性", "sense_fingerprint": "把戏剧、歌舞等节目表演给观众看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演出", "is_correct": true, "explanation": "演出：表演节目给观众看，与“新戏”的语境相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语须为可饮用之物，“喝一出新戏”不成立。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指闭眼休息，与“新戏”的上演无关。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清洁，与“新戏”的上演无关。"}], "explanations": {"演出": "演出：表演节目给观众看，与“新戏”的语境相符。", "喝": "搭配：“喝”的宾语须为可饮用之物，“喝一出新戏”不成立。", "睡": "语义：“睡”指闭眼休息，与“新戏”的上演无关。", "打扫": "语义：“打扫”指清洁，与“新戏”的上演无关。"}, "sentence_index": 0, "correct_answer": "演出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校演出了一场运动会。", "explanation": "这里应该用〈举行〉。演出指上台给观众表演，不能用于运动会这类竞赛活动。"}, {"text": "她演出了一次考试。", "explanation": "这里应该用〈参加〉。演出指上台给观众表演，不能用于考试。"}, {"text": "工人演出了一座桥。", "explanation": "这里应该用〈修〉。演出指表演节目，不能用于建造或修理桥梁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演出", "is_correct": true, "explanation": "演出：表演歌舞给观众看，与“歌舞很受观众欢迎”的语境相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛掷，与“歌舞”不能搭配，语义不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象通常是物件或设施，不能修“歌舞”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指用布等摩擦去除污物，与“歌舞”无关。"}], "explanations": {"演出": "演出：表演歌舞给观众看，与“歌舞很受观众欢迎”的语境相符。", "扔": "语义：“扔”指抛掷，与“歌舞”不能搭配，语义不通。", "修": "搭配：“修”的对象通常是物件或设施，不能修“歌舞”。", "擦": "语义：“擦”指用布等摩擦去除污物，与“歌舞”无关。"}, "sentence_index": 6, "correct_answer": "演出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他演出了一本小说，很受欢迎。", "explanation": "这里应该用〈写〉。演出指表演给观众看，不能用于写作。"}, {"text": "我每天早上都演出一杯茶。", "explanation": "这里应该用〈喝〉。演出指表演节目，不能用于饮用。"}, {"text": "他演出了一盘棋，很快就赢了。", "explanation": "这里应该用〈下〉。演出指表演节目给观众看，不能用于下棋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "乐团把音乐厅演出了一场音乐会。", "corrected_sentence": "乐团在音乐厅演出了一场音乐会。", "error_description": "处置式误用：“音乐厅”是场所，不能作“把”字宾语，应以“在”引出场所，正确形式是“在音乐厅演出了一场音乐会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个剧团每年都会把各地演出。", "corrected_sentence": "这个剧团每年都会到各地演出。", "error_description": "处置式误用：“各地”是处所，不能作“把”字宾语；表示到达地点应用“到”，正确形式是“到各地演出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守旧", "is_correct": true, "explanation": "守旧：坚持旧的做法，不肯改变，与「改革」意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交换意见，与「改革」没有反义关系。"}, {"text": "鼓励", "is_correct": false, "explanation": "鼓励指激发或支持，不是「改革」的反义词。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与「改革」不构成反义。"}], "correct_answer": "守旧", "explanations": {"守旧": "守旧：坚持旧的做法，不肯改变，与「改革」意思相反。", "讨论": "讨论指交换意见，与「改革」没有反义关系。", "鼓励": "鼓励指激发或支持，不是「改革」的反义词。", "研究": "研究指深入探讨，与「改革」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守旧", "is_correct": true, "explanation": "守旧：坚持旧的做法，不肯改变，与「改革」意思相反。"}, {"text": "设计", "is_correct": false, "explanation": "设计指规划或绘制图样，与「改革」没有反义关系。"}, {"text": "批准", "is_correct": false, "explanation": "批准指同意，与「改革」不构成反义。"}, {"text": "登记", "is_correct": false, "explanation": "登记指记录备案，与「改革」无关。"}], "correct_answer": "守旧", "explanations": {"守旧": "守旧：坚持旧的做法，不肯改变，与「改革」意思相反。", "设计": "设计指规划或绘制图样，与「改革」没有反义关系。", "批准": "批准指同意，与「改革」不构成反义。", "登记": "登记指记录备案，与「改革」无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改革是把不好的老办法改掉，换成好办法。", "primary_collocate": null, "pronunciation": "gǎi gé", "ipa": "kai˨˩˦ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "学校改革了考试的老办法。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想改革旧的工作方法。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市正在改革公共交通的管理办法。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们改革了老办法，大家都很高兴。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板决定改革公司不好的管理办法。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须改革这个不好的排班办法。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里改革了种地的老办法，粮食多了。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院改革了看病的办法，病人不用排很长的队。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想把上课的老方式改革一下。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂改革以后，工人的工作轻松多了。", "target_word": "改革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改革了", "label": "体标（了）"}, {"form": "改革过", "label": "体标（过）"}, {"form": "改革者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把不好的老办法改掉，换成好办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd727e10f-1248-4124-9d4c-8b97d0ca17dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改革", "is_correct": true, "explanation": "改革：把不好的老办法改掉，换成好办法，符合「学校改革了考试的老办法」的语境。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」指创造从前没有的东西，「老办法」本来就已存在，不能说发明。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象是场所或展览，不能带「办法」作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "配价：「吃」的宾语必须是可以吃的东西，「办法」不能被吃。"}], "explanations": {"改革": "改革：把不好的老办法改掉，换成好办法，符合「学校改革了考试的老办法」的语境。", "发明": "语义：「发明」指创造从前没有的东西，「老办法」本来就已存在，不能说发明。", "参观": "搭配：「参观」的对象是场所或展览，不能带「办法」作宾语。", "吃": "配价：「吃」的宾语必须是可以吃的东西，「办法」不能被吃。"}, "sentence_index": 0, "correct_answer": "改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工厂改革了旧的厂房。", "explanation": "这里应该用〈改造〉。改革用于制度、办法，旧厂房这样的建筑要用改造。"}, {"text": "他改革了那个错误的答案。", "explanation": "这里应该用〈改正〉。改革用于制度、办法，错误的答案要用改正。"}, {"text": "他改革了那辆旧自行车。", "explanation": "这里应该用〈修理〉。改革用于制度、办法，自行车这样的物品要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改革", "is_correct": true, "explanation": "改革：去掉种地的老办法，换成新办法，粮食因此增多，符合语境。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」的对象是车船，不能带「办法」作宾语。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：「游览」针对风景名胜，不能说游览一种办法。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」只用于饮用液体，「老办法」不能被喝。"}], "explanations": {"改革": "改革：去掉种地的老办法，换成新办法，粮食因此增多，符合语境。", "驾驶": "搭配：「驾驶」的对象是车船，不能带「办法」作宾语。", "游览": "搭配：「游览」针对风景名胜，不能说游览一种办法。", "喝": "语义：「喝」只用于饮用液体，「老办法」不能被喝。"}, "sentence_index": 6, "correct_answer": "改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们改革了公司的规模。", "explanation": "这里应该用〈扩大〉。改革用于制度、办法，规模的增加要用扩大。"}, {"text": "他们改革了坏掉的灯泡。", "explanation": "这里应该用〈更换〉。改革用于制度、办法，坏掉的灯泡要用更换。"}, {"text": "他们改革了那场争吵。", "explanation": "这里应该用〈平息〉。改革用于制度、办法，争吵要用平息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校改革了了点名的老办法。", "corrected_sentence": "学校改革了点名的老办法。", "error_description": "动态助词「了」只用一次。这里在「改革」后重复用了两个「了」，说成「改革了了」，语法错误。正确的说法是「学校改革了点名的老办法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把种地的老办法改革。", "corrected_sentence": "他们把种地的老办法改革了。", "error_description": "「把」字句的动词后面不能是光杆动词，要加「了」等其他成分。这里「改革」后面什么也没有，句子不完整。应说「把种地的老办法改革了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
