INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86491, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牛是农场里的大动物，会给我们牛奶。", "primary_collocate": null, "pronunciation": "niú", "ipa": "njoʊ˧˥", "syllable_count": 1, "sentences": [{"text": "农场里有三头牛。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那头牛在草地上吃草。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头牛每天早上都给我们很多奶。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩第一次看到牛，有点害怕。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛的个子很大，可是很安静。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上去给牛喂草。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有一头黑白的牛。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在农场里看见了一群牛。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛喜欢吃草，不吃肉。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，爷爷把牛带回家。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "头", "label": "量词"}, {"form": "奶牛", "label": "复合"}, {"form": "黄牛", "label": "复合"}], "register": "中性", "sense_fingerprint": "农场里产奶的大动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86491, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牛", "is_correct": true, "explanation": "牛（niú）是本词，指农场里产奶的大动物。"}, {"text": "流", "is_correct": false, "explanation": "流（liú）与 niú 声母不同（l 与 n），意思是流动。"}, {"text": "扭", "is_correct": false, "explanation": "扭（niǔ，第三声）与 niú（第二声）声调不同，意思是扭动。"}, {"text": "妞", "is_correct": false, "explanation": "妞（niū，第一声）与 niú（第二声）声调不同，口语中指女孩。"}], "explanations": {"牛": "牛（niú）是本词，指农场里产奶的大动物。", "流": "流（liú）与 niú 声母不同（l 与 n），意思是流动。", "扭": "扭（niǔ，第三声）与 niú（第二声）声调不同，意思是扭动。", "妞": "妞（niū，第一声）与 niú（第二声）声调不同，口语中指女孩。"}, "sentence_index": null, "correct_answer": "牛"}, "level_3": {"options": [{"text": "牛", "is_correct": true, "explanation": "“牛”是农场里的大型家畜，可以用“头”计数，与“三头”搭配，句子成立。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：农场里一般不养老虎，与“农场里有”的语境相矛盾。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体形庞大，农场里一般不饲养，句子不符合常识。"}, {"text": "狮子", "is_correct": false, "explanation": "语义：狮子是野生猛兽，不会出现在农场里。"}], "explanations": {"牛": "“牛”是农场里的大型家畜，可以用“头”计数，与“三头”搭配，句子成立。", "老虎": "语义：农场里一般不养老虎，与“农场里有”的语境相矛盾。", "大象": "体貌：大象体形庞大，农场里一般不饲养，句子不符合常识。", "狮子": "语义：狮子是野生猛兽，不会出现在农场里。"}, "sentence_index": 0, "correct_answer": "牛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在农场看见了一张牛。", "explanation": "这里应该用〈头〉。“张”用于纸、桌子等平面的东西，不用于牛。"}, {"text": "我们农场里养了三本牛，每天给我们很多奶。", "explanation": "这里应该用〈头〉。“本”用于书，不用于牛。"}, {"text": "我每天早上喝一杯牛，很有营养。", "explanation": "这里应该用〈牛奶〉。〈牛〉指动物，不单独指牛奶，“喝一杯牛”不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛", "is_correct": true, "explanation": "“牛”是河边常见的黑白花家畜，与“黑白的”搭配，句子成立。"}, {"text": "猩猩", "is_correct": false, "explanation": "语义：猩猩多为棕黑色，且不在河边的草地上生活，与“黑白的”不符。"}, {"text": "骆驼", "is_correct": false, "explanation": "体貌：骆驼多为棕黄色，外形与“黑白的”不相符。"}, {"text": "蒜", "is_correct": false, "explanation": "语义：蒜是植物，不是有颜色的动物，不能“在河边”走动。"}], "explanations": {"牛": "“牛”是河边常见的黑白花家畜，与“黑白的”搭配，句子成立。", "猩猩": "语义：猩猩多为棕黑色，且不在河边的草地上生活，与“黑白的”不符。", "骆驼": "体貌：骆驼多为棕黄色，外形与“黑白的”不相符。", "蒜": "语义：蒜是植物，不是有颜色的动物，不能“在河边”走动。"}, "sentence_index": 6, "correct_answer": "牛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天买了一个牛。", "explanation": "这里应该用〈头〉。牛作量词用“头”，“个”不能用于牛。"}, {"text": "这双牛很好穿，我每天都穿。", "explanation": "〈牛〉指动物，不指鞋，这里应说〈鞋〉。"}, {"text": "我们家养了一匹牛。", "explanation": "这里应该用〈头〉。“匹”用于马、骡等，不用于牛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草地上有三张牛在吃草。", "corrected_sentence": "草地上有三头牛在吃草。", "error_description": "量词错误：“牛”的量词是“头”，“张”用于纸、桌子等。错误形式是“三张牛”，正确形式是“三头牛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河边有两头牛们。", "corrected_sentence": "河边有两头牛。", "error_description": "“们”只用于指人，不能加在动物名词“牛”后面，数量词修饰时也不需要“们”。错误写法是“牛们”，正确写法是“两头牛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
