INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "哺乳动物，身体大，力气大，可耕田，母牛产奶。", "primary_collocate": null, "pronunciation": "niú", "ipa": "njoʊ˧˥", "syllable_count": 1, "sentences": [{"text": "牛的力气很大，可以帮农民耕田。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前农民用牛耕田。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛是哺乳动物，不是鸟。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头牛的身体比马还大。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的牛每天都能产二十公斤奶。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛拉着车，慢慢走在田里。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那头牛力气大，一个人拉不住它。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛有两只角，身体又大又重。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，农民赶着牛去田里。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛不会飞，但是能走很远的路。", "target_word": "牛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "头", "label": "量词"}, {"form": "奶牛", "label": "复合"}, {"form": "黄牛", "label": "复合"}], "register": "中性", "sense_fingerprint": "力气大可耕田的哺乳动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86492, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牛", "is_correct": true, "explanation": "牛（niú）是本词，指力气大、可耕田的哺乳动物。"}, {"text": "流", "is_correct": false, "explanation": "流（liú）与 niú 声母不同（l 与 n），意思是流动。"}, {"text": "扭", "is_correct": false, "explanation": "扭（niǔ，第三声）与 niú（第二声）声调不同，意思是扭动。"}, {"text": "妞", "is_correct": false, "explanation": "妞（niū，第一声）与 niú（第二声）声调不同，口语中指女孩。"}], "explanations": {"牛": "牛（niú）是本词，指力气大、可耕田的哺乳动物。", "流": "流（liú）与 niú 声母不同（l 与 n），意思是流动。", "扭": "扭（niǔ，第三声）与 niú（第二声）声调不同，意思是扭动。", "妞": "妞（niū，第一声）与 niú（第二声）声调不同，口语中指女孩。"}, "sentence_index": null, "correct_answer": "牛"}, "level_3": {"options": [{"text": "牛", "is_correct": true, "explanation": "“牛”力气大，能帮农民耕田，句子成立。"}, {"text": "兔子", "is_correct": false, "explanation": "语义：兔子力气小，不能用来耕田，与“力气很大”相矛盾。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "体貌：蚂蚁身体很小，力气再大也不能帮农民耕田。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠体型小，不能用来耕田。"}], "explanations": {"牛": "“牛”力气大，能帮农民耕田，句子成立。", "兔子": "语义：兔子力气小，不能用来耕田，与“力气很大”相矛盾。", "蚂蚁": "体貌：蚂蚁身体很小，力气再大也不能帮农民耕田。", "老鼠": "语义：老鼠体型小，不能用来耕田。"}, "sentence_index": 0, "correct_answer": "牛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有三本牛，每天都去喂。", "explanation": "这里应该用〈头〉。“本”用于书，不用于牛。"}, {"text": "我每天早上喝一杯牛，很有营养。", "explanation": "这里应该用〈牛奶〉。〈牛〉指动物，不单独指牛奶，“喝一杯牛”不能这样说。"}, {"text": "我们家养了一张牛，每天耕田。", "explanation": "这里应该用〈头〉。“张”用于纸、桌子等平面的东西，不用于牛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛", "is_correct": true, "explanation": "“牛”力气大，一个人拉不住，与“那头”搭配，句子成立。"}, {"text": "蒜", "is_correct": false, "explanation": "语义：大蒜是植物，没有力气，也不能被人拉住。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，没有力气，也不会被人拉住。"}, {"text": "大葱", "is_correct": false, "explanation": "语义：大葱是蔬菜，没有力气，也不会被人拉住。"}], "explanations": {"牛": "“牛”力气大，一个人拉不住，与“那头”搭配，句子成立。", "蒜": "语义：大蒜是植物，没有力气，也不能被人拉住。", "白菜": "语义：白菜是蔬菜，没有力气，也不会被人拉住。", "大葱": "语义：大葱是蔬菜，没有力气，也不会被人拉住。"}, "sentence_index": 6, "correct_answer": "牛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村里有一位牛。", "explanation": "这里应该用〈头〉。“位”用于人，不用于牛。"}, {"text": "这双牛很暖和，我冬天都穿。", "explanation": "〈牛〉指动物，不指鞋，这里应说〈鞋〉。"}, {"text": "我们家养了一个牛。", "explanation": "这里应该用〈头〉。“个”不用于牛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "以前农民用一张牛耕田。", "corrected_sentence": "以前农民用一头牛耕田。", "error_description": "量词错误：“牛”用“头”计量，“张”用于纸、桌子等。错误形式是“一张牛”，正确形式是“一头牛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "田里有两把牛在耕地。", "corrected_sentence": "田里有两头牛在耕地。", "error_description": "量词错误：“牛”用“头”计量，“把”用于有把手的东西。错误形式是“两把牛”，正确形式是“两头牛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
