INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86493, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "米是用来量东西有多长的一个单位。", "primary_collocate": null, "pronunciation": "mǐ", "ipa": "mi˨˩˦", "syllable_count": 1, "sentences": [{"text": "这条路有三百米长。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明跑了一百米。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子长两米。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校离我家只有五百米。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间有十米长。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的水有两米深。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往前走了二十米。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树有十米高。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请往前走五十米，然后向左拐。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池长五十米，宽二十米。", "target_word": "米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "厘米", "label": "复合"}, {"form": "千米", "label": "复合"}, {"form": "平方米", "label": "复合"}], "register": "中性", "sense_fingerprint": "量长短的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c5d38-188c-4474-8f42-65925038992f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86493, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "米", "is_correct": true, "explanation": "米（mǐ）：长度单位，一米等于一百厘米。"}, {"text": "你", "is_correct": false, "explanation": "你（nǐ）与米（mǐ）声母不同（n 与 m），意思是“你”。"}, {"text": "里", "is_correct": false, "explanation": "里（lǐ）与米（mǐ）声母不同（l 与 m），意思是“里面”。"}, {"text": "笔", "is_correct": false, "explanation": "笔（bǐ）与米（mǐ）声母不同（b 与 m），意思是“笔”。"}, {"text": "迷", "is_correct": false, "explanation": "迷（mí）与米（mǐ）声调不同（第二声与第三声），意思是“迷恋”。"}], "explanations": {"米": "米（mǐ）：长度单位，一米等于一百厘米。", "你": "你（nǐ）与米（mǐ）声母不同（n 与 m），意思是“你”。", "里": "里（lǐ）与米（mǐ）声母不同（l 与 m），意思是“里面”。", "笔": "笔（bǐ）与米（mǐ）声母不同（b 与 m），意思是“笔”。", "迷": "迷（mí）与米（mǐ）声调不同（第二声与第三声），意思是“迷恋”。"}, "sentence_index": null, "correct_answer": "米"}, "level_3": {"options": [{"text": "米", "is_correct": true, "explanation": "米：长度单位，“三百米长”可以描述一条路的长度。"}, {"text": "厘米", "is_correct": false, "explanation": "语义：“三百厘米”只有三米，不能用来形容一条路的长度。"}, {"text": "毫米", "is_correct": false, "explanation": "语义：“三百毫米”只有三十厘米，远远不够描述一条路。"}, {"text": "平方米", "is_correct": false, "explanation": "搭配：“平方米”是面积单位，不能用来量长度。"}], "explanations": {"米": "米：长度单位，“三百米长”可以描述一条路的长度。", "厘米": "语义：“三百厘米”只有三米，不能用来形容一条路的长度。", "毫米": "语义：“三百毫米”只有三十厘米，远远不够描述一条路。", "平方米": "搭配：“平方米”是面积单位，不能用来量长度。"}, "sentence_index": 0, "correct_answer": "米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书卖三十米。", "explanation": "这里应该用〈元〉。米是长度单位，说价钱要用元。"}, {"text": "这间屋子的面积是二十米。", "explanation": "这里应该用〈平方米〉。米是长度单位，说面积要用平方米。"}, {"text": "我每天喝一米水。", "explanation": "这里应该用〈升〉。米只用来量长度，量液体要用升。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86493, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "米", "is_correct": true, "explanation": "米（mǐ）：长度单位，一米等于一百厘米。"}, {"text": "体", "is_correct": false, "explanation": "体（tǐ）与米（mǐ）声母不同（t 与 m），意思是“身体”。"}, {"text": "底", "is_correct": false, "explanation": "底（dǐ）与米（mǐ）声母不同（d 与 m），意思是“底部”。"}, {"text": "密", "is_correct": false, "explanation": "密（mì）与米（mǐ）声调不同（第四声与第三声），意思是“密集”。"}, {"text": "礼", "is_correct": false, "explanation": "礼（lǐ）与米（mǐ）声母不同（l 与 m），意思是“礼物”。"}], "explanations": {"米": "米（mǐ）：长度单位，一米等于一百厘米。", "体": "体（tǐ）与米（mǐ）声母不同（t 与 m），意思是“身体”。", "底": "底（dǐ）与米（mǐ）声母不同（d 与 m），意思是“底部”。", "密": "密（mì）与米（mǐ）声调不同（第四声与第三声），意思是“密集”。", "礼": "礼（lǐ）与米（mǐ）声母不同（l 与 m），意思是“礼物”。"}, "sentence_index": null, "correct_answer": "米"}, "level_3": {"options": [{"text": "米", "is_correct": true, "explanation": "米：长度单位，“往前走了二十米”描述的是步行的距离。"}, {"text": "度", "is_correct": false, "explanation": "语义：“度”用于温度或角度，不能用来量步行的距离。"}, {"text": "千克", "is_correct": false, "explanation": "语义：“千克”是重量单位，不能用来量走路的距离。"}, {"text": "升", "is_correct": false, "explanation": "搭配：“升”是容积单位，不能用于距离。"}], "explanations": {"米": "米：长度单位，“往前走了二十米”描述的是步行的距离。", "度": "语义：“度”用于温度或角度，不能用来量步行的距离。", "千克": "语义：“千克”是重量单位，不能用来量走路的距离。", "升": "搭配：“升”是容积单位，不能用于距离。"}, "sentence_index": 6, "correct_answer": "米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果重两米。", "explanation": "这里应该用〈千克〉。米是长度单位，称重量要用千克。"}, {"text": "今天气温零下五米。", "explanation": "这里应该用〈度〉。米只量长度，量温度要用度。"}, {"text": "他今年十米了。", "explanation": "这里应该用〈岁〉。米不能用来计算年龄，说年纪要用岁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的河面宽两百个米。", "corrected_sentence": "这条河的河面宽两百米。", "error_description": "错误：“两百个米”。正确：“两百米”。“米”是长度单位，前面的数量不加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座塔有三十斤高。", "corrected_sentence": "这座塔有三十米高。", "error_description": "错误：“三十斤高”。正确：“三十米高”。“斤”是重量单位，不能量高度；说高度要用长度单位“米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
