INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "米", "is_correct": true, "explanation": "米（mǐ）：长度的基本单位，一米等于一百厘米。"}, {"text": "你", "is_correct": false, "explanation": "你（nǐ）与米（mǐ）声母不同（n 与 m），意思是“你”。"}, {"text": "笔", "is_correct": false, "explanation": "笔（bǐ）与米（mǐ）声母不同（b 与 m），意思是“笔”。"}, {"text": "底", "is_correct": false, "explanation": "底（dǐ）与米（mǐ）声母不同（d 与 m），意思是“底部”。"}, {"text": "迷", "is_correct": false, "explanation": "迷（mí）与米（mǐ）声调不同（第二声与第三声），意思是“迷恋”。"}], "explanations": {"米": "米（mǐ）：长度的基本单位，一米等于一百厘米。", "你": "你（nǐ）与米（mǐ）声母不同（n 与 m），意思是“你”。", "笔": "笔（bǐ）与米（mǐ）声母不同（b 与 m），意思是“笔”。", "底": "底（dǐ）与米（mǐ）声母不同（d 与 m），意思是“底部”。", "迷": "迷（mí）与米（mǐ）声调不同（第二声与第三声），意思是“迷恋”。"}, "sentence_index": null, "correct_answer": "米"}, "level_3": {"options": [{"text": "米", "is_correct": true, "explanation": "米：长度的基本单位，“一米等于一百厘米”是正确的换算。"}, {"text": "厘米", "is_correct": false, "explanation": "语义：“一厘米等于一百厘米”不成立，一厘米本身只是一百分之一米。"}, {"text": "千米", "is_correct": false, "explanation": "语义：“一千米”远大于“一百厘米”，这样换算是错的。"}, {"text": "平方米", "is_correct": false, "explanation": "搭配：“平方米”是面积单位，不能与“厘米”这样的长度单位直接换算。"}], "explanations": {"米": "米：长度的基本单位，“一米等于一百厘米”是正确的换算。", "厘米": "语义：“一厘米等于一百厘米”不成立，一厘米本身只是一百分之一米。", "千米": "语义：“一千米”远大于“一百厘米”，这样换算是错的。", "平方米": "搭配：“平方米”是面积单位，不能与“厘米”这样的长度单位直接换算。"}, "sentence_index": 0, "correct_answer": "米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶牛奶有两米。", "explanation": "这里应该用〈升〉。米是长度单位，量液体要用升。"}, {"text": "这箱橘子重三米。", "explanation": "这里应该用〈千克〉。米是长度单位，称重量要用千克。"}, {"text": "今天最高温度是三十米。", "explanation": "这里应该用〈度〉。米不能用来量温度，温度要用度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86494, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "米", "is_correct": true, "explanation": "米（mǐ）：长度的基本单位，一米等于一百厘米。"}, {"text": "体", "is_correct": false, "explanation": "体（tǐ）与米（mǐ）声母不同（t 与 m），意思是“身体”。"}, {"text": "里", "is_correct": false, "explanation": "里（lǐ）与米（mǐ）声母不同（l 与 m），意思是“里面”。"}, {"text": "密", "is_correct": false, "explanation": "密（mì）与米（mǐ）声调不同（第四声与第三声），意思是“密集”。"}, {"text": "礼", "is_correct": false, "explanation": "礼（lǐ）与米（mǐ）声母不同（l 与 m），意思是“礼物”。"}], "explanations": {"米": "米（mǐ）：长度的基本单位，一米等于一百厘米。", "体": "体（tǐ）与米（mǐ）声母不同（t 与 m），意思是“身体”。", "里": "里（lǐ）与米（mǐ）声母不同（l 与 m），意思是“里面”。", "密": "密（mì）与米（mǐ）声调不同（第四声与第三声），意思是“密集”。", "礼": "礼（lǐ）与米（mǐ）声母不同（l 与 m），意思是“礼物”。"}, "sentence_index": null, "correct_answer": "米"}, "level_3": {"options": [{"text": "米", "is_correct": true, "explanation": "米：长度单位，“三米的绳子”是常见的说法。"}, {"text": "岁", "is_correct": false, "explanation": "搭配：“岁”用来说年龄，不能用来量绳子的长度。"}, {"text": "度", "is_correct": false, "explanation": "搭配：“度”用于温度或角度，不能用来量绳子。"}, {"text": "升", "is_correct": false, "explanation": "搭配：“升”是容积单位，不能用来量绳子的长度。"}], "explanations": {"米": "米：长度单位，“三米的绳子”是常见的说法。", "岁": "搭配：“岁”用来说年龄，不能用来量绳子的长度。", "度": "搭配：“度”用于温度或角度，不能用来量绳子。", "升": "搭配：“升”是容积单位，不能用来量绳子的长度。"}, "sentence_index": 6, "correct_answer": "米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋卖三百米。", "explanation": "这里应该用〈元〉。米是长度单位，说价钱要用元。"}, {"text": "我的爷爷已经八十米了。", "explanation": "这里应该用〈岁〉。米不能用来计算年龄，说年纪要用岁。"}, {"text": "我每天晚上睡八米。", "explanation": "这里应该用〈小时〉。米只量长度，计算睡眠时间要用小时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的身高是一个米七。", "corrected_sentence": "我的身高是一米七。", "error_description": "错误：“一个米七”。正确：“一米七”。“米”前面的数词直接接“米”，不能加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了米五的布。", "corrected_sentence": "我买了五米的布。", "error_description": "错误：“米五的布”，词序颠倒。正确：“五米的布”。“米”作量词，要放在数词之后，不能放在数词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
