INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86495, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由着是别人想怎么样，就让他怎么样。", "primary_collocate": null, "pronunciation": "yóu zhe", "ipa": "joʊ˧˥ tʂə", "syllable_count": 2, "sentences": [{"text": "奶奶很喜欢孙子，什么都由着他。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐想去哪儿，爸妈都由着她。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想怎么做就怎么做，我由着你。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想玩多久，妈妈就由着他玩多久。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太爱小狗了，由着它睡在床上。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板由着客人挑，想买什么都行。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我不管了，由着你们吧。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他由着朋友说，一句话也不回。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天由着我们选座位。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸由着儿子画满墙，一点也不生气。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "别人想怎样就让他怎样，顺着对方的意愿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86495, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "由着", "is_correct": true, "explanation": "由着（yóu zhe）：听凭、任凭，与题目读音一致。"}, {"text": "有着", "is_correct": false, "explanation": "有着 yǒu zhe 与 yóu zhe 第一音节声调不同（第三声与第二声），意思是具有。"}, {"text": "悠着", "is_correct": false, "explanation": "悠着 yōu zhe 与 yóu zhe 第一音节声调不同（第一声），意思是慢慢来、有分寸。"}, {"text": "诱着", "is_correct": false, "explanation": "诱着 yòu zhe 与 yóu zhe 第一音节声调不同（第四声），意思是引诱。"}], "explanations": {"由着": "由着（yóu zhe）：听凭、任凭，与题目读音一致。", "有着": "有着 yǒu zhe 与 yóu zhe 第一音节声调不同（第三声与第二声），意思是具有。", "悠着": "悠着 yōu zhe 与 yóu zhe 第一音节声调不同（第一声），意思是慢慢来、有分寸。", "诱着": "诱着 yòu zhe 与 yóu zhe 第一音节声调不同（第四声），意思是引诱。"}, "sentence_index": null, "correct_answer": "由着"}, "level_3": {"options": [{"text": "由着", "is_correct": true, "explanation": "由着：听凭、顺着对方的意愿，与“很喜欢孙子”相符。"}, {"text": "拦", "is_correct": false, "explanation": "语义：“拦”是阻止，与“很喜欢孙子，什么都……”相矛盾。"}, {"text": "罚", "is_correct": false, "explanation": "语义：“罚”是惩戒，与“很喜欢孙子”的语境不协调。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责骂，与“很喜欢孙子”的语境相矛盾。"}], "explanations": {"由着": "由着：听凭、顺着对方的意愿，与“很喜欢孙子”相符。", "拦": "语义：“拦”是阻止，与“很喜欢孙子，什么都……”相矛盾。", "罚": "语义：“罚”是惩戒，与“很喜欢孙子”的语境不协调。", "骂": "语义：“骂”是责骂，与“很喜欢孙子”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "由着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我由着那种吵闹的环境。", "explanation": "这里应该用〈讨厌〉。由着表示听凭、顺从，不表示厌恶。"}, {"text": "我们一直在由着天晴。", "explanation": "这里应该用〈等待〉。由着表示听凭，不表示等候某件事发生。"}, {"text": "这位工程师由着那批钢材建了一座桥。", "explanation": "这里应该用〈利用〉。由着表示听凭、任凭对方，不表示拿某物来做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86495, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "由着", "is_correct": true, "explanation": "由着（yóu zhe）：听凭、任凭，与题目读音一致。"}, {"text": "谋着", "is_correct": false, "explanation": "谋着 móu zhe 与 yóu zhe 声母不同（m 与 y），意思是图谋。"}, {"text": "投着", "is_correct": false, "explanation": "投着 tóu zhe 与 yóu zhe 声母不同（t 与 y），意思是投向、投入。"}, {"text": "揉着", "is_correct": false, "explanation": "揉着 róu zhe 与 yóu zhe 声母不同（r 与 y），声调相同，意思是搓、按。"}, {"text": "愁着", "is_correct": false, "explanation": "愁着 chóu zhe 与 yóu zhe 声母不同（ch 与 y），声调相同，意思是发愁。"}], "explanations": {"由着": "由着（yóu zhe）：听凭、任凭，与题目读音一致。", "谋着": "谋着 móu zhe 与 yóu zhe 声母不同（m 与 y），意思是图谋。", "投着": "投着 tóu zhe 与 yóu zhe 声母不同（t 与 y），意思是投向、投入。", "揉着": "揉着 róu zhe 与 yóu zhe 声母不同（r 与 y），声调相同，意思是搓、按。", "愁着": "愁着 chóu zhe 与 yóu zhe 声母不同（ch 与 y），声调相同，意思是发愁。"}, "sentence_index": null, "correct_answer": "由着"}, "level_3": {"options": [{"text": "由着", "is_correct": true, "explanation": "由着：听凭你们自行处理，与“我不管了”一致。"}, {"text": "逼着", "is_correct": false, "explanation": "语义：“逼着”是强迫，与“我不管了”的态度相反。"}, {"text": "监督", "is_correct": false, "explanation": "语义：“监督”是管束，与“我不管了”矛盾。"}, {"text": "谏", "is_correct": false, "explanation": "语域：“谏”是文言式的劝谏用语，放在这句口语里不搭。"}], "explanations": {"由着": "由着：听凭你们自行处理，与“我不管了”一致。", "逼着": "语义：“逼着”是强迫，与“我不管了”的态度相反。", "监督": "语义：“监督”是管束，与“我不管了”矛盾。", "谏": "语域：“谏”是文言式的劝谏用语，放在这句口语里不搭。"}, "sentence_index": 6, "correct_answer": "由着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "气温由着季节的变化而升高。", "explanation": "这里应该用〈随着〉。由着表示听凭、任凭，不表示事物随另一事物而变化。"}, {"text": "他由着全部责任。", "explanation": "这里应该用〈承担〉。由着表示听任，不表示担负责任。"}, {"text": "孩子们由着节目。", "explanation": "这里应该用〈观看〉。由着表示听凭，不表示看演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86495, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐由着过我看电视，从不催我。", "corrected_sentence": "姐姐由着我看电视，从不催我。", "error_description": "错误：“由着”后多加了“过”，写成“由着过”。正确：应为“由着我看电视”。“着”表示持续的听凭状态，“过”表示经历，二者不能并用于“由着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸由着的我们玩，从不管。", "corrected_sentence": "爸爸由着我们玩，从不管。", "error_description": "“由着”后直接接宾语，中间不能加“的”；应为“由着我们玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
