INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86496, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听凭；任凭。", "primary_collocate": null, "pronunciation": "yóu zhe", "ipa": "joʊ˧˥ tʂə", "syllable_count": 2, "sentences": [{"text": "妈妈由着孩子自己选衣服。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师由着我们自己决定。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不管弟弟，由着他玩游戏。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能总由着自己的脾气。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸由着她去，没有拦她。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说别由着孩子吃太多糖。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他由着事情发展，什么也不做。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司由着员工选择上班时间。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别由着他乱花钱。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她由着眼泪流下来，没有擦。", "target_word": "由着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "听凭、任凭某人或某事自行发展，不加干涉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86496, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "由着", "is_correct": true, "explanation": "由着（yóu zhe）：听凭、任凭，与题目读音一致。"}, {"text": "有着", "is_correct": false, "explanation": "有着 yǒu zhe 与 yóu zhe 第一音节声调不同（第三声与第二声），意思是具有。"}, {"text": "悠着", "is_correct": false, "explanation": "悠着 yōu zhe 与 yóu zhe 第一音节声调不同（第一声），意思是慢慢来、有分寸。"}, {"text": "诱着", "is_correct": false, "explanation": "诱着 yòu zhe 与 yóu zhe 第一音节声调不同（第四声），意思是引诱。"}], "explanations": {"由着": "由着（yóu zhe）：听凭、任凭，与题目读音一致。", "有着": "有着 yǒu zhe 与 yóu zhe 第一音节声调不同（第三声与第二声），意思是具有。", "悠着": "悠着 yōu zhe 与 yóu zhe 第一音节声调不同（第一声），意思是慢慢来、有分寸。", "诱着": "诱着 yòu zhe 与 yóu zhe 第一音节声调不同（第四声），意思是引诱。"}, "sentence_index": null, "correct_answer": "由着"}, "level_3": {"options": [{"text": "由着", "is_correct": true, "explanation": "由着：听凭、任凭，允许孩子自己做主，与句意相符。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代人去做，与后面的“孩子自己选”矛盾。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”与“由着”的听凭义相反，与句意矛盾。"}, {"text": "赐", "is_correct": false, "explanation": "语域：“赐”是书面、带施予意味的词，用于母亲管孩子选衣服的口语语境不协调。"}], "explanations": {"由着": "由着：听凭、任凭，允许孩子自己做主，与句意相符。", "替": "语义：“替”表示代人去做，与后面的“孩子自己选”矛盾。", "禁止": "语义：“禁止”与“由着”的听凭义相反，与句意矛盾。", "赐": "语域：“赐”是书面、带施予意味的词，用于母亲管孩子选衣服的口语语境不协调。"}, "sentence_index": 0, "correct_answer": "由着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵必须由着上级的命令。", "explanation": "这里应该用〈服从〉。由着表示听凭、任凭对方自行处理，不表示遵照执行命令。"}, {"text": "这座老城由着七百年的历史。", "explanation": "这里应该用〈拥有〉。由着没有“具有”的意思，只表示听凭。"}, {"text": "他很快由着作业。", "explanation": "这里应该用〈完成〉。由着表示听凭，不表示做完某件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86496, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "由着", "is_correct": true, "explanation": "由着（yóu zhe）：听凭、任凭，与题目读音一致。"}, {"text": "谋着", "is_correct": false, "explanation": "谋着 móu zhe 与 yóu zhe 声母不同（m 与 y），意思是图谋。"}, {"text": "投着", "is_correct": false, "explanation": "投着 tóu zhe 与 yóu zhe 声母不同（t 与 y），意思是投向、投入。"}, {"text": "揉着", "is_correct": false, "explanation": "揉着 róu zhe 与 yóu zhe 声母不同（r 与 y），声调相同，意思是搓、按。"}, {"text": "愁着", "is_correct": false, "explanation": "愁着 chóu zhe 与 yóu zhe 声母不同（ch 与 y），声调相同，意思是发愁。"}], "explanations": {"由着": "由着（yóu zhe）：听凭、任凭，与题目读音一致。", "谋着": "谋着 móu zhe 与 yóu zhe 声母不同（m 与 y），意思是图谋。", "投着": "投着 tóu zhe 与 yóu zhe 声母不同（t 与 y），意思是投向、投入。", "揉着": "揉着 róu zhe 与 yóu zhe 声母不同（r 与 y），声调相同，意思是搓、按。", "愁着": "愁着 chóu zhe 与 yóu zhe 声母不同（ch 与 y），声调相同，意思是发愁。"}, "sentence_index": null, "correct_answer": "由着"}, "level_3": {"options": [{"text": "由着", "is_correct": true, "explanation": "由着：听凭事情自然发展，与“什么也不做”一致。"}, {"text": "推动", "is_correct": false, "explanation": "语义：“推动”要求出力促成，与“什么也不做”矛盾。"}, {"text": "促进", "is_correct": false, "explanation": "语义：“促进”是积极促使发展，与“什么也不做”相冲突。"}, {"text": "参与", "is_correct": false, "explanation": "搭配：“参与”需要以活动、工作等为对象，“事情发展”不是可参与的对象。"}], "explanations": {"由着": "由着：听凭事情自然发展，与“什么也不做”一致。", "推动": "语义：“推动”要求出力促成，与“什么也不做”矛盾。", "促进": "语义：“促进”是积极促使发展，与“什么也不做”相冲突。", "参与": "搭配：“参与”需要以活动、工作等为对象，“事情发展”不是可参与的对象。"}, "sentence_index": 6, "correct_answer": "由着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我非常由着你的帮助。", "explanation": "这里应该用〈感谢〉。由着表示听凭对方自行其是，不能用来表达感激。"}, {"text": "他每天由着房间。", "explanation": "这里应该用〈打扫〉。由着没有清理的意思，不能接“房间”表示整理。"}, {"text": "这个月的销量由着广告投放增长。", "explanation": "这里应该用〈随着〉。由着表示听凭、任凭，不表示事物随另一事物而变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶总是由着了我的性子。", "corrected_sentence": "奶奶总是由着我的性子。", "error_description": "错误：“由着”后多加了“了”，写成“由着了”。正确：应为“由着我的性子”。“着”已表示持续的听凭状态，不能再与“了”并用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸由着的我选课，从来不管。", "corrected_sentence": "爸爸由着我选课，从来不管。", "error_description": "错误：“的”插在“由着”与宾语“我”之间，写成“由着的我”。正确：应为“由着我选课”，“由着”后直接接宾语，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
