INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "系列是一件接着一件、互相有关系的一些东西。", "primary_collocate": null, "pronunciation": "xì liè", "ipa": "ɕi˥˩ lie˥˩", "syllable_count": 2, "sentences": [{"text": "这个月，公司做了一系列新计划。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了一系列问题，老师都回答了。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为新同学办了一系列活动。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一系列的变化让大家很吃惊。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生做了一系列检查，才找到原因。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府公布了一系列新办法。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一系列好消息让他笑了一整天。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛前，球队有一系列准备工作。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，市里采取了一系列措施。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了一系列理由，但我不信。", "target_word": "系列", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一系列", "label": "复合"}], "register": "中性", "sense_fingerprint": "一件接一件、互相有关的事或东西，常说“一系列”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "系列", "is_correct": true, "explanation": "“一系列”指一件接一件、互相有关的许多事，符合“新计划”的语境。"}, {"text": "场", "is_correct": false, "explanation": "语义：“一场”指一次比赛或演出，不能说“一场新计划”。"}, {"text": "片", "is_correct": false, "explanation": "搭配：“一片”用于平面的东西，不能用来修饰计划。"}, {"text": "团", "is_correct": false, "explanation": "语义：“一团”指成团的东西，不能用来计算计划。"}], "explanations": {"系列": "“一系列”指一件接一件、互相有关的许多事，符合“新计划”的语境。", "场": "语义：“一场”指一次比赛或演出，不能说“一场新计划”。", "片": "搭配：“一片”用于平面的东西，不能用来修饰计划。", "团": "语义：“一团”指成团的东西，不能用来计算计划。"}, "sentence_index": 0, "correct_answer": "系列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一系列夫妻很恩爱。", "explanation": "这里应该用〈对〉。夫妻成对，应说“这对夫妻”；“一系列”指一件接一件、互相有关的事或物，不用于人。"}, {"text": "我的一系列朋友都来了。", "explanation": "“一系列”多用于事或物，不用于人，应说“一群朋友”。"}, {"text": "他一系列地跑了五公里。", "explanation": "“一系列”强调一件接一件的多件事，跑一次步不宜这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "系列", "is_correct": true, "explanation": "“一系列”修饰“好消息”，指一连串的好消息。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画作，不能用来计算消息。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等，不能说“一座好消息”。"}, {"text": "面", "is_correct": false, "explanation": "搭配：“面”用于平面或镜子等，不能用来修饰消息。"}], "explanations": {"系列": "“一系列”修饰“好消息”，指一连串的好消息。", "幅": "语义：“幅”用于画作，不能用来计算消息。", "座": "搭配：“座”用于山、建筑等，不能说“一座好消息”。", "面": "搭配：“面”用于平面或镜子等，不能用来修饰消息。"}, "sentence_index": 6, "correct_answer": "系列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一系列的叔叔都很高。", "explanation": "“系列”不用于人，“一系列”指一件接一件的事或物，不能修饰叔叔。"}, {"text": "他一系列地摔了一跤。", "explanation": "“一系列地”强调一连串的动作或事件，摔了一跤只是一次，不宜这样说。"}, {"text": "他的一系列天空很蓝。", "explanation": "“系列”指一连串相关的事情或物品，不能修饰“天空”这样的单一事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地震后，市里出台了两系列措施。", "corrected_sentence": "地震后，市里出台了一系列措施。", "error_description": "“系列”在“一系列”义项中，前面的数词应用“一”，不能用“两”。“两系列措施”不通，应说“一系列措施”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家提出了两系列建议。", "corrected_sentence": "大家提出了一系列建议。", "error_description": "“系列”前的数词应用“一”，不能用“两”。“两系列建议”不通，应说“一系列建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
