INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86501, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "警察是保护大家平安、抓坏人的人。", "primary_collocate": null, "pronunciation": "jǐng chá", "ipa": "tɕiŋ˨˩˦ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "我长大想当警察，抓坏人。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察叔叔帮我找到了妈妈。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个警察穿着蓝色的衣服。", "target_word": "警察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迷路的时候，可以问警察。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸是警察，他工作很忙。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察来了，坏人都跑了。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马路上有一位警察。", "target_word": "警察", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们都喜欢这位警察。", "target_word": "警察", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看见警察，就把钱包交给他。", "target_word": "警察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察开车去抓坏人。", "target_word": "警察", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "交通警察", "label": "复合"}, {"form": "警察局", "label": "复合"}], "register": "中性", "sense_fingerprint": "保护大家、抓坏人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86501, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警察", "is_correct": true, "explanation": "警察的职责包括抓坏人，“想当”后接职业，句意通顺。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生的职责是救治病人，不负责抓坏人。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷本身是坏人，“想当小偷、抓坏人”前后矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“抓”的施事须是人，“空气”不能抓坏人。"}], "explanations": {"警察": "警察的职责包括抓坏人，“想当”后接职业，句意通顺。", "医生": "语义：医生的职责是救治病人，不负责抓坏人。", "小偷": "语义：小偷本身是坏人，“想当小偷、抓坏人”前后矛盾。", "空气": "搭配：“抓”的施事须是人，“空气”不能抓坏人。"}, "sentence_index": 0, "correct_answer": "警察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐是一名警察，每天在学校教我们语文。", "explanation": "这里应该用〈老师〉。警察负责维护治安、抓捕违法人员，不负责教学，不能用来指教师。"}, {"text": "我哥哥是警察，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。警察抓坏人、保护大家，不给病人看病。"}, {"text": "这栋楼是警察，我经常去。", "explanation": "这里应该用〈派出所〉。“警察”指人，指建筑物要用“派出所”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警察", "is_correct": true, "explanation": "警察在马路上执勤是常见情景，句意通顺。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“位”用于人，汽车要说“一辆汽车”。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“位”用于人，小狗要说“一只小狗”。"}, {"text": "大树", "is_correct": false, "explanation": "搭配：“位”用于人，大树要说“一棵大树”。"}], "explanations": {"警察": "警察在马路上执勤是常见情景，句意通顺。", "汽车": "搭配：“位”用于人，汽车要说“一辆汽车”。", "小狗": "搭配：“位”用于人，小狗要说“一只小狗”。", "大树": "搭配：“位”用于人，大树要说“一棵大树”。"}, "sentence_index": 6, "correct_answer": "警察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我舅舅是一名警察，经常在法庭上为当事人辩护。", "explanation": "这里应该用〈律师〉。警察负责维护治安，不在法庭上为当事人辩护。"}, {"text": "我妈妈是一名警察，每天给客人剪头发。", "explanation": "这里应该用〈理发师〉。警察负责维护治安，不负责给客人剪头发。"}, {"text": "那位警察每天在饭店做菜。", "explanation": "这里应该用〈厨师〉。警察负责维护治安，不在饭店做菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只警察正在帮老奶奶过马路。", "corrected_sentence": "一位警察正在帮老奶奶过马路。", "error_description": "量词错误：指人的“警察”应使用量词“位”，“只”用于动物。“一只警察”应改为“一位警察”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几辆警察守在门口。", "corrected_sentence": "几名警察守在门口。", "error_description": "量词错误：“辆”用于车辆，指人的“警察”应使用量词“名”或“位”。“几辆警察”应改为“几名警察”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
