INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "维护社会治安、保护人民安全、依法处理违法犯罪行为的人员。", "primary_collocate": null, "pronunciation": "jǐng chá", "ipa": "tɕiŋ˨˩˦ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "警察正在路口指挥交通。", "target_word": "警察", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一名警察在街上巡逻。", "target_word": "警察", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察依法处理了这起打架事件。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察抓住了小偷。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发生事故后，警察很快来到现场。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察向群众介绍了防骗的方法。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到危险，请马上打电话找警察。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位警察每天晚上都在社区里巡逻。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察检查了司机的驾驶证。", "target_word": "警察", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察要保护人民的安全，也要遵守法律。", "target_word": "警察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "交通警察", "label": "复合"}, {"form": "警察局", "label": "复合"}], "register": "中性", "sense_fingerprint": "执行职务、维护治安的公职人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警察", "is_correct": true, "explanation": "警察是负责指挥交通、维护治安的人员，在路口指挥交通符合语境。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手的职业不包括在路口指挥交通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师在厨房工作，不负责路口指挥交通。"}, {"text": "交通", "is_correct": false, "explanation": "搭配：“指挥”的施事须是人，“交通”本身不能发出指挥的动作。"}], "explanations": {"警察": "警察是负责指挥交通、维护治安的人员，在路口指挥交通符合语境。", "歌手": "语义：歌手的职业不包括在路口指挥交通。", "厨师": "语义：厨师在厨房工作，不负责路口指挥交通。", "交通": "搭配：“指挥”的施事须是人，“交通”本身不能发出指挥的动作。"}, "sentence_index": 0, "correct_answer": "警察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈是一名警察，在医院里给病人看病。", "explanation": "这里应该用〈医生〉。警察负责维护治安、处理违法犯罪，不负责给病人看病。"}, {"text": "他去年升为三级警察。", "explanation": "这里应该用〈警官〉。警衔、级别说的是警官，“警察”是泛称，不用于表示警衔。"}, {"text": "我爸爸是一名警察，每天在饭店做菜。", "explanation": "这里应该用〈厨师〉。警察负责维护治安，不在饭店做菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警察", "is_correct": true, "explanation": "警察是遇到危险时可以打电话求助的人员，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“找”需要可以被寻找、联系的对象，“空气”不能打电话去找。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不能在危险时帮忙，打电话去找钢琴不合常理。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是场所，不能作为打电话求助的对象。"}], "explanations": {"警察": "警察是遇到危险时可以打电话求助的人员，句意通顺。", "空气": "搭配：“找”需要可以被寻找、联系的对象，“空气”不能打电话去找。", "钢琴": "语义：钢琴不能在危险时帮忙，打电话去找钢琴不合常理。", "公园": "语义：公园是场所，不能作为打电话求助的对象。"}, "sentence_index": 6, "correct_answer": "警察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼是警察，里面有很多办公室。", "explanation": "这里应该用〈警局〉。“警察”指人，指建筑物要用“警局”或“派出所”。"}, {"text": "我是一名警察，每天在法庭上为当事人辩护。", "explanation": "这里应该用〈律师〉。警察负责维护治安、处理违法犯罪，不在法庭上为当事人辩护。"}, {"text": "那位警察每天在理发店给客人剪头发。", "explanation": "这里应该用〈理发师〉。警察负责维护治安，不负责给客人剪头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只警察正在马路中间指挥交通。", "corrected_sentence": "那位警察正在马路中间指挥交通。", "error_description": "量词错误：指人的“警察”应使用量词“位”，“只”用于动物。“那只警察”应改为“那位警察”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
