INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86503, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "声明是公开地告诉大家自己的想法。", "primary_collocate": null, "pronunciation": "shēng míng", "ipa": "ʂɤŋ˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他站起来，向大家声明自己的想法。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李在班上声明，他不想当班长。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先声明，我不喜欢吵架。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈当着大家声明，周末谁也不能出去。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公开声明了自己的看法。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师在会上声明，大家要按时交作业。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大声地向同学声明，这个办法她不同意。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先声明一下，这只是我个人的想法。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在电话里声明过，他不同意。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长对大家声明，水费不会再涨。", "target_word": "声明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "声明了", "label": "完成体"}, {"form": "声明过", "label": "经历体"}, {"form": "声明书", "label": "复合词"}], "register": "正式", "sense_fingerprint": "公开地告诉大家自己的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86503, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "声明", "is_correct": true, "explanation": "声明（shēng míng）：公开地告诉大家自己的想法，与题目读音一致。"}, {"text": "生命", "is_correct": false, "explanation": "生命 shēng mìng 与 shēng míng 第二音节声调不同（第四声与第二声），意思是生命。"}, {"text": "争鸣", "is_correct": false, "explanation": "争鸣 zhēng míng 与 shēng míng 第一音节声母不同（zh 与 sh），意思是互相辩论。"}, {"text": "盛名", "is_correct": false, "explanation": "盛名 shèng míng 与 shēng míng 第一音节声调不同（第四声），意思是很高的名望。"}, {"text": "深明", "is_correct": false, "explanation": "深明 shēn míng 与 shēng míng 第一音节韵母不同（-n 与 -ng），意思是深刻明白。"}], "explanations": {"声明": "声明（shēng míng）：公开地告诉大家自己的想法，与题目读音一致。", "生命": "生命 shēng mìng 与 shēng míng 第二音节声调不同（第四声与第二声），意思是生命。", "争鸣": "争鸣 zhēng míng 与 shēng míng 第一音节声母不同（zh 与 sh），意思是互相辩论。", "盛名": "盛名 shèng míng 与 shēng míng 第一音节声调不同（第四声），意思是很高的名望。", "深明": "深明 shēn míng 与 shēng míng 第一音节韵母不同（-n 与 -ng），意思是深刻明白。"}, "sentence_index": null, "correct_answer": "声明"}, "level_3": {"options": [{"text": "声明", "is_correct": true, "explanation": "声明：公开地告诉大家自己的想法，与句意相符。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与“向大家”告诉的意思相反。"}, {"text": "请求", "is_correct": false, "explanation": "搭配：“请求”的对象多为事情或帮助，不能直接接“想法”。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽别人，与“自己的想法”搭配不上。"}], "explanations": {"声明": "声明：公开地告诉大家自己的想法，与句意相符。", "隐藏": "语义：“隐藏”与“向大家”告诉的意思相反。", "请求": "搭配：“请求”的对象多为事情或帮助，不能直接接“想法”。", "嘲笑": "语义：“嘲笑”是讥讽别人，与“自己的想法”搭配不上。"}, "sentence_index": 0, "correct_answer": "声明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他常常声明童年的快乐。", "explanation": "这里应该用〈回忆〉。声明是公开表态或说明情况，不能用于个人回想。"}, {"text": "大家声明他的书包。", "explanation": "这里应该用〈找〉。声明不表示寻找物件，不能接物品作宾语。"}, {"text": "我们终于声明了那座山。", "explanation": "这里应该用〈爬上〉。声明不表示攀登，不能接地点作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL,