INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声明", "is_correct": true, "explanation": "声明：公开表明态度，与“大声地”及“不同意”一致。"}, {"text": "嘀咕", "is_correct": false, "explanation": "语义：“嘀咕”是小声低语，与“大声地”矛盾。"}, {"text": "耳语", "is_correct": false, "explanation": "语义：“耳语”是贴耳低声说话，与“大声地”矛盾。"}, {"text": "吩咐", "is_correct": false, "explanation": "搭配：“吩咐”后接的是要别人去做的事，与后面对办法的态度不合。"}], "explanations": {"声明": "声明：公开表明态度，与“大声地”及“不同意”一致。", "嘀咕": "语义：“嘀咕”是小声低语，与“大声地”矛盾。", "耳语": "语义：“耳语”是贴耳低声说话，与“大声地”矛盾。", "吩咐": "搭配：“吩咐”后接的是要别人去做的事，与后面对办法的态度不合。"}, "sentence_index": 6, "correct_answer": "声明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己的照片声明在朋友圈里。", "explanation": "这里应该用〈发布〉。声明表示公开地表态或说明想法，不用于发布照片。"}, {"text": "消防员声明了大火。", "explanation": "这里应该用〈扑灭〉。声明只表示公开表态，不能用于消灭火灾。"}, {"text": "大家声明新同学。", "explanation": "这里应该用〈欢迎〉。声明不表示迎接或接纳人，只能用于说明想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
