INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86504, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "声明", "is_correct": true, "explanation": "声明（shēng míng）：公开表示态度或说明情况，与题目读音一致。"}, {"text": "生命", "is_correct": false, "explanation": "生命 shēng mìng 与 shēng míng 第二音节声调不同（第四声与第二声），意思是生命。"}, {"text": "争鸣", "is_correct": false, "explanation": "争鸣 zhēng míng 与 shēng míng 第一音节声母不同（zh 与 sh），意思是互相辩论。"}, {"text": "盛名", "is_correct": false, "explanation": "盛名 shèng míng 与 shēng míng 第一音节声调不同（第四声），意思是很高的名望。"}, {"text": "深明", "is_correct": false, "explanation": "深明 shēn míng 与 shēng míng 第一音节韵母不同（-n 与 -ng），意思是深刻明白。"}], "explanations": {"声明": "声明（shēng míng）：公开表示态度或说明情况，与题目读音一致。", "生命": "生命 shēng mìng 与 shēng míng 第二音节声调不同（第四声与第二声），意思是生命。", "争鸣": "争鸣 zhēng míng 与 shēng míng 第一音节声母不同（zh 与 sh），意思是互相辩论。", "盛名": "盛名 shèng míng 与 shēng míng 第一音节声调不同（第四声），意思是很高的名望。", "深明": "深明 shēn míng 与 shēng míng 第一音节韵母不同（-n 与 -ng），意思是深刻明白。"}, "sentence_index": null, "correct_answer": "声明"}, "level_3": {"options": [{"text": "声明", "is_correct": true, "explanation": "声明：公开表示态度或说明情况，与句意一致。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”与“公开”的意思相反，句意冲突。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”表示讥讽，与“产品没有问题”的说明不符。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”是表达不满，而“产品没有问题”是澄清说明，句意不合。"}], "explanations": {"声明": "声明：公开表示态度或说明情况，与句意一致。", "隐瞒": "语义：“隐瞒”与“公开”的意思相反，句意冲突。", "嘲笑": "语义：“嘲笑”表示讥讽，与“产品没有问题”的说明不符。", "抱怨": "语义：“抱怨”是表达不满，而“产品没有问题”是澄清说明，句意不合。"}, "sentence_index": 0, "correct_answer": "声明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们声明明天见面。", "explanation": "这里应该用〈约定〉。声明是公开表态或说明情况，不表示双方商定见面。"}, {"text": "大家声明他的歌声。", "explanation": "这里应该用〈欣赏〉。声明不表示欣赏，不能接声音作宾语。"}, {"text": "他把书声明在桌上。", "explanation": "这里应该用〈放〉。声明不表示放置，不能带处所补语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声明", "is_correct": true, "explanation": "声明：公开表明态度，与“不是我做的”的说明语气一致。"}, {"text": "承认", "is_correct": false, "explanation": "语义：“承认”表示认下事情，与“这不是我做的”矛盾。"}, {"text": "炫耀", "is_correct": false, "explanation": "语义：“炫耀”是夸示，与否认事情的语气不合。"}, {"text": "吹嘘", "is_correct": false, "explanation": "搭配：“吹嘘”多用于成绩、本领，不能用于否认某件事的说明。"}], "explanations": {"声明": "声明：公开表明态度，与“不是我做的”的说明语气一致。", "承认": "语义：“承认”表示认下事情，与“这不是我做的”矛盾。", "炫耀": "语义：“炫耀”是夸示，与否认事情的语气不合。", "吹嘘": "搭配：“吹嘘”多用于成绩、本领，不能用于否认某件事的说明。"}, "sentence_index": 6, "correct_answer": "声明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨晚就声明了这张桌子。", "explanation": "这里应该用〈擦〉。声明不表示擦拭，不能接家具作宾语。"}, {"text": "他把旧书声明了。", "explanation": "这里应该用〈扔〉。声明只用于公开表态或说明情况，不能指丢弃东西。"}, {"text": "大家都在声明这道菜。", "explanation": "这里应该用〈品尝〉。声明不表示尝味道，不能接食物作对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校正式的声明了这次考试的时间。", "corrected_sentence": "学校正式声明了这次考试的时间。", "error_description": "“正式”作状语修饰动词时，中间不能加“的”；加“的”后“正式的”变成定语，句子不通，应为“正式声明”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那件事与我无关，我想再声明一个。", "corrected_sentence": "那件事与我无关，我想再声明一次。", "error_description": "动作的次数要用动量词“次”，不能用“个”；应为“声明一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86505, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86505, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86505, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不仅是说不只是这样，还有别的。", "primary_collocate": null, "pronunciation": "bù jǐn", "ipa": "pu˥˩ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "他不仅是我的老师，还是我的朋友。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不仅是你的问题，也是大家的问题。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京不仅是中国的首都，还是一座大城市。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不仅是医生，还是一位好妈妈。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不仅是给孩子看的，大人也可以看。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语不仅是学说话，还要学写字。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不仅是一份工作，也是我的爱好。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不仅是我的同学，也是我的邻居。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动不仅是为了身体好，也是为了开心。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日不仅是孩子们的，也是全家人的。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不仅：不只是这样，后面接「是……」，常与「还」「也」呼应，补充别的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86505, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不仅", "is_correct": true, "explanation": "正确：不仅（bù jǐn）。"}, {"text": "不尽", "is_correct": false, "explanation": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声，jǐn 第三声），意思是没有穷尽。"}, {"text": "布巾", "is_correct": false, "explanation": "bù jīn 与 bù jǐn 第二音节声调不同（jīn 第一声，jǐn 第三声），意思是布做的毛巾。"}, {"text": "步进", "is_correct": false, "explanation": "bù jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是一步一步前进。"}, {"text": "不惊", "is_correct": false, "explanation": "bù jīng 与 bù jǐn 韵母由 in 变为 ing，声调也不同，意思是不受惊动。"}], "explanations": {"不仅": "正确：不仅（bù jǐn）。", "不尽": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声，jǐn 第三声），意思是没有穷尽。", "布巾": "bù jīn 与 bù jǐn 第二音节声调不同（jīn 第一声，jǐn 第三声），意思是布做的毛巾。", "步进": "bù jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是一步一步前进。", "不惊": "bù jīng 与 bù jǐn 韵母由 in 变为 ing，声调也不同，意思是不受惊动。"}, "sentence_index": null, "correct_answer": "不仅"}, "level_3": {"options": [{"text": "不仅", "is_correct": true, "explanation": "正确：「不仅……，还……」表示范围超出所说的，与「还是」呼应。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果，前文没有可以导出结论的原因，「是我的老师」与「还是我的朋友」之间不构成因果。"}, {"text": "或者", "is_correct": false, "explanation": "语义：「或者」表示选择，与后面的「还是」合用时变成二选一，与「老师」「朋友」并列增加的语义相冲突。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：「只有」须与「才」呼应，此处没有「才」，搭配不成立。"}], "explanations": {"不仅": "正确：「不仅……，还……」表示范围超出所说的，与「还是」呼应。", "因此": "语义：「因此」表示因果，前文没有可以导出结论的原因，「是我的老师」与「还是我的朋友」之间不构成因果。", "或者": "语义：「或者」表示选择，与后面的「还是」合用时变成二选一，与「老师」「朋友」并列增加的语义相冲突。", "只有": "搭配：「只有」须与「才」呼应，此处没有「才」，搭配不成立。"}, "sentence_index": 0, "correct_answer": "不仅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方法不仅有效，但是需要很多钱。", "explanation": "这里应该用〈虽然〉。「不仅」表示递进，要与「而且」「还」呼应，不能与「但是」表示的转折搭配。"}, {"text": "他虽然没学过法语，不仅能看懂这封信。", "explanation": "这里应该用〈却〉。「不仅」表示递进，不能表示转折，「虽然」之后应由「却」等转折词引出结果，不能用「不仅」。"}, {"text": "不仅下雨，所以我不出门。", "explanation": "这里应该用〈因为〉。「不仅」表示递进，不能引出因果；原因应由「因为」引出，再接「所以」表示结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86505, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不仅", "is_correct": true, "explanation": "正确：不仅（bù jǐn）。"}, {"text": "不进", "is_correct": false, "explanation": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是不进入。"}, {"text": "不近", "is_correct": false, "explanation": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是不靠近。"}, {"text": "不禁", "is_correct": false, "explanation": "bù jīn 与 bù jǐn 第二音节声调不同（jīn 第一声），意思是忍不住。"}], "explanations": {"不仅": "正确：不仅（bù jǐn）。", "不进": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是不进入。", "不近": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是不靠近。", "不禁": "bù jīn 与 bù jǐn 第二音节声调不同（jīn 第一声），意思是忍不住。"}, "sentence_index": null, "correct_answer": "不仅"}, "level_3": {"options": [{"text": "不仅", "is_correct": true, "explanation": "正确：「不仅……，也……」表示范围超出一份工作，与「也是」呼应。"}, {"text": "或", "is_correct": false, "explanation": "语义：「或」表示二选一，与「也是」表示累加的语义相冲突，句子变成两者择一。"}, {"text": "要么", "is_correct": false, "explanation": "搭配：「要么」须成对使用表示二选一（要么……要么……），此处与「也是」不搭配。"}, {"text": "如果", "is_correct": false, "explanation": "语义：「如果」引出假设条件，句子变成「假如这是工作」的条件句，与陈述递进的语义不符。"}], "explanations": {"不仅": "正确：「不仅……，也……」表示范围超出一份工作，与「也是」呼应。", "或": "语义：「或」表示二选一，与「也是」表示累加的语义相冲突，句子变成两者择一。", "要么": "搭配：「要么」须成对使用表示二选一（要么……要么……），此处与「也是」不搭配。", "如果": "语义：「如果」引出假设条件，句子变成「假如这是工作」的条件句，与陈述递进的语义不符。"}, "sentence_index": 6, "correct_answer": "不仅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不是老师，不仅是学生。", "explanation": "这里应该用〈而是〉。「不是」之后要用「而是」引出对比，「不仅」只表示递进，不能表示对比。"}, {"text": "他一边看书，不仅听音乐。", "explanation": "这里应该用〈同时〉或〈又〉。「不仅」表示递进，不能表示两个动作并列同时进行，「一边」之后应接「一边」或「同时」呼应。"}, {"text": "他不仅很努力，所以考上了大学。", "explanation": "这里应该用〈因为〉。「不仅」表示递进，不能表示因果，表示原因应用「因为」引出，「不仅」与「所以」不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市不仅大学，还有很多公园。", "corrected_sentence": "这个城市不仅有大学，还有很多公园。", "error_description": "「不仅」后面应接谓语「有」，表示范围不止于此。「不仅大学」缺少动词，应改为「不仅有大学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校不仅数学，也教英语。", "corrected_sentence": "学校不仅教数学，也教英语。", "error_description": "「不仅」后面应接谓语，「不仅数学」缺少动词「教」，应改为「不仅教数学」，与后面的「也教英语」呼应。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
