INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86506, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示意思不限于所说的范围，后面常有“而且”“还”等相配合。", "primary_collocate": null, "pronunciation": "bù jǐn", "ipa": "pu˥˩ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家店的菜不仅好吃，而且很便宜。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不仅会唱歌，还会跳舞。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不仅下雨，而且刮大风。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子不仅大，而且很干净。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不仅学习好，还很爱帮助别人。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不仅去了北京，还去了上海。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子不仅聪明，而且很有礼貌。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁不仅快，而且不会堵车。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不仅说得好，而且写得也好。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不仅我喜欢这部电影，我的朋友也喜欢。", "target_word": "不仅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不仅：递进连词，后面接形容词或动词，与「而且」「还」配合，表示范围不止于此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86506, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不仅", "is_correct": true, "explanation": "正确：不仅（bù jǐn）。"}, {"text": "步进", "is_correct": false, "explanation": "bù jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是一步一步前进。"}, {"text": "布巾", "is_correct": false, "explanation": "bù jīn 与 bù jǐn 第二音节声调不同（jīn 第一声），意思是布做的毛巾。"}, {"text": "不惊", "is_correct": false, "explanation": "bù jīng 与 bù jǐn 韵母由 in 变为 ing，声调也不同，意思是不受惊动。"}], "explanations": {"不仅": "正确：不仅（bù jǐn）。", "步进": "bù jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是一步一步前进。", "布巾": "bù jīn 与 bù jǐn 第二音节声调不同（jīn 第一声），意思是布做的毛巾。", "不惊": "bù jīng 与 bù jǐn 韵母由 in 变为 ing，声调也不同，意思是不受惊动。"}, "sentence_index": null, "correct_answer": "不仅"}, "level_3": {"options": [{"text": "不仅", "is_correct": true, "explanation": "正确：「不仅……，而且……」表示范围不止于此，与「而且」呼应。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：「虽然」须与「但是」「却」呼应表示让步转折，不能与「而且」并列递进。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示因果，「好吃」不能作为「很便宜」的原因，句子的语义关系不成立。"}, {"text": "或者", "is_correct": false, "explanation": "语义：「或者」表示选择，与「而且」表示的递加关系相冲突。"}], "explanations": {"不仅": "正确：「不仅……，而且……」表示范围不止于此，与「而且」呼应。", "虽然": "搭配：「虽然」须与「但是」「却」呼应表示让步转折，不能与「而且」并列递进。", "因为": "语义：「因为」表示因果，「好吃」不能作为「很便宜」的原因，句子的语义关系不成立。", "或者": "语义：「或者」表示选择，与「而且」表示的递加关系相冲突。"}, "sentence_index": 0, "correct_answer": "不仅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房子不仅大，但是很旧。", "explanation": "这里应该用〈虽然〉。「不仅」表示递进，要与「而且」「还」呼应，不能与「但是」表示的转折搭配。"}, {"text": "这不是一套房子，不仅是一个家。", "explanation": "这里应该用〈而是〉。「不是」之后要用「而是」引出对比，「不仅」只表示递进，不能表示对比。"}, {"text": "这件衣服不仅便宜，却很难看。", "explanation": "这里应该用〈虽然〉。「不仅」表示递进，不能表示让步，「却」之前应与「虽然」呼应，不能用「不仅」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86506, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不仅", "is_correct": true, "explanation": "正确：不仅（bù jǐn）。"}, {"text": "不尽", "is_correct": false, "explanation": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是没有穷尽。"}, {"text": "不进", "is_correct": false, "explanation": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是不进入。"}, {"text": "不近", "is_correct": false, "explanation": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是不靠近。"}, {"text": "不禁", "is_correct": false, "explanation": "bù jīn 与 bù jǐn 第二音节声调不同（jīn 第一声），意思是忍不住。"}], "explanations": {"不仅": "正确：不仅（bù jǐn）。", "不尽": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是没有穷尽。", "不进": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是不进入。", "不近": "bú jìn 与 bù jǐn 第二音节声调不同（jìn 第四声），意思是不靠近。", "不禁": "bù jīn 与 bù jǐn 第二音节声调不同（jīn 第一声），意思是忍不住。"}, "sentence_index": null, "correct_answer": "不仅"}, "level_3": {"options": [{"text": "不仅", "is_correct": true, "explanation": "正确：「不仅……，而且……」表示范围不止于此，与「而且」呼应。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：「尽管」须与「但是」「还是」呼应表示让步，不能与「而且」并列递进。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，「聪明」与「有礼貌」之间不是因果关系，句子语义不通。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：「只有」须与「才」呼应，此处没有「才」，搭配不成立。"}], "explanations": {"不仅": "正确：「不仅……，而且……」表示范围不止于此，与「而且」呼应。", "尽管": "搭配：「尽管」须与「但是」「还是」呼应表示让步，不能与「而且」并列递进。", "所以": "语义：「所以」表示因果，「聪明」与「有礼貌」之间不是因果关系，句子语义不通。", "只有": "搭配：「只有」须与「才」呼应，此处没有「才」，搭配不成立。"}, "sentence_index": 6, "correct_answer": "不仅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一边做饭，不仅打电话。", "explanation": "这里应该用〈同时〉。「不仅」表示递进，不能表示两个动作同时进行，「一边」之后应接「一边」或「同时」呼应，不能用「不仅」。"}, {"text": "我本以为他会来，不仅他没有来。", "explanation": "这里应该用〈不料〉。「不仅」表示递进，不能表示出乎意料的转折，「本以为」之后应用「不料」引出相反的结果。"}, {"text": "这间屋子不仅小，因此很便宜。", "explanation": "这里应该用〈因为〉。「不仅」表示递进，不能表示因果，「因此」与「不仅」不能搭配，表示原因应用「因为」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
