INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "股份是一家公司分成的许多小份，买了就有一份。", "primary_collocate": null, "pronunciation": "gǔ fèn", "ipa": "ku˨˩˦ fən˥˩", "syllable_count": 2, "sentences": [{"text": "他在这家公司有一些股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把股份分给了很多人。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买这家公司的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她卖掉了手里的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股份分成了一百万份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸有公司百分之十的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买了股份，就是公司的一个小主人。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的股份越来越贵了。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给了我一点公司的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三个人各有三分之一的股份。", "target_word": "股份", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股份公司", "label": "复合"}, {"form": "股份制", "label": "复合"}], "register": "中性", "sense_fingerprint": "公司分成的许多小份，买了就拥有一份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55ba4b8-27ee-40aa-8987-109ad1bec8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86507, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "股份", "is_correct": true, "explanation": "正确：股份（gǔ fèn）指公司分成的许多小份，这就是听到的词。"}, {"text": "鼓风", "is_correct": false, "explanation": "fēng（第一声）与 fèn（第四声）的韵母和声调都不同，意思是吹风、送风。"}, {"text": "骨粉", "is_correct": false, "explanation": "fěn（第三声）与 fèn（第四声）声调不同，意思是骨头磨成的粉。"}, {"text": "估分", "is_correct": false, "explanation": "gū 与 gǔ、fēn 与 fèn 声调都不同，意思是估计分数。"}, {"text": "古坟", "is_correct": false, "explanation": "gǔ 相同，fén（第二声）与 fèn（第四声）只有声调不同，意思是古代的坟墓。"}], "explanations": {"股份": "正确：股份（gǔ fèn）指公司分成的许多小份，这就是听到的词。", "鼓风": "fēng（第一声）与 fèn（第四声）的韵母和声调都不同，意思是吹风、送风。", "骨粉": "fěn（第三声）与 fèn（第四声）声调不同，意思是骨头磨成的粉。", "估分": "gū 与 gǔ、fēn 与 fèn 声调都不同，意思是估计分数。", "古坟": "gǔ 相同，fén（第二声）与 fèn（第四声）只有声调不同，意思是古代的坟墓。"}, "sentence_index": null, "correct_answer": "股份"}, "level_3": {"options": [{"text": "股份", "is_correct": true, "explanation": "正确：句中指他持有这家公司的一部分份额，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以在公司里拥有的东西，“在这家公司有一些天气”说不通。"}, {"text": "股价", "is_correct": false, "explanation": "搭配：“有”后面接“股价”不通，股价是股票的价格，不是可以持有的份额。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是交给学校的钱，与“公司”无关，句意不通。"}], "explanations": {"股份": "正确：句中指他持有这家公司的一部分份额，符合语境。", "天气": "语义：天气不是可以在公司里拥有的东西，“在这家公司有一些天气”说不通。", "股价": "搭配：“有”后面接“股价”不通，股价是股票的价格，不是可以持有的份额。", "学费": "语义：学费是交给学校的钱，与“公司”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "股份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上去超市买股份。", "explanation": "这里应该用〈食品〉。股份是公司资本的份额，不是超市里的商品，不能拿去买。"}, {"text": "她是这家公司的股份。", "explanation": "这里应该用〈股东〉。股份指份额，不指人；指持有股份的人要说股东。"}, {"text": "这次演出每人的股份是三张门票。", "explanation": "这里应该用〈份额〉。股份专指公司资本中的份额，不用于演出票数这类一般分配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股份", "is_correct": true, "explanation": "正确：买入的是公司的份额，买了股份就成了公司的一部分所有者，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：买房子买的是房产，与“公司的小主人”无关，句子说不通。"}, {"text": "股东", "is_correct": false, "explanation": "搭配：“买”的对象是可以买的东西，不能买“股东”这样的人。"}, {"text": "菜", "is_correct": false, "explanation": "语义：买菜买的是食物，与公司的所有权无关，句意不通。"}], "explanations": {"股份": "正确：买入的是公司的份额，买了股份就成了公司的一部分所有者，符合句意。", "房子": "语义：买房子买的是房产，与“公司的小主人”无关，句子说不通。", "股东": "搭配：“买”的对象是可以买的东西，不能买“股东”这样的人。", "菜": "语义：买菜买的是食物，与公司的所有权无关，句意不通。"}, "sentence_index": 6, "correct_answer": "股份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他交了三万元股份，成了公司的合伙人。", "explanation": "这里应该用〈股金〉。入股时交出的是钱，股份指所占的份额，不能说“交股份”。"}, {"text": "这家店每个月都赚很多股份。", "explanation": "这里应该用〈利润〉。赚到的是钱，股份指份额，不能用“赚”来说。"}, {"text": "他的孩子每年都要交股份。", "explanation": "这里应该用〈学费〉。交出去的是钱，股份不是钱，不能用来交学费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把自己的一只股份卖给了朋友。", "corrected_sentence": "他把自己的股份卖给了朋友。", "error_description": "量词错误：“股份”前不能用“只”（“只”多用于动物、船只等）。应去掉“一只”，说“他把自己的股份卖给了朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一部分股份付给了朋友。", "corrected_sentence": "他把一部分股份卖给了朋友。", "error_description": "搭配错误：“股份”是可以卖的份额，不能“付”，应说“卖”。正确：“他把一部分股份卖给了朋友。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
