INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人物是故事里的人，或者很重要的人。", "primary_collocate": null, "pronunciation": "rén wù", "ipa": "ʐən˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "这本书里的人物很有意思。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的人物都有自己的名字。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影有五个主要人物。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢这个故事的主要人物。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们公司的重要人物。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人是村里很受尊敬的人物。", "target_word": "人物", "complexity_tier": "T3", "furigana": "zhè wèi lǎo rén shì cūn lǐ hěn shòu zūn jìng de rén wù", "sentence_source": "generated"}, {"text": "老师给我们讲历史人物的故事。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的人物都很可爱。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的人物，大家都认识。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人物在电影里一直很勇敢。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位人物", "label": "量词"}, {"form": "重要人物", "label": "复合"}, {"form": "历史人物", "label": "复合"}], "register": "中性", "sense_fingerprint": "故事里的人；重要的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86509, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人物", "is_correct": true, "explanation": "人物指书里描写的人，“这本书里的人物很有意思”通顺自然。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是物理量，书里不会有温度“很有意思”，与“这本书里”的语境冲突。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格可以说“很贵”“很便宜”，不能说“很有意思”。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：面积可以说“很大”“很小”，不能说“很有意思”。"}], "explanations": {"人物": "人物指书里描写的人，“这本书里的人物很有意思”通顺自然。", "温度": "语义：温度是物理量，书里不会有温度“很有意思”，与“这本书里”的语境冲突。", "价格": "搭配：价格可以说“很贵”“很便宜”，不能说“很有意思”。", "面积": "搭配：面积可以说“很大”“很小”，不能说“很有意思”。"}, "sentence_index": 0, "correct_answer": "人物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地铁里挤满了人物。", "explanation": "这里应该用〈乘客〉。〈乘客〉指乘车的人；〈人物〉指书里描写的人或有名望的人，不能用来指地铁里一般的乘车人。"}, {"text": "公司这次派了五名人物去修理空调。", "explanation": "这里应该用〈工人〉。〈人物〉指书里描写的人或有名望的人，不能指修理空调的工人。"}, {"text": "这个城市的人物一年增加了很多。", "explanation": "这里应该用〈人口〉。〈人口〉指一个地区的居民总数，〈人物〉不能表示人数的增减。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人物", "is_correct": true, "explanation": "人物与“历史”组成“历史人物”，“讲历史人物的故事”通顺自然。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体数据，不能作为故事的讲述对象，“讲历史身高的故事”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是数字性的属性，不能成为“讲……的故事”的内容。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌只指长相，不能与“历史”组合成可以被讲述的对象。"}], "explanations": {"人物": "人物与“历史”组成“历史人物”，“讲历史人物的故事”通顺自然。", "身高": "语义：身高是人的身体数据，不能作为故事的讲述对象，“讲历史身高的故事”说不通。", "年龄": "语义：年龄是数字性的属性，不能成为“讲……的故事”的内容。", "外貌": "语义：外貌只指长相，不能与“历史”组合成可以被讲述的对象。"}, "sentence_index": 6, "correct_answer": "人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里的人物正在给病人看病。", "explanation": "这里应该用〈医生〉。〈人物〉指故事里的人或重要的人，不能指给病人看病的医生。"}, {"text": "这家饭店的人物都很热情。", "explanation": "这里应该用〈服务员〉。〈人物〉不能用来指饭店里工作的一般人员。"}, {"text": "我们班的人物今天都来上课了。", "explanation": "这里应该用〈同学〉。〈人物〉指故事里的人或重要的人，不能指班里的一般同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在村里是一只有名的人物。", "corrected_sentence": "他在村里是一位有名的人物。", "error_description": "量词错误：“人物”前应该用“位”或“个”，写成“一只”不对，因为“只”多用于动物，不能用来计数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部小说里有一本重要人物。", "corrected_sentence": "这部小说里有一个重要人物。", "error_description": "量词错误：“人物”前应该用“个”或“位”，写成“一本”不对，因为“本”用于书籍，不能用来计数人物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
