INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指文艺作品中描写的人；也指在某一领域有影响、有地位的人。", "primary_collocate": null, "pronunciation": "rén wù", "ipa": "ʐən˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "作者把小说人物写得很真实。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章里有三个人物。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中人物的性格各不相同。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是科学界的著名人物。", "target_word": "人物", "complexity_tier": "T3", "furigana": "tā shì kē xué jiè de zhù míng rén wù", "sentence_source": "generated"}, {"text": "那位老人是当地的知名人物。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧的人物很生动。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是政界的重要人物。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家画了一个有趣的人物。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是音乐界有影响的人物。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事中的人物都很有个性。", "target_word": "人物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位人物", "label": "量词"}, {"form": "重要人物", "label": "复合"}, {"form": "历史人物", "label": "复合"}], "register": "中性", "sense_fingerprint": "作品中描写的人；某领域有影响的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人物", "is_correct": true, "explanation": "人物指小说中描写的人，“把小说人物写得很真实”自然通顺。"}, {"text": "密度", "is_correct": false, "explanation": "语义：密度是物理量，小说内容不能被“写得很真实”，与“作者把小说”的语境矛盾。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：面积可以说“很大”“很小”，不能说“写得很真实”。"}, {"text": "指标", "is_correct": false, "explanation": "语域：指标是统计或技术用语，不用于描写小说的内容，不能说“写得很真实”。"}], "explanations": {"人物": "人物指小说中描写的人，“把小说人物写得很真实”自然通顺。", "密度": "语义：密度是物理量，小说内容不能被“写得很真实”，与“作者把小说”的语境矛盾。", "面积": "搭配：面积可以说“很大”“很小”，不能说“写得很真实”。", "指标": "语域：指标是统计或技术用语，不用于描写小说的内容，不能说“写得很真实”。"}, "sentence_index": 0, "correct_answer": "人物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现在工作很忙，我们需要更多人物。", "explanation": "这里应该用〈人手〉。〈人手〉指做事的人力；〈人物〉指书里描写的人或有名望的人，不能表示做事的人力。"}, {"text": "这个小区的人物大多是年轻人。", "explanation": "这里应该用〈居民〉。〈居民〉指住在某地的人，〈人物〉不用来指一般的住户。"}, {"text": "景区门口的草地上长着很多人物。", "explanation": "这里应该用〈树〉或〈花〉。〈人物〉指书里描写的人或有名望的人，不能指植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人物", "is_correct": true, "explanation": "人物指在某个领域有地位的人，“他是政界的重要人物”自然通顺。"}, {"text": "作品", "is_correct": false, "explanation": "语义：作品指作家或艺术家创作的成果，不是人，不能说“他是政界的重要作品”。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：房屋是建筑物，不能指“他”这样的人，“他是政界的重要房屋”说不通。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指长相，不能表示一个人在政界的地位或身份。"}], "explanations": {"人物": "人物指在某个领域有地位的人，“他是政界的重要人物”自然通顺。", "作品": "语义：作品指作家或艺术家创作的成果，不是人，不能说“他是政界的重要作品”。", "房屋": "语义：房屋是建筑物，不能指“他”这样的人，“他是政界的重要房屋”说不通。", "外貌": "语义：外貌指长相，不能表示一个人在政界的地位或身份。"}, "sentence_index": 6, "correct_answer": "人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的人物每天九点上班。", "explanation": "这里应该用〈员工〉。〈人物〉指作品中的人或有影响的人，不能指公司里的一般职员。"}, {"text": "商店里的人物在排队付钱。", "explanation": "这里应该用〈顾客〉。〈人物〉不用来指买东西的一般人。"}, {"text": "医院里的人物正在给病人看病。", "explanation": "这里应该用〈医生〉。〈人物〉不能指给病人看病的医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是体坛一只有影响的人物。", "corrected_sentence": "她是体坛一位有影响的人物。", "error_description": "量词错误：“人物”前应该用“位”或“个”，写成“一只”不对，因为“只”多用于动物，不能用来计数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我们村的一张知名人物。", "corrected_sentence": "他是我们村的一位知名人物。", "error_description": "量词错误：“人物”前应该用“位”或“个”，写成“一张”不对，因为“张”用于有平面的东西，不能用来指人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86511, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "永久", "is_correct": true, "explanation": "“永久”与“临时”意思相反，指长久不变，与“暂时”的意思相对。"}, {"text": "繁忙", "is_correct": false, "explanation": "“繁忙”指事务多、很忙碌，与“临时”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”指清楚分明，与“临时”没有反义关系。"}, {"text": "圆滑", "is_correct": false, "explanation": "“圆滑”指处事周到、不生硬，与“临时”没有反义关系。"}], "correct_answer": "永久", "explanations": {"永久": "“永久”与“临时”意思相反，指长久不变，与“暂时”的意思相对。", "繁忙": "“繁忙”指事务多、很忙碌，与“临时”没有反义关系。", "清晰": "“清晰”指清楚分明，与“临时”没有反义关系。", "圆滑": "“圆滑”指处事周到、不生硬，与“临时”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86511, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "永久", "is_correct": true, "explanation": "“永久”与“临时”意思相反，指长久不变，与“暂时”的意思相对。"}, {"text": "严格", "is_correct": false, "explanation": "“严格”指要求高、不放松，与“临时”没有反义关系。"}, {"text": "细致", "is_correct": false, "explanation": "“细致”指周密、仔细，与“临时”没有反义关系。"}, {"text": "活泼", "is_correct": false, "explanation": "“活泼”形容人或事物生动有朝气，与“临时”没有反义关系。"}], "correct_answer": "永久", "explanations": {"永久": "“永久”与“临时”意思相反，指长久不变，与“暂时”的意思相对。", "严格": "“严格”指要求高、不放松，与“临时”没有反义关系。", "细致": "“细致”指周密、仔细，与“临时”没有反义关系。", "活泼": "“活泼”形容人或事物生动有朝气，与“临时”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86511, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "暂时的，不会长久如此。", "primary_collocate": null, "pronunciation": "lín shí", "ipa": "lin˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这是临时的办法。", "target_word": "临时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这间屋子只是临时的仓库，以后会拆掉。", "target_word": "临时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先住在临时的房子里。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥是临时的，不能走大车。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校给我们找了一个临时住处。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只是临时办公室，下个月我们搬家。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还没有好工作，先找份临时工作。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路坏了，政府修了一条临时的路。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个临时停车场只开一个月。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张临时卡三天后就不能用了。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "临时工", "label": "复合"}, {"form": "临时性", "label": "复合"}, {"form": "臨時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "暂时的，不长久，如临时工、临时住处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "临时", "is_correct": true, "explanation": "“临时”表示暂时、不长久，修饰“办法”，符合句意。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指声音或环境平静，不用来形容办法。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”指光线充足，不用来形容办法。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容物体含有水分，不能用来修饰“办法”。"}], "explanations": {"临时": "“临时”表示暂时、不长久，修饰“办法”，符合句意。", "安静": "语义：“安静”指声音或环境平静，不用来形容办法。", "明亮": "语义：“明亮”指光线充足，不用来形容办法。", "潮湿": "搭配：“潮湿”形容物体含有水分，不能用来修饰“办法”。"}, "sentence_index": 0, "correct_answer": "临时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个苹果的味道很临时。", "explanation": "“临时”描述安排或设施是否长久，不能用来形容味道这样的性质。"}, {"text": "他的心情很临时，刚才还在笑，现在就哭了。", "explanation": "“临时”描述事物或安排的暂时性质，不能用来形容人的心情变化，这里应改用〈不稳定〉之类的词。"}, {"text": "这座桥的颜色很临时。", "explanation": "“临时”不能用来形容颜色等外观特征，它只描述事物是否长久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "临时", "is_correct": true, "explanation": "“临时”表示暂时、不长久，修饰“工作”，符合“先找份……工作”的句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不用来修饰工作本身。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”多形容刀具等器物的刃口，不能用来修饰“工作”。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容事物排列有序，不用来形容工作的性质。"}], "explanations": {"临时": "“临时”表示暂时、不长久，修饰“工作”，符合“先找份……工作”的句意。", "聪明": "语义：“聪明”形容人的智力，不用来修饰工作本身。", "锋利": "搭配：“锋利”多形容刀具等器物的刃口，不能用来修饰“工作”。", "整齐": "搭配：“整齐”形容事物排列有序，不用来形容工作的性质。"}, "sentence_index": 6, "correct_answer": "临时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张卡的颜色很临时。", "explanation": "“临时”不能形容颜色等外观特征，它只说明事物是否长久。"}, {"text": "这本书写得很临时，大家都爱看。", "explanation": "“临时”不能形容书写得好坏，它只表示事物暂时、不长久。"}, {"text": "他的临时性格让大家很不满意。", "explanation": "“临时”描述事物的暂时性质，不能用来形容人的性格，这里误用了它的含义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路是临时，下个月就封了。", "corrected_sentence": "这条路是临时的，下个月就封了。", "error_description": "错误形式：“是临时”；正确形式：“是临时的”。“临时”作表语时，后面要带“的”，不能单独作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个棚子是临时得仓库。", "corrected_sentence": "这个棚子是临时的仓库。", "error_description": "错误形式：“临时得仓库”；正确形式：“临时的仓库”。“临时”修饰名词“仓库”时要用助词“的”，“得”只用于动词或形容词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
