INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86512, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86512, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "事到临头才（做），事先没有安排。", "primary_collocate": null, "pronunciation": "lín shí", "ipa": "lin˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他临时有事，不能来了。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师临时改了考试时间。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们临时决定去爬山。", "target_word": "临时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议临时取消，大家都回家了。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天的比赛临时换了地方。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯坏了，今天临时停用。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理临时通知我们明天开会。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为下雨，我们临时换了一个办法。", "target_word": "临时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友临时来看我，我家里什么吃的也没有。", "target_word": "临时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话不是我准备好的，是临时想到的。", "target_word": "临时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "临时工", "label": "复合"}, {"form": "临时性", "label": "复合"}, {"form": "臨時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事到临头才（做），事先没有安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "临时", "is_correct": true, "explanation": "“临时”表示事到临头才发生，修饰“有事”，符合句意。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”表示动作或变化缓慢进行，与“有事”这种突然出现的情况不合。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意为之，与“有事不能来”的意外情况相矛盾。"}, {"text": "悄悄", "is_correct": false, "explanation": "搭配：“悄悄”修饰的是动作，不能直接修饰“有事”这一状态。"}], "explanations": {"临时": "“临时”表示事到临头才发生，修饰“有事”，符合句意。", "慢慢": "语义：“慢慢”表示动作或变化缓慢进行，与“有事”这种突然出现的情况不合。", "特意": "语义：“特意”表示有意为之，与“有事不能来”的意外情况相矛盾。", "悄悄": "搭配：“悄悄”修饰的是动作，不能直接修饰“有事”这一状态。"}, "sentence_index": 0, "correct_answer": "临时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的比赛去年就临时换了地方。", "explanation": "“临时”表示事到临头才作出的安排，与“去年就”这种提前的时间矛盾，这里应去掉“临时”。"}, {"text": "我们计划明年临时出国。", "explanation": "“计划”本身意味着事先安排，与“临时”表示事到临头的意思相冲突，这里不能这样用。"}, {"text": "老师提前一周临时通知了我们。", "explanation": "这里应该用〈提前〉或〈事先〉。“临时”强调事情临近时才发生，与“提前一周”的时间不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "临时", "is_correct": true, "explanation": "“临时”表示事到临头才发生，修饰“通知”，符合句意。"}, {"text": "渐渐", "is_correct": false, "explanation": "语义：“渐渐”表示逐步变化的过程，与一次性的通知动作不合。"}, {"text": "缓缓", "is_correct": false, "explanation": "语义：“缓缓”形容动作慢慢进行，与“通知”这种迅速传达的行为不合。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容事物排列有序，不能修饰“通知”这一动作。"}], "explanations": {"临时": "“临时”表示事到临头才发生，修饰“通知”，符合句意。", "渐渐": "语义：“渐渐”表示逐步变化的过程，与一次性的通知动作不合。", "缓缓": "语义：“缓缓”形容动作慢慢进行，与“通知”这种迅速传达的行为不合。", "整齐": "搭配：“整齐”形容事物排列有序，不能修饰“通知”这一动作。"}, "sentence_index": 6, "correct_answer": "临时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些话是我早就临时想到的。", "explanation": "“早就”表示提前很久，与“临时”表示事到临头的意思相矛盾，这里不能这样用。"}, {"text": "这次旅行我计划了一年，是临时决定的。", "explanation": "“计划了一年”表示事先安排很久，与“临时决定”的意思相冲突，“临时”在这里用错了。"}, {"text": "我们已经事先临时安排好了明天的会议。", "explanation": "这里应该去掉“临时”或改用〈事先〉。“事先”与“临时”意思相反，不能同时修饰同一安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为天气不好，学校早就临时关门了。", "corrected_sentence": "因为天气不好，学校临时关门了。", "error_description": "语义矛盾：“临时”表示事到临头才做，不能和表示很早以前的“早就”一起用，应去掉“早就”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客人提前一个月临时来看我们。", "corrected_sentence": "客人临时来看我们。", "error_description": "语义矛盾：“临时”表示事先没有安排，不能和“提前一个月”这种事先的安排一起用，应去掉“提前一个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
