INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86513, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86513, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "别人是除了你和我以外的人。", "primary_collocate": null, "pronunciation": "bié rén", "ipa": "pje˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这件事别人不知道，只有你我知道。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人都走了，只有我们还在这里。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让别人看我的信。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不是我的，是别人的。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别问别人，自己想一想。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了你和我，别人都没来。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天别人请客，我们不用花钱。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人的话，你不用都听。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱帮助别人。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个秘密我没有告诉别人。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "别人家", "label": "复合"}], "register": "中性", "sense_fingerprint": "除了你和我以外的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55ba4b8-27ee-40aa-8987-109ad1bec8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别人", "is_correct": true, "explanation": "正确：“别人”指你我以外的人，与“只有你我知道”相呼应。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”包括你和我，与“只有你我知道”矛盾。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人本人，与“只有你我知道”的意思矛盾。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”就是听话人，说“您不知道”却又说“只有你我知道”，前后矛盾。"}], "explanations": {"别人": "正确：“别人”指你我以外的人，与“只有你我知道”相呼应。", "大家": "语义：“大家”包括你和我，与“只有你我知道”矛盾。", "自己": "语义：“自己”指说话人本人，与“只有你我知道”的意思矛盾。", "您": "语义：“您”就是听话人，说“您不知道”却又说“只有你我知道”，前后矛盾。"}, "sentence_index": 0, "correct_answer": "别人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明很聪明，别人在班里总是第一名。", "explanation": "这里应该用〈他〉。“别人”泛指你我以外的人，不用来指某个具体的人。"}, {"text": "这些狗很聪明，别人会听主人的话。", "explanation": "这里应该用〈它们〉。“别人”只指人，不指动物。"}, {"text": "别人，你好！", "explanation": "这里应该用〈同学〉。“别人”指你我以外的人，不能用来直接称呼对方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别人", "is_correct": true, "explanation": "正确：“别人”指你我以外的人，句中是他人请客，我们不用花钱。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括说话人和听话人，若咱们请客就要花钱，与“我们不用花钱”矛盾。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”请客却又说“不用花钱”，前后矛盾。"}, {"text": "它", "is_correct": false, "explanation": "配价：“请客”的施事必须是人，“它”指事物或动物，不能请客。"}], "explanations": {"别人": "正确：“别人”指你我以外的人，句中是他人请客，我们不用花钱。", "咱们": "语义：“咱们”包括说话人和听话人，若咱们请客就要花钱，与“我们不用花钱”矛盾。", "我们": "语义：“我们”请客却又说“不用花钱”，前后矛盾。", "它": "配价：“请客”的施事必须是人，“它”指事物或动物，不能请客。"}, "sentence_index": 6, "correct_answer": "别人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸爸是别人。", "explanation": "这里应该用〈医生〉。“别人”泛指你我以外的人，不能用来说明某人的身份或职业。"}, {"text": "他的名字是别人。", "explanation": "这里应该用〈王明〉。“别人”是代词，指你我以外的人，不能用作人名。"}, {"text": "我把别人还给了他。", "explanation": "这里应该用〈书〉。“别人”指人，不能像物品一样归还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不想把自己的信给一个别人看。", "corrected_sentence": "我不想把自己的信给别人看。", "error_description": "数量词错误：“别人”是代词，前面不能加“一个”这类数量词。应去掉“一个”，说“给别人看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是别人东西。", "corrected_sentence": "这是别人的东西。", "error_description": "“的”遗漏：“别人”修饰名词“东西”时要加“的”，应说“别人的东西”，不说“别人东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
