INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86514, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86514, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指说话人和听话人之外的其他人，或自己以外的人。", "primary_collocate": null, "pronunciation": "bié rén", "ipa": "pje˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "做事不能只想自己，也要想想别人。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常把功劳让给别人。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人怎么说，我并不太在意。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要总是拿自己和别人比。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是说别人的好话。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自己做不好，就别怪别人。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人有困难时，我们应该帮一帮。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车借给别人了。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会听别人说话，也是一种本事。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人的经验，对我们也很有用。", "target_word": "别人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "别人家", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己以外的其他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55ba4b8-27ee-40aa-8987-109ad1bec8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别人", "is_correct": true, "explanation": "正确：“也要想想别人”与前句“只想自己”相对，指自己以外的人。"}, {"text": "自己", "is_correct": false, "explanation": "语义：前句说“只想自己”，后句再说“想想自己”，前后自相矛盾，句意不通。"}, {"text": "您", "is_correct": false, "explanation": "语域：“您”是对听话人的敬称，用于泛指的道理不合适。"}, {"text": "谁", "is_correct": false, "explanation": "搭配：“想想”后接具体对象，“谁”是疑问代词，陈述句中不这样用。"}], "explanations": {"别人": "正确：“也要想想别人”与前句“只想自己”相对，指自己以外的人。", "自己": "语义：前句说“只想自己”，后句再说“想想自己”，前后自相矛盾，句意不通。", "您": "语域：“您”是对听话人的敬称，用于泛指的道理不合适。", "谁": "搭配：“想想”后接具体对象，“谁”是疑问代词，陈述句中不这样用。"}, "sentence_index": 0, "correct_answer": "别人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷是别人。", "explanation": "这里应该用〈长辈〉。“别人”泛指你我以外的人，不能用来指自己的亲人。"}, {"text": "我家的猫叫别人。", "explanation": "这里应该用〈咪咪〉。“别人”是代词，指人，不能用作动物的名字。"}, {"text": "别人，请问厕所在哪儿？", "explanation": "这里应该用〈先生〉。“别人”指你我以外的人，不能用来称呼对方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别人", "is_correct": true, "explanation": "正确：“别人”指自己以外的人，有困难的是别人，我们去帮忙。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”有困难时还要由“我们”去帮，施助者与受助者矛盾，句意不通。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括说话人与听话人，与“我们应该帮一帮”中的施助对象自相矛盾。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指当事人本身，而“帮一帮”的对象应是他人，句意不通。"}], "explanations": {"别人": "正确：“别人”指自己以外的人，有困难的是别人，我们去帮忙。", "我们": "语义：“我们”有困难时还要由“我们”去帮，施助者与受助者矛盾，句意不通。", "咱们": "语义：“咱们”包括说话人与听话人，与“我们应该帮一帮”中的施助对象自相矛盾。", "自己": "语义：“自己”指当事人本身，而“帮一帮”的对象应是他人，句意不通。"}, "sentence_index": 6, "correct_answer": "别人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的名字叫别人。", "explanation": "这里应该用〈小李〉。“别人”是代词，指你我以外的人，不能用作人名。"}, {"text": "今天的天气是别人。", "explanation": "这里应该用〈好〉。“别人”指人，不能用来说明天气。"}, {"text": "我把别人收进了抽屉。", "explanation": "这里应该用〈东西〉。“别人”指人，不能像物品一样收进抽屉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很尊重两个别人的选择。", "corrected_sentence": "我很尊重别人的选择。", "error_description": "数量词错误：“别人”是代词，不能直接与“两个”组合。应去掉“两个”，说“我很尊重别人的选择”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该帮助别人们。", "corrected_sentence": "我们应该帮助别人。", "error_description": "多余的“们”：“别人”本身泛指他人，不能再加“们”，应说“帮助别人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
