INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86516, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接触地面。", "primary_collocate": null, "pronunciation": "zhuó dì", "ipa": "ʈʂwo˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "飞机慢慢着地，大家都鼓掌了。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跳下来的时候，双脚先着地。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子摔倒了，是头先着地。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球着地以后，又跳了起来。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫从树上跳下来，四只脚同时着地。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员落下来，脚没有站稳，手先着地。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟轻轻着地，然后走开了。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳高落下的时候，要用脚着地，别用背。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从床上掉下来，后背着地，疼得说不出话。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机着地以前，风很大。", "target_word": "着地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "着地了", "label": "体标（了）"}, {"form": "着地过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "身体或物体落下后接触地面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd727e10f-1248-4124-9d4c-8b97d0ca17dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着地", "is_correct": true, "explanation": "“着地”指物体落到地面上，与飞机慢慢降落的语境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：飞机不会游泳，“慢慢游泳”与降落的场景不符。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”是及物动词，后面要有宾语，句中没有宾语。"}, {"text": "摔倒", "is_correct": false, "explanation": "搭配：“摔倒”多用于人或动物，飞机不说摔倒。"}], "explanations": {"着地": "“着地”指物体落到地面上，与飞机慢慢降落的语境相符。", "游泳": "语义：飞机不会游泳，“慢慢游泳”与降落的场景不符。", "打开": "配价：“打开”是及物动词，后面要有宾语，句中没有宾语。", "摔倒": "搭配：“摔倒”多用于人或动物，飞机不说摔倒。"}, "sentence_index": 0, "correct_answer": "着地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "婴儿着地时体重只有三公斤。", "explanation": "这里应该用〈落地〉。婴儿出生要说落地，着地只指身体或物体接触地面，不能指出生。"}, {"text": "台风在广东着地了。", "explanation": "这里应该用〈登陆〉。台风从海上到陆地要说登陆，着地只指物体接触地面。"}, {"text": "飞机在海面上着地了。", "explanation": "这里应该用〈着水〉。飞机降落在水面要说着水，着地指落在陆地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着地", "is_correct": true, "explanation": "“着地”指小鸟轻轻落到地面，与后文“然后走开了”相符。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：小鸟轻轻落地不会被摔碎，与“轻轻”的语境不符。"}, {"text": "沉没", "is_correct": false, "explanation": "搭配：“沉没”多用于船只或物体没入水中，不用于小鸟落地。"}, {"text": "冒烟", "is_correct": false, "explanation": "语义：小鸟落地不会冒烟，与语境不符。"}], "explanations": {"着地": "“着地”指小鸟轻轻落到地面，与后文“然后走开了”相符。", "摔碎": "语义：小鸟轻轻落地不会被摔碎，与“轻轻”的语境不符。", "沉没": "搭配：“沉没”多用于船只或物体没入水中，不用于小鸟落地。", "冒烟": "语义：小鸟落地不会冒烟，与语境不符。"}, "sentence_index": 6, "correct_answer": "着地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个想法终于着地了，下个月就开始做。", "explanation": "这里应该用〈落实〉。想法确定下来要说落实，着地只指身体或物体接触地面。"}, {"text": "他带球着地得分了。", "explanation": "这里应该用〈触地〉。橄榄球带球触地得分要说触地，着地不能用于得分。"}, {"text": "渔船慢慢着地了。", "explanation": "这里应该用〈靠岸〉。船只靠近岸边要说靠岸，着地指接触地面，船不会着地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跳下来的时候，两只脚同时着地面。", "corrected_sentence": "他跳下来的时候，两只脚同时着地。", "error_description": "错误在于“着地”是不及物动词，不能带宾语“地面”。正确说法是“两只脚同时着地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "直升机慢慢被着地，我们都向后退了几步。", "corrected_sentence": "直升机慢慢着地，我们都向后退了几步。", "error_description": "错误在于“着地”是不及物动词，不能用“被”字句。正确说法是“直升机慢慢着地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
