INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86517, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女性是女孩和女人。", "primary_collocate": null, "pronunciation": "nǚ xìng", "ipa": "ny˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这位女性是我的新同事。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女性在门口等朋友。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多女性在跳舞。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位很有爱心的女性。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的东西都是给女性用的。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间只让女性住。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车上有一位女性给老人让了座。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是为年轻女性做的。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认识一位会说三种语言的女性。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位女性手里拿着一把红伞。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "女性：日常指具体的女孩、女人，可以用「位」来数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女性", "is_correct": true, "explanation": "正确：「女性」指女人，可用「位」来数，与「这位」搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是东西，不能当同事，也不能用「位」来数。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不能成为工作中的同事，句子不成立。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不能当同事，也不能用「位」来数。"}], "explanations": {"女性": "正确：「女性」指女人，可用「位」来数，与「这位」搭配。", "桌子": "语义：桌子是东西，不能当同事，也不能用「位」来数。", "孩子": "语义：孩子不能成为工作中的同事，句子不成立。", "苹果": "语义：苹果是水果，不能当同事，也不能用「位」来数。"}, "sentence_index": 0, "correct_answer": "女性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认识一只女性。", "explanation": "这里应该用〈位〉。「女性」指人，应用人的量词「位」，「只」用于动物或小件物品。"}, {"text": "这只母猫是一位女性。", "explanation": "「女性」只指人类，不能用于动物，母猫应说「雌性」。"}, {"text": "她很有女性。", "explanation": "这里应说〈女人味〉。「很有」可接表示气质的名词（如「很有爱心」），但「女性」是类别名词，不能表示气质，「很有女性」不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女性", "is_correct": true, "explanation": "正确：「女性」指女人，与「一位」搭配，可以做车上的乘客。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会给人让座，也不能用「位」来数。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会主动让座，句子与常识相矛盾。"}, {"text": "箱子", "is_correct": false, "explanation": "语义：箱子不能让座，且量词「位」只用于人，句子与常识相矛盾。"}], "explanations": {"女性": "正确：「女性」指女人，与「一位」搭配，可以做车上的乘客。", "小狗": "语义：小狗不会给人让座，也不能用「位」来数。", "婴儿": "语义：婴儿不会主动让座，句子与常识相矛盾。", "箱子": "语义：箱子不能让座，且量词「位」只用于人，句子与常识相矛盾。"}, "sentence_index": 6, "correct_answer": "女性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是我的女性，今年十岁。", "explanation": "这里应该用〈女儿〉。「女性」是女人和女孩的泛称，不表示子女关系，表示女儿应说「女儿」。"}, {"text": "喂，女性，请你让一下。", "explanation": "这里应该用〈女士〉。称呼陌生女子应用「女士」，直接用「女性」称呼生硬且不礼貌。"}, {"text": "我的女性在家做饭。", "explanation": "这里应该用〈妻子〉。「女性」泛指女人，不能用来指称自己的配偶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只女性是我的老板。", "corrected_sentence": "这位女性是我的老板。", "error_description": "「女性」指人，量词应用「位」，「只」用于动物。「这只女性」中量词错误，应改为「这位女性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只女性参加了这次比赛。", "corrected_sentence": "一位女性参加了这次比赛。", "error_description": "「女性」指人，量词应用「位」，「只」用于动物或小件物品。「一只女性」中量词错误，应改为「一位女性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
