INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指女人；人类两性中能生育后代的一方。", "primary_collocate": null, "pronunciation": "nǚ xìng", "ipa": "ny˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "女性比男性平均寿命长一些。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多女性也当了经理。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司有一半的员工是女性。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女性在家庭和社会中都很重要。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说女性要多注意身体。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报纸主要给女性读者看。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她研究的是女性的工作和生活。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的新生中，女性比男性多。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女性可以生孩子，这是男性做不到的。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越来越多的女性走上了重要的工作岗位。", "target_word": "女性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "书面", "sense_fingerprint": "女性：与男性相对，指人类两性中的一方，多用于社会、统计、生理等较正式的语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女性", "is_correct": true, "explanation": "正确：「女性」指人类两性中的一方，与「比男性」构成比较，符合统计语境。"}, {"text": "男性", "is_correct": false, "explanation": "语义：「男性比男性」比较对象重复，没有比较意义。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物与人群的平均寿命不构成比较，句子不通。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：「平均寿命」用于人群统计，「猫」与「男性」不能进行这种比较。"}], "explanations": {"女性": "正确：「女性」指人类两性中的一方，与「比男性」构成比较，符合统计语境。", "男性": "语义：「男性比男性」比较对象重复，没有比较意义。", "动物": "语义：动物与人群的平均寿命不构成比较，句子不通。", "猫": "搭配：「平均寿命」用于人群统计，「猫」与「男性」不能进行这种比较。"}, "sentence_index": 0, "correct_answer": "女性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只母牛是女性。", "explanation": "这里应该用〈雌性〉。「女性」只用于人类，动物应说「雌性」。"}, {"text": "我的女性在厨房里做饭。", "explanation": "这里应该用〈妻子〉。「女性」泛指女人，不能用来指称自己的配偶。"}, {"text": "他是一位女性。", "explanation": "这里应该用〈男性〉。「他」指男子，「女性」指女人，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女性", "is_correct": true, "explanation": "正确：「女性」与后面的「的工作和生活」搭配，指研究的对象是女性群体。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不工作，「宠物的工作」语义不通。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：建筑没有工作和生活，句子与常识相矛盾。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：天气没有「工作和生活」，「天气的工作和生活」语义不通。"}], "explanations": {"女性": "正确：「女性」与后面的「的工作和生活」搭配，指研究的对象是女性群体。", "宠物": "语义：宠物不工作，「宠物的工作」语义不通。", "建筑": "语义：建筑没有工作和生活，句子与常识相矛盾。", "天气": "搭配：天气没有「工作和生活」，「天气的工作和生活」语义不通。"}, "sentence_index": 6, "correct_answer": "女性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我认识一头女性。", "explanation": "这里应该用〈位〉。「头」用于牛等大型动物，「女性」指人，应用量词「位」。"}, {"text": "张女性是我的老师。", "explanation": "这里应该用〈女士〉。姓氏后的尊称应说「张女士」，「女性」不能用作尊称。"}, {"text": "这只母狗是女性。", "explanation": "这里应该用〈雌性〉。「女性」只用于人类，动物应说「雌性」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两位女性们都很优秀。", "corrected_sentence": "这两位女性都很优秀。", "error_description": "「这两位」已经表示数量，「女性们」再加复数后缀「们」属于重复，应去掉「们」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只女性在银行工作。", "corrected_sentence": "一位女性在银行工作。", "error_description": "「女性」指人，量词应用「位」，「只」用于动物。「一只女性」中量词错误，应改为「一位女性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
