INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "西边的地区。", "primary_collocate": null, "pronunciation": "xī bù", "ipa": "ɕi˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "中国的西部有很多高山。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去西部看看大草原。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西部的天气比东部干。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的西部人口不多。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西部的冬天又冷又长。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友住在这个城市的西部。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西部有一条很长的河。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我们开车去了西部。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西部的路不太好走。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要帮助西部的孩子读书。", "target_word": "西部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "西部地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "西边的地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西部", "is_correct": true, "explanation": "“西部”是地区，中国的西部多高山，句子成立。"}, {"text": "平原", "is_correct": false, "explanation": "语义：平原地势平坦，不会有很多高山，句子不成立。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是室内场所，不可能有很多高山。"}, {"text": "厨房", "is_correct": false, "explanation": "体貌：厨房面积小，是室内空间，与“很多高山”不相称。"}], "explanations": {"西部": "“西部”是地区，中国的西部多高山，句子成立。", "平原": "语义：平原地势平坦，不会有很多高山，句子不成立。", "教室": "语义：教室是室内场所，不可能有很多高山。", "厨房": "体貌：厨房面积小，是室内空间，与“很多高山”不相称。"}, "sentence_index": 0, "correct_answer": "西部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "西部国家都很重视教育。", "explanation": "这里应该用〈西方〉。“西方”泛指欧美国家，不说“西部国家”。"}, {"text": "我们向西部转，然后一直走。", "explanation": "这里应该用〈西〉。〈西部〉指地区，表示方向要说“向西”。"}, {"text": "我的朋友是西部。", "explanation": "〈西部〉指地区，不指人，这里应说〈西部人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西部", "is_correct": true, "explanation": "“西部”是地方，可以有河，句子成立。"}, {"text": "书桌", "is_correct": false, "explanation": "体貌：书桌体积小，不可能有一条很长的河。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服是物品，不是地方，不能“有一条很长的河”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是随身物品，不是可以有河的地方。"}], "explanations": {"西部": "“西部”是地方，可以有河，句子成立。", "书桌": "体貌：书桌体积小，不可能有一条很长的河。", "衣服": "语义：衣服是物品，不是地方，不能“有一条很长的河”。", "书包": "语义：书包是随身物品，不是可以有河的地方。"}, "sentence_index": 6, "correct_answer": "西部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山顶看见了一颗西部。", "explanation": "〈西部〉指地区，不是可以看见的具体事物；“颗”只用于星星、太阳等天体，换用其他量词也不成立。"}, {"text": "这顿饭的西部很好吃。", "explanation": "〈西部〉指地区，不指食物的一部分，这里用错了。"}, {"text": "我买了一位西部。", "explanation": "〈西部〉指地区，不是可买的具体物品；“位”只用于人，换用“个”也不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明年要去西部里旅游。", "corrected_sentence": "我们明年要去西部旅游。", "error_description": "方位词误用：「西部」本身就是表示地区的方位名词，后面不能再加「里」。错误形式是「去西部里旅游」，正确形式是「去西部旅游」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车开了到西部。", "corrected_sentence": "车开到了西部。", "error_description": "“了”的位置错误：“了”应放在结果补语“到”之后，应说“车开到了西部”，不说“车开了到西部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
