INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86523, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86523, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "角度是你从哪一边来看事情。", "primary_collocate": null, "pronunciation": "jiǎo dù", "ipa": "tɕjaʊ˨˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "从学生的角度看，作业太多了。", "target_word": "角度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想从另一个角度回答问题。", "target_word": "角度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人看事情的角度不一样。", "target_word": "角度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "换个角度想，你就不会生气了。", "target_word": "角度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请我们从不同角度写作文。", "target_word": "角度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在客人的角度想，这样做不太好。", "target_word": "角度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个角度很新，我以前没想过。", "target_word": "角度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的角度和我的不一样，所以我们吵起来了。", "target_word": "角度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是从孩子的角度想事情。", "target_word": "角度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要从多个角度看这件事。", "target_word": "角度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "看事情的出发点、立场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55ba4b8-27ee-40aa-8987-109ad1bec8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能作为“从……看”的立场，这句话说不通。"}, {"text": "角度", "is_correct": true, "explanation": "正确：“从学生的角度看”指站在学生的立场看事情，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能用来表示看事情的立场。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指人的长相，不能作为“从……看”作业多少的出发点。"}], "explanations": {"桌子": "语义：桌子是家具，不能作为“从……看”的立场，这句话说不通。", "角度": "正确：“从学生的角度看”指站在学生的立场看事情，与句意相符。", "窗户": "语义：窗户是建筑部件，不能用来表示看事情的立场。", "外貌": "体貌：外貌指人的长相，不能作为“从……看”作业多少的出发点。"}, "sentence_index": 0, "correct_answer": "角度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆新车的角度很快。", "explanation": "这里应该用〈速度〉。角度指看事情的出发点，说车的快慢要用速度，不能说“角度很快”。"}, {"text": "这箱苹果的角度很重。", "explanation": "这里应该用〈重量〉。角度不能用来说物体的轻重，说轻重要用重量。"}, {"text": "这块石头的角度很硬。", "explanation": "这里应该用〈硬度〉。角度不表示物体的软硬，说软硬要用硬度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用“很新”来形容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指冷暖阴晴，说“天气很新”不通，也不能指看事情的方式。"}, {"text": "角度", "is_correct": true, "explanation": "正确：“这个角度很新”描述的是看事情的立场或方式，与“我以前没想过”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指岁数，不能用“很新”来形容，也不能指看事情的立场。"}], "explanations": {"身材": "体貌：“身材”指人的体形，不能用“很新”来形容。", "天气": "语义：天气指冷暖阴晴，说“天气很新”不通，也不能指看事情的方式。", "角度": "正确：“这个角度很新”描述的是看事情的立场或方式，与“我以前没想过”相符。", "年龄": "语义：年龄指岁数，不能用“很新”来形容，也不能指看事情的立场。"}, "sentence_index": 6, "correct_answer": "角度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事的角度很认真。", "explanation": "这里应该用〈态度〉。“认真”形容的是态度；角度是看事情的出发点，不能说“认真的角度”。"}, {"text": "他躲在沙发的角度后面看电视。", "explanation": "这里应该用〈角落〉。角落指物体相接的隐蔽处，角度不能指这种空间位置。"}, {"text": "这根绳子的角度很长。", "explanation": "这里应该用〈长度〉。角度指看事情的出发点，说绳子的长短要用长度，不能说“角度很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该从对方地角度想问题。", "corrected_sentence": "我们应该从对方的角度想问题。", "error_description": "结构助词错误：“对方”修饰“角度”时应用“的”，不能用“地”。正确：“从对方的角度想问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请向父母的角度理解一下孩子。", "corrected_sentence": "请从父母的角度理解一下孩子。", "error_description": "错误：介词“向”用错，应为“从”。“向”引出方向或对象，不能引出看事情的出发点；正确说法是“从……角度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
