INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86527, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跳是脚用力离开地面，身体向上或向前。", "primary_collocate": null, "pronunciation": "tiào", "ipa": "tʰjɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "他从桌子上跳下来了。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跳过了那条小河。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上又跳又笑。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力向前跳，就过了河。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙跳进了水里。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能跳过这条线吗？", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她高兴得跳了起来。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳上了桌子。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要跳过前面的水坑。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向前用力一跳，跳到了对面。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跳了", "label": "完成体"}, {"form": "跳着", "label": "持续体"}, {"form": "跳过", "label": "经历体"}, {"form": "跳跳", "label": "重叠"}], "register": "中性", "sense_fingerprint": "脚用力离开地面，身体向上或向前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86527, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跳", "is_correct": true, "explanation": "正确答案。跳 tiào，指脚用力离开地面，身体向上或向前。"}, {"text": "掉", "is_correct": false, "explanation": "tiào 与 diào 声母不同（t 与 d），意思是“掉”（落下）。"}, {"text": "挑", "is_correct": false, "explanation": "tiào（第四声）与 tiāo（第一声）声调不同，意思是“挑选”。"}, {"text": "条", "is_correct": false, "explanation": "tiào（第四声）与 tiáo（第二声）声调不同，意思是“条”（量词或细长物）。"}], "explanations": {"跳": "正确答案。跳 tiào，指脚用力离开地面，身体向上或向前。", "掉": "tiào 与 diào 声母不同（t 与 d），意思是“掉”（落下）。", "挑": "tiào（第四声）与 tiāo（第一声）声调不同，意思是“挑选”。", "条": "tiào（第四声）与 tiáo（第二声）声调不同，意思是“条”（量词或细长物）。"}, "sentence_index": null, "correct_answer": "跳"}, "level_3": {"options": [{"text": "跳", "is_correct": true, "explanation": "正确。“跳下来”表示身体从高处脚用力离开桌面落下，符合语境。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站下来”不能表示从桌子上离开，应说“站起来”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不是身体离开桌面的动作，“从桌子上唱下来”不通。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”需要在水中或借助水的动作，与从桌子上下来的动作不符。"}], "explanations": {"跳": "正确。“跳下来”表示身体从高处脚用力离开桌面落下，符合语境。", "站": "搭配：“站下来”不能表示从桌子上离开，应说“站起来”。", "唱": "语义：“唱”不是身体离开桌面的动作，“从桌子上唱下来”不通。", "游": "语义：“游”需要在水中或借助水的动作，与从桌子上下来的动作不符。"}, "sentence_index": 0, "correct_answer": "跳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只鸟在天上跳来跳去。", "explanation": "这里应该用〈飞〉。跳需要双脚用力蹬地离开地面，鸟在天上靠翅膀飞行。"}, {"text": "他一伸手，把杯子跳到了地上，摔碎了。", "explanation": "这里应该用〈推〉。跳是不及物动作，不能用“把”字句带“杯子”移动，应说“推”。"}, {"text": "树叶从树上跳下来了。", "explanation": "这里应该用〈落〉。跳要求主动用脚蹬地，树叶飘下来应说“落”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳", "is_correct": true, "explanation": "正确。“跳了起来”表示身体突然跃起，与“高兴得”的语境相符。"}, {"text": "躺", "is_correct": false, "explanation": "搭配：“躺起来”不是高兴时身体的动作，搭配不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡了起来”与“高兴得”的兴奋情绪不合，睡不表示突然跃起。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“病”是生病的意思，不能加“了起来”表示动作开始。"}], "explanations": {"跳": "正确。“跳了起来”表示身体突然跃起，与“高兴得”的语境相符。", "躺": "搭配：“躺起来”不是高兴时身体的动作，搭配不通。", "睡": "语义：“睡了起来”与“高兴得”的兴奋情绪不合，睡不表示突然跃起。", "病": "搭配：“病”是生病的意思，不能加“了起来”表示动作开始。"}, "sentence_index": 6, "correct_answer": "跳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用脚把球跳进了网。", "explanation": "这里应该用〈踢〉。跳是不及物动词，不能带“球”作宾语，把球踢进网要用“踢”。"}, {"text": "他不小心跳了一跤。", "explanation": "这里应该用〈摔〉。摔跤是身体失去平衡倒地，不能说“跳了一跤”。"}, {"text": "他跳了一下，把衣服跳到地上。", "explanation": "这里应该用〈扔〉。跳是人的不及物动作，不能带“衣服”作宾语表示移动，把衣服扔到地上要用“扔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗从床上跳下了来。", "corrected_sentence": "小狗从床上跳下来了。", "error_description": "错误：趋向补语“下来”被拆开，“下了来”不成立。正确：应说“跳下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们跳了过水坑。", "corrected_sentence": "我们跳过了水坑。", "error_description": "错误：“过”应紧跟动词“跳”构成“跳过”，中间不能插入“了”。正确：应说“跳过了水坑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
