INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86528, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两脚用力使身体离开地面。", "primary_collocate": null, "pronunciation": "tiào", "ipa": "tʰjɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "他两脚用力，跳得很高。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在床上跳来跳去。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家站好，一起跳十下。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上跳五分钟，身体越来越好。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跳不高，但是他跳得很高。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球运动员用力跳起来，把球投进去。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在原地，跳了三下。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跳着喊我的名字。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友跳得太高，差点儿摔倒。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再跳一下，我看看你的腿。", "target_word": "跳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跳了", "label": "完成体"}, {"form": "跳着", "label": "持续体"}, {"form": "跳过", "label": "经历体"}, {"form": "跳跳", "label": "重叠"}], "register": "中性", "sense_fingerprint": "两脚用力使身体离开地面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86528, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跳", "is_correct": true, "explanation": "正确答案。跳 tiào，指两脚用力使身体离开地面。"}, {"text": "掉", "is_correct": false, "explanation": "tiào 与 diào 声母不同（t 与 d），意思是“掉”（落下）。"}, {"text": "挑", "is_correct": false, "explanation": "tiào（第四声）与 tiāo（第一声）声调不同，意思是“挑选”。"}, {"text": "条", "is_correct": false, "explanation": "tiào（第四声）与 tiáo（第二声）声调不同，意思是“条”（量词或细长物）。"}], "explanations": {"跳": "正确答案。跳 tiào，指两脚用力使身体离开地面。", "掉": "tiào 与 diào 声母不同（t 与 d），意思是“掉”（落下）。", "挑": "tiào（第四声）与 tiāo（第一声）声调不同，意思是“挑选”。", "条": "tiào（第四声）与 tiáo（第二声）声调不同，意思是“条”（量词或细长物）。"}, "sentence_index": null, "correct_answer": "跳"}, "level_3": {"options": [{"text": "跳", "is_correct": true, "explanation": "正确。“跳得很高”表示两脚用力使身体向上离地，符合“两脚用力”的语境。"}, {"text": "躺", "is_correct": false, "explanation": "搭配：“躺得很高”不能说，躺不表示身体向上离开地面。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“两脚用力”无关，“吃得很高”不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”不表示向上用力离地，与“两脚用力”的动作冲突。"}], "explanations": {"跳": "正确。“跳得很高”表示两脚用力使身体向上离地，符合“两脚用力”的语境。", "躺": "搭配：“躺得很高”不能说，躺不表示身体向上离开地面。", "吃": "语义：“吃”与“两脚用力”无关，“吃得很高”不通。", "睡": "语义：“睡”不表示向上用力离地，与“两脚用力”的动作冲突。"}, "sentence_index": 0, "correct_answer": "跳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上跳五公里，身体越来越好。", "explanation": "这里应该用〈跑〉。跳是原地或短距离的蹬地动作，不能用来表示跑五公里这样的长距离移动。"}, {"text": "他每天早上跳五分钟船，身体越来越好。", "explanation": "这里应该用〈划〉。跳不能带“船”作宾语，划船才用“划”。"}, {"text": "他每天早上跳十公斤，身体越来越好。", "explanation": "这里应该用〈举〉。跳是动作，不能用公斤计量，锻炼力量应说“举十公斤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳", "is_correct": true, "explanation": "正确。“跳了三下”表示做了三次跳的动作，与“站在原地”相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”不能用动量词“下”计次，“哭了三下”不通。"}, {"text": "懂", "is_correct": false, "explanation": "语义：“懂”是心理状态，不能用动量词“下”计次，“懂了三下”不通。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“病”是生病的意思，不能用动量词“下”计次。"}], "explanations": {"跳": "正确。“跳了三下”表示做了三次跳的动作，与“站在原地”相符。", "哭": "语义：“哭”不能用动量词“下”计次，“哭了三下”不通。", "懂": "语义：“懂”是心理状态，不能用动量词“下”计次，“懂了三下”不通。", "病": "搭配：“病”是生病的意思，不能用动量词“下”计次。"}, "sentence_index": 6, "correct_answer": "跳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你再把腿跳一下，我看看你的腿。", "explanation": "这里应该用〈抬〉。跳是不及物动作，不能用“把”带“腿”作宾语，把腿举起来应说“抬”。"}, {"text": "这只鸟在天上跳来跳去。", "explanation": "这里应该用〈飞〉。跳需要双脚用力蹬地，鸟在天上靠翅膀飞行。"}, {"text": "树叶在空中跳了一下，就落在地上。", "explanation": "这里应该用〈飘〉或〈落〉。跳要求主动用脚蹬地，树叶靠风飘落，不能用“跳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子跳很得高。", "corrected_sentence": "孩子跳得很高。", "error_description": "错误：补语结构“跳得很高”中，“得”被挪到“很”之后。正确：应说“跳得很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她站在原地，跳了几个。", "corrected_sentence": "她站在原地，跳了几下。", "error_description": "错误：动作的计量用了“个”，“个”用于计量人或事物，不能计量跳的次数。正确：应说“跳了几下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
