INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86531, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "确定是想好了，不再改变。", "primary_collocate": null, "pronunciation": "què dìng", "ipa": "tɕʰɥe˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我确定明年去中国工作。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他确定要换工作，下个月就走。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已经确定了，不会再改。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我确定不去了，你们去吧。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她确定要学中文，不想学法语了。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想好了就确定下来，别再变了。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她确定要和他结婚了，谁劝也没用。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我确定今年夏天回国，票都买了。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还没想好，不能确定要不要去。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我确定了这个办法，大家别再说了。", "target_word": "确定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "确定了", "label": "体标"}, {"form": "确定过", "label": "体标"}, {"form": "确定下来", "label": "复合"}], "register": "中性", "sense_fingerprint": "想好后做决定，不再改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55ba4b8-27ee-40aa-8987-109ad1bec8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回忆", "is_correct": false, "explanation": "语义：回忆指想起过去的事，不能用于说明明年的计划。"}, {"text": "确定", "is_correct": true, "explanation": "正确：“确定”表示想好后定下来，与“明年去中国工作”搭配，符合句意。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：怀念指思念过去，与“明年去中国工作”的计划相矛盾。"}, {"text": "颁布", "is_correct": false, "explanation": "语域：“颁布”是正式用语，指发布法令，不能用于个人的打算。"}], "explanations": {"回忆": "语义：回忆指想起过去的事，不能用于说明明年的计划。", "确定": "正确：“确定”表示想好后定下来，与“明年去中国工作”搭配，符合句意。", "怀念": "语义：怀念指思念过去，与“明年去中国工作”的计划相矛盾。", "颁布": "语域：“颁布”是正式用语，指发布法令，不能用于个人的打算。"}, "sentence_index": 0, "correct_answer": "确定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他确定很累，不想去了。", "explanation": "这里应该用〈确实〉。确定指人想好或弄清后定下来，不表示“的确、实在”的语气。"}, {"text": "他确定地跑向终点。", "explanation": "这里应该用〈飞快地〉。确定指事情定下来或清楚，不用来描述跑的快慢；表达速度要用飞快地。"}, {"text": "物价很确定。", "explanation": "这里应该用〈稳定〉。物价的平稳不变要用稳定，确定指事情明确，不形容物价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：散步是走路锻炼，不能接“要和他结婚”这样的决定。"}, {"text": "确定", "is_correct": true, "explanation": "正确：“确定”表示想好后定下来、不再改变，后面可以接“要……”，与“谁劝也没用”相符。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的宾语是人或事，不能接“要和他结婚”这样的动作。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：丢失指东西找不到，与“要和他结婚”的决定无关。"}], "explanations": {"散步": "语义：散步是走路锻炼，不能接“要和他结婚”这样的决定。", "确定": "正确：“确定”表示想好后定下来、不再改变，后面可以接“要……”，与“谁劝也没用”相符。", "感谢": "配价：“感谢”的宾语是人或事，不能接“要和他结婚”这样的动作。", "丢失": "语义：丢失指东西找不到，与“要和他结婚”的决定无关。"}, "sentence_index": 6, "correct_answer": "确定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天确定会下雨。", "explanation": "这里应该用〈肯定〉。确定指人想好或弄清后定下来，不用于对天气的推测。"}, {"text": "这家饭馆确定很好吃。", "explanation": "这里应该用〈确实〉。确定指人想好或弄清后定下来，不表示“的确、实在”的语气。"}, {"text": "这个结果确定会改变。", "explanation": "这里应该用〈必然〉。确定指人作出决定或弄清情况，不用来断定事情的必然变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划我们终于确定上来了。", "corrected_sentence": "这个计划我们终于确定下来了。", "error_description": "错误：补语“上来”用错，应为“下来”。“确定下来”表示定下来、不再改变；“确定上来”不能这样用。学习者常把“下来”和“上来”混用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没确定了去不去。", "corrected_sentence": "我还没确定去不去。", "error_description": "错误：“确定”后多了体标“了”，与“还没”冲突，应为“还没确定去不去”。“还没”表示尚未发生，不能与“了”同用。学习者常把“还没”和“了”一起用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86532, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
