INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86532, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "明确地定下来；使清楚、固定而不再变动。", "primary_collocate": null, "pronunciation": "què dìng", "ipa": "tɕʰɥe˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "会议的时间还没确定。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先确定一下比赛的地点。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师已经确定了考试的日期。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划的名字确定了吗？", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理把开会的时间确定在星期五。", "target_word": "确定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先确定好人数，再订饭店。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生确定了病人的手术时间。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家确定了旅行的路线。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格一确定，我们就可以签字。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们还没有确定谁来当队长。", "target_word": "确定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "确定了", "label": "体标"}, {"form": "确定过", "label": "体标"}, {"form": "确定下来", "label": "复合"}], "register": "中性", "sense_fingerprint": "把时间、地点等明确定下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55ba4b8-27ee-40aa-8987-109ad1bec8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出席", "is_correct": false, "explanation": "搭配：“出席”的主语应是人，不能说“会议的时间”出席。"}, {"text": "确定", "is_correct": true, "explanation": "正确：“确定”表示把时间定下来，与“还没……”搭配，符合句意。"}, {"text": "回答", "is_correct": false, "explanation": "搭配：“回答”的对象是问题，不能用“会议的时间”作宾语。"}, {"text": "参观", "is_correct": false, "explanation": "语义：参观指去看地方或展览，与时间的安排无关。"}], "explanations": {"出席": "搭配：“出席”的主语应是人，不能说“会议的时间”出席。", "确定": "正确：“确定”表示把时间定下来，与“还没……”搭配，符合句意。", "回答": "搭配：“回答”的对象是问题，不能用“会议的时间”作宾语。", "参观": "语义：参观指去看地方或展览，与时间的安排无关。"}, "sentence_index": 0, "correct_answer": "确定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情很确定。", "explanation": "这里应该用〈平静〉。心情、情绪的平稳要用平静；确定指事情定下来或清楚，不形容心情。"}, {"text": "他确定地笑了起来。", "explanation": "这里应该用〈开心地〉。确定不用来描述笑的心情，表达高兴要用开心地。"}, {"text": "这家店的服务很确定。", "explanation": "这里应该用〈周到〉。服务的好坏要用周到来形容；确定指事情明确，不形容服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝”指吞咽饮品，不能用于定下手术时间。"}, {"text": "确定", "is_correct": true, "explanation": "正确：“确定”表示把时间定下来，与“手术时间”搭配，符合句意。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的宾语是人或事物，不能与“手术时间”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与定下时间无关。"}], "explanations": {"喝": "语义：“喝”指吞咽饮品，不能用于定下手术时间。", "确定": "正确：“确定”表示把时间定下来，与“手术时间”搭配，符合句意。", "感谢": "配价：“感谢”的宾语是人或事物，不能与“手术时间”搭配。", "唱": "语义：“唱”指发出歌声，与定下时间无关。"}, "sentence_index": 6, "correct_answer": "确定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷的身体很确定。", "explanation": "这里应该用〈健康〉。确定指把时间、地点等明确定下来，不能形容身体状况。"}, {"text": "这样做的结果确定会失败。", "explanation": "这里应该用〈必然〉。确定指把时间、地点等明确定下来，不用来断定事情的必然结果。"}, {"text": "他确定地做完了作业。", "explanation": "这里应该用〈迅速地〉。确定指事情定下来或清楚，不用来说做事的快慢，表达快慢要用迅速地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把聚餐的地点确定到学校门口。", "corrected_sentence": "我们把聚餐的地点确定在学校门口。", "error_description": "错误：补语介词用错，“到”应为“在”。“确定在……”表示把地点定在某处；“确定到”不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题还没确定上来。", "corrected_sentence": "这个问题还没确定下来。", "error_description": "错误：补语“上来”用错，应为“下来”。“确定下来”表示定下来、不再改变；“确定上来”不能这样用。学习者常把“下来”和“上来”混用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
