INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "丈夫是和妈妈结了婚的那个男人。", "primary_collocate": null, "pronunciation": "zhàng fu", "ipa": "ʈʂɑŋ˥˩ fu", "syllable_count": 2, "sentences": [{"text": "我妈妈的丈夫是我爸爸。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的丈夫在医院工作。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈和她的丈夫一起去旅行了。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈的丈夫每天开车送我上学。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈的丈夫很喜欢做饭。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的丈夫是一位工程师。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我妈妈的丈夫，我叫他叔叔。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的丈夫昨天送了我一本书。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈和丈夫在厨房做晚饭。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆说，妈妈的丈夫是个好人。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "从孩子或家人的角度，指与某位女性结婚的男人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丈夫", "is_correct": true, "explanation": "「丈夫」指妈妈的配偶，与「是我爸爸」的家庭关系相符。"}, {"text": "妻子", "is_correct": false, "explanation": "语义：「妻子」指男方的配偶，句中的「妈妈」是女性，两者不能构成这样的关系。"}, {"text": "姐姐", "is_correct": false, "explanation": "语义：「姐姐」是女性，「我妈妈的姐姐」不能是「我爸爸」，性别不合。"}, {"text": "女儿", "is_correct": false, "explanation": "语义：「女儿」是女性子女，不能是「我爸爸」，性别与亲属关系都不合。"}], "explanations": {"丈夫": "「丈夫」指妈妈的配偶，与「是我爸爸」的家庭关系相符。", "妻子": "语义：「妻子」指男方的配偶，句中的「妈妈」是女性，两者不能构成这样的关系。", "姐姐": "语义：「姐姐」是女性，「我妈妈的姐姐」不能是「我爸爸」，性别不合。", "女儿": "语义：「女儿」是女性子女，不能是「我爸爸」，性别与亲属关系都不合。"}, "sentence_index": 0, "correct_answer": "丈夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈的丈夫是我的姐姐。", "explanation": "这里应该用〈爸爸〉。「丈夫」指妈妈的男性配偶，「姐姐」是女性同辈，与之矛盾。"}, {"text": "我妈妈的丈夫是一位女士。", "explanation": "「丈夫」一定是男性，不能是「女士」，两者矛盾。应说「我妈妈的丈夫是一位先生」。"}, {"text": "我妈妈的丈夫很年轻，还没结过婚。", "explanation": "这里应该用〈男朋友〉。「丈夫」已经表示结了婚的男性配偶，未婚的男性伴侣应说〈男朋友〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丈夫", "is_correct": true, "explanation": "「丈夫」指妈妈的配偶，与「我叫他叔叔」的称呼相符。"}, {"text": "弟弟", "is_correct": false, "explanation": "语义：「弟弟」是妈妈的同胞兄弟，应叫「舅舅」，不能叫「叔叔」。"}, {"text": "儿子", "is_correct": false, "explanation": "语义：「儿子」是妈妈的儿子，即我的兄弟，不能叫「叔叔」，句意不通。"}, {"text": "侄子", "is_correct": false, "explanation": "语义：「侄子」是妈妈的侄子，与我是表亲，不能叫「叔叔」，句意不通。"}], "explanations": {"丈夫": "「丈夫」指妈妈的配偶，与「我叫他叔叔」的称呼相符。", "弟弟": "语义：「弟弟」是妈妈的同胞兄弟，应叫「舅舅」，不能叫「叔叔」。", "儿子": "语义：「儿子」是妈妈的儿子，即我的兄弟，不能叫「叔叔」，句意不通。", "侄子": "语义：「侄子」是妈妈的侄子，与我是表亲，不能叫「叔叔」，句意不通。"}, "sentence_index": 6, "correct_answer": "丈夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈的丈夫还在上小学。", "explanation": "这里应该用〈儿子〉。「丈夫」指成年并已婚的男性配偶，上小学的孩子是妈妈的儿子。"}, {"text": "妈妈的丈夫是一只小狗。", "explanation": "这里应该用〈宠物〉。「丈夫」指人，动物不能充当丈夫。"}, {"text": "妈妈的丈夫是我的弟弟。", "explanation": "这里应该用〈爸爸〉。「丈夫」是妈妈的配偶，「弟弟」是晚辈男子，两者的亲属关系不能成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈有一只丈夫。", "corrected_sentence": "我妈妈有一位丈夫。", "error_description": "量词错误：「丈夫」指人，应用「位」或「个」，「只」多用于动物，不能修饰人。应说「我妈妈有一位丈夫」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我妈妈丈夫。", "corrected_sentence": "他是我妈妈的丈夫。", "error_description": "漏了「的」：「我妈妈」修饰「丈夫」时，中间必须用「的」连接，应说「我妈妈的丈夫」。去掉「的」会使定语与中心语之间的关系不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
