INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "已婚女子的配偶，即男方。", "primary_collocate": null, "pronunciation": "zhàng fu", "ipa": "ʈʂɑŋ˥˩ fu", "syllable_count": 2, "sentences": [{"text": "她的丈夫是老师。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王太太对丈夫很好。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和丈夫去年一起去了日本。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的丈夫每天早上做早饭。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张女士的丈夫在医院工作。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子给丈夫买了一件新衣服。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位好丈夫，也是一位好爸爸。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边工作，一边照顾孩子和丈夫。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丈夫出差了，她一个人在家。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李红和丈夫都喜欢旅行。", "target_word": "丈夫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "从妻子的角度，指已婚女子的配偶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丈夫", "is_correct": true, "explanation": "「丈夫」指已婚女子的配偶，与「她的……是老师」的句子相符。"}, {"text": "妻子", "is_correct": false, "explanation": "语义：「妻子」指男方的配偶，句中的「她」是女性，与配偶的身份不合。"}, {"text": "房子", "is_correct": false, "explanation": "语义：「房子」是物，不能作人的配偶，「她的房子是老师」句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：「汽车」是物，不能作人的身份，「她的汽车是老师」句意不通。"}], "explanations": {"丈夫": "「丈夫」指已婚女子的配偶，与「她的……是老师」的句子相符。", "妻子": "语义：「妻子」指男方的配偶，句中的「她」是女性，与配偶的身份不合。", "房子": "语义：「房子」是物，不能作人的配偶，「她的房子是老师」句意不通。", "汽车": "语义：「汽车」是物，不能作人的身份，「她的汽车是老师」句意不通。"}, "sentence_index": 0, "correct_answer": "丈夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的丈夫今年刚出生。", "explanation": "这里应该用〈儿子〉。「丈夫」指已经结婚的配偶，刚出生的婴儿不能结婚。"}, {"text": "她的丈夫是一位女士。", "explanation": "这里应该用〈妻子〉表示女性配偶。「丈夫」指男性，与「女士」矛盾。"}, {"text": "她的丈夫在幼儿园上学。", "explanation": "这里应该用〈孩子〉。「丈夫」要求成年并已婚，幼儿园的小朋友是孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丈夫", "is_correct": true, "explanation": "「丈夫」指男性配偶，「他是一位好……，也是一位好爸爸」的句子相符。"}, {"text": "女儿", "is_correct": false, "explanation": "语义：「女儿」指女性子女，与句中「他」的男性身份不合。"}, {"text": "女朋友", "is_correct": false, "explanation": "语义：「女朋友」指女性恋人，与句中「他」的男性身份不合。"}, {"text": "女士", "is_correct": false, "explanation": "搭配：「女士」是对成年女性的称呼，不能用来描述男性的身份。"}], "explanations": {"丈夫": "「丈夫」指男性配偶，「他是一位好……，也是一位好爸爸」的句子相符。", "女儿": "语义：「女儿」指女性子女，与句中「他」的男性身份不合。", "女朋友": "语义：「女朋友」指女性恋人，与句中「他」的男性身份不合。", "女士": "搭配：「女士」是对成年女性的称呼，不能用来描述男性的身份。"}, "sentence_index": 6, "correct_answer": "丈夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "李红的丈夫明天要结婚了。", "explanation": "这里应该用〈未婚夫〉。「丈夫」已经表示结了婚，「明天要结婚」的男性是未婚夫。"}, {"text": "李红的丈夫是一棵树。", "explanation": "「丈夫」指人，一棵树不能是人的丈夫，语义矛盾。应说「李红的丈夫是一位医生」之类。"}, {"text": "李红的丈夫是她的妈妈。", "explanation": "「丈夫」是男性配偶，「妈妈」是女性长辈，两者矛盾。应说「李红的丈夫是一位老师」之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一本好丈夫。", "corrected_sentence": "她有一个好丈夫。", "error_description": "量词用错了：「本」用于书本等物品，不能用于人。「丈夫」是人，应该用「个」（或「位」），说「她有一个好丈夫」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个称职丈夫。", "corrected_sentence": "他是个称职的丈夫。", "error_description": "双音节形容词「称职」作定语修饰名词时通常要加「的」，应说「他是个称职的丈夫」；单音节的「好」（如「好丈夫」）可以不加。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
