INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上年是今年前面的那一年。", "primary_collocate": null, "pronunciation": "shàng nián", "ipa": "ʂɑŋ˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "上年的今天，我们正好在海边玩。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥上年大学毕业，今年找到了工作。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是上年出的，今年还在卖。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起上年，今年的苹果便宜多了。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上年春天，爷爷搬到了我们家住。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校上年新建了一个大图书馆。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上年存的钱，今年全花完了。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上年考试他得了第一，今年也不错。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈上年种的花，今年开得很好看。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上年他每天跑步，所以今年身体很好。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "时间名词：今年前面的那一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd727e10f-1248-4124-9d4c-8b97d0ca17dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上年", "is_correct": true, "explanation": "“上年”指去年，“上年的今天”表示去年的同一天，与语境相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不是时间词，不能与“今天”组成时间修饰。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是时间词，不能表示某一天。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不是时间词，不能表示某一天。"}], "explanations": {"上年": "“上年”指去年，“上年的今天”表示去年的同一天，与语境相符。", "窗户": "语义：“窗户”不是时间词，不能与“今天”组成时间修饰。", "桌子": "语义：“桌子”不是时间词，不能表示某一天。", "汽车": "语义：“汽车”不是时间词，不能表示某一天。"}, "sentence_index": 0, "correct_answer": "上年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上年我们要去海边玩。", "explanation": "这里应该用〈明年〉。上年指过去的一年，不能用来说将来的计划。"}, {"text": "我每次上年都去跑步。", "explanation": "这里应该用〈每天〉。上年指一个确定的去年，不能和“每次”搭配表示反复发生。"}, {"text": "上年我正在吃饭，你等一下。", "explanation": "这里应该用〈现在〉。上年指过去的一年，不能表示说话时正在进行的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上年", "is_correct": true, "explanation": "“上年”指去年，“我上年存的钱”指去年存下的钱，与“今年全花完了”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：钱不存在冰箱里，“冰箱存的钱”说不通。"}, {"text": "下周", "is_correct": false, "explanation": "语义：下周的钱还没有存，与“今年全花完了”的时间关系矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是时间词，也不能存钱，“我桌子存的钱”说不通。"}], "explanations": {"上年": "“上年”指去年，“我上年存的钱”指去年存下的钱，与“今年全花完了”相符。", "冰箱": "语义：钱不存在冰箱里，“冰箱存的钱”说不通。", "下周": "语义：下周的钱还没有存，与“今年全花完了”的时间关系矛盾。", "桌子": "语义：“桌子”不是时间词，也不能存钱，“我桌子存的钱”说不通。"}, "sentence_index": 6, "correct_answer": "上年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个星期的天气比上年暖和多了。", "explanation": "这里应该用〈上个星期〉。上年指整整一年，不能和一个星期的天气直接比较。"}, {"text": "我上年的时候，明年就要毕业了。", "explanation": "这里应该用〈今年〉。上年指过去的一年，与“明年就要毕业”的将来时间相矛盾。"}, {"text": "他每次上年都跑步，所以今年身体很好。", "explanation": "这里应该用〈每天〉。上年指一个确定的去年，不能和“每次”搭配表示反复发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上年了冬天，我们去了海边。", "corrected_sentence": "上年冬天，我们去了海边。", "error_description": "错误在于“上年”是时间名词，后面不能加“了”。正确说法是“上年冬天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上年的去了北京。", "corrected_sentence": "他上年去了北京。", "error_description": "错误在于“的”被插在时间状语“上年”和动词“去”之间，多余。正确说法是“他上年去了北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
