INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86538, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指今年的前一年，即去年。", "primary_collocate": null, "pronunciation": "shàng nián", "ipa": "ʂɑŋ˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "上年我家的收入比今年少一些。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上年夏天去过一次北京。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的雨水比上年多很多。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上年这个时候，我还在国外工作。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司上年卖出了五千台电视。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她上年才开始学做饭，现在做得很好。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上年的冬天特别冷，今年暖和多了。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店今年的客人比上年少。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上年他买了一辆新车，今年又换了房子。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把上年的照片找出来了。", "target_word": "上年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "时间名词：今年的前一年，即去年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd727e10f-1248-4124-9d4c-8b97d0ca17dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上年", "is_correct": true, "explanation": "“上年”指今年的前一年，与“比今年少”的比较相符。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是一天中的时段，不能与全年的收入相比。"}, {"text": "上周", "is_correct": false, "explanation": "搭配：“上周”是一周，不能与“今年”的全年收入比较。"}, {"text": "早上", "is_correct": false, "explanation": "语义：“早上”指一天中的时段，与“今年”的收入比较不成立。"}], "explanations": {"上年": "“上年”指今年的前一年，与“比今年少”的比较相符。", "下午": "语义：“下午”是一天中的时段，不能与全年的收入相比。", "上周": "搭配：“上周”是一周，不能与“今年”的全年收入比较。", "早上": "语义：“早上”指一天中的时段，与“今年”的收入比较不成立。"}, "sentence_index": 0, "correct_answer": "上年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我上年要去上海出差。", "explanation": "这里应该用〈明年〉。上年指过去的一年，不能用来说将来的安排。"}, {"text": "你上年再给我打电话吧。", "explanation": "这里应该用〈明天〉。上年指过去的一年，不能用来请别人将来做某事。"}, {"text": "我上年就要出发去旅行了。", "explanation": "这里应该用〈今年〉。上年是过去的一年，不能与“就要出发”这样的将来动作搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上年", "is_correct": true, "explanation": "“上年”指去年，与“冬天特别冷，今年暖和多了”的对比相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”还没有到来，不能用来和今年的天气对比。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是另一个季节，不能修饰“冬天”。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“昨天”是一天，不能修饰季节“冬天”。"}], "explanations": {"上年": "“上年”指去年，与“冬天特别冷，今年暖和多了”的对比相符。", "明年": "语义：“明年”还没有到来，不能用来和今年的天气对比。", "夏天": "语义：“夏天”是另一个季节，不能修饰“冬天”。", "昨天": "搭配：“昨天”是一天，不能修饰季节“冬天”。"}, "sentence_index": 6, "correct_answer": "上年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每次上年都去公园玩。", "explanation": "这里应该用〈每年〉。上年指一个确定的去年，不能和“每次”搭配表示反复发生。"}, {"text": "我们坐车，上年就到了学校。", "explanation": "这里应该用〈十分钟〉。上年是整年，不能表示坐车到校所用的短时间。"}, {"text": "他最近上年一直在忙工作。", "explanation": "这里应该用〈这段时间〉。上年指去年，不能和“最近”同时出现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们上年着去过一次上海。", "corrected_sentence": "我们上年去过一次上海。", "error_description": "错误在于“上年”是时间名词，后面不能加“着”。正确说法是“我们上年去过一次上海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我上年的来过这里。", "corrected_sentence": "我上年来过这里。", "error_description": "错误在于“的”被插在时间状语“上年”和动词“来”之间，多余。正确说法是“我上年来过这里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86539, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可以", "is_correct": true, "explanation": "正确。“不行”表示不可以，其反义词是“可以”，表示允许。"}, {"text": "聪明", "is_correct": false, "explanation": "与“不行”没有反义关系，“聪明”指头脑灵活。"}, {"text": "安静", "is_correct": false, "explanation": "与“不行”没有反义关系，“安静”指没有声音或动静。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“不行”没有反义关系，“漂亮”指外貌好看。"}], "correct_answer": "可以", "explanations": {"可以": "正确。“不行”表示不可以，其反义词是“可以”，表示允许。", "聪明": "与“不行”没有反义关系，“聪明”指头脑灵活。", "安静": "与“不行”没有反义关系，“安静”指没有声音或动静。", "漂亮": "与“不行”没有反义关系，“漂亮”指外貌好看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86539, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可以", "is_correct": true, "explanation": "正确。“只喝水不吃饭不行”表示不可以，其反义词是“可以”，表示允许。"}, {"text": "高兴", "is_correct": false, "explanation": "与“不行”没有反义关系，“高兴”指愉快的心情。"}, {"text": "认真", "is_correct": false, "explanation": "与“不行”没有反义关系，“认真”指做事专心、不马虎。"}, {"text": "干净", "is_correct": false, "explanation": "与“不行”没有反义关系，“干净”指没有脏东西。"}], "correct_answer": "可以", "explanations": {"可以": "正确。“只喝水不吃饭不行”表示不可以，其反义词是“可以”，表示允许。", "高兴": "与“不行”没有反义关系，“高兴”指愉快的心情。", "认真": "与“不行”没有反义关系，“认真”指做事专心、不马虎。", "干净": "与“不行”没有反义关系，“干净”指没有脏东西。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86539, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不行是不可以，或者不好。", "primary_collocate": null, "pronunciation": "bù xíng", "ipa": "pu˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "你的字写得不行，要多练。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜不行，太咸了。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我唱歌不行，你别听。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是图书馆，大声说话不行。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体不行，别让他搬东西。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想晚上去玩？不行，明天要考试。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，不行了。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做不行，会有危险。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的英语不行，听不懂他的话。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只喝水不吃饭不行啊。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不可以或不好；用于评价水平、质量或表示不允许", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a68a0c0-0cc4-46cf-be05-5ccf26b00493') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不幸", "is_correct": false, "explanation": "xìng 与 xíng 声调不同（第四声与第二声），意思是不幸运。"}, {"text": "不行", "is_correct": true, "explanation": "正确。bù xíng，意思是不好、差。"}, {"text": "不平", "is_correct": false, "explanation": "píng 与 xíng 声母不同（p 与 x），声调相同，意思是不公平。"}, {"text": "不性", "is_correct": false, "explanation": "xìng 与 xíng 声调不同（第四声与第二声），这不是常用词，只是同音近音字。"}], "explanations": {"不幸": "xìng 与 xíng 声调不同（第四声与第二声），意思是不幸运。", "不行": "正确。bù xíng，意思是不好、差。", "不平": "píng 与 xíng 声母不同（p 与 x），声调相同，意思是不公平。", "不性": "xìng 与 xíng 声调不同（第四声与第二声），这不是常用词，只是同音近音字。"}, "sentence_index": null, "correct_answer": "不行"}, "level_3": {"options": [{"text": "不甜", "is_correct": false, "explanation": "搭配：「甜」用于味道，不用来评价写字的好坏。"}, {"text": "不行", "is_correct": true, "explanation": "正确。「写得不行」评价字的水平，表示不好，与“要多练”相合。"}, {"text": "不热", "is_correct": false, "explanation": "语义：「热」说温度，与写字的水平无关，句子不通。"}, {"text": "不咸", "is_correct": false, "explanation": "语义：「咸」说味道，与写字的好坏无关，句子不通。"}], "explanations": {"不甜": "搭配：「甜」用于味道，不用来评价写字的好坏。", "不行": "正确。「写得不行」评价字的水平，表示不好，与“要多练”相合。", "不热": "语义：「热」说温度，与写字的水平无关，句子不通。", "不咸": "语义：「咸」说味道，与写字的好坏无关，句子不通。"}, "sentence_index": 0, "correct_answer": "不行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥不行，比我高半个头。", "explanation": "“不行”表示不好或不可以，不用于比较身高，这里应描述身高，用〈高〉。"}, {"text": "这些菜不行，大家都说它太好吃了。", "explanation": "“不行”表示不好，与“太好吃了”矛盾，此处应用〈好〉。"}, {"text": "这把椅子不行，坐上去很舒服。", "explanation": "“不行”表示不好，与“坐上去很舒服”矛盾，此处应用〈好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86539, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不醒", "is_correct": false, "explanation": "xǐng 与 xíng 声调不同（第三声与第二声），意思是没有醒来。"}, {"text": "不行", "is_correct": true, "explanation": "正确。bù xíng，意思是不好、差。"}, {"text": "不兴", "is_correct": false, "explanation": "xīng 与 xíng 声调不同（第一声与第二声），意思是不流行。"}, {"text": "不明", "is_correct": false, "explanation": "m 与 x 声母不同，声调相同（第二声），意思是不清楚。"}], "explanations": {"不醒": "xǐng 与 xíng 声调不同（第三声与第二声），意思是没有醒来。", "不行": "正确。bù xíng，意思是不好、差。", "不兴": "xīng 与 xíng 声调不同（第一声与第二声），意思是不流行。", "不明": "m 与 x 声母不同，声调相同（第二声），意思是不清楚。"}, "sentence_index": null, "correct_answer": "不行"}, "level_3": {"options": [{"text": "不流利了", "is_correct": false, "explanation": "搭配：「流利」用于说话、写字等能力，不用来形容手机的状态。"}, {"text": "不安静了", "is_correct": false, "explanation": "语义：「安静」说周围没有声音，与“没电”的状态无关，句意不通。"}, {"text": "不行了", "is_correct": true, "explanation": "正确。「手机没电了，不行了」表示手机坏了、不能用，与前句相合。"}, {"text": "不热闹了", "is_correct": false, "explanation": "语义：「热闹」说场面，手机不能用来形容热闹，句子不通。"}], "explanations": {"不流利了": "搭配：「流利」用于说话、写字等能力，不用来形容手机的状态。", "不安静了": "语义：「安静」说周围没有声音，与“没电”的状态无关，句意不通。", "不行了": "正确。「手机没电了，不行了」表示手机坏了、不能用，与前句相合。", "不热闹了": "语义：「热闹」说场面，手机不能用来形容热闹，句子不通。"}, "sentence_index": 6, "correct_answer": "不行了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次作文的开头写得很不行，老师把它选进了范文。", "explanation": "“不行”表示不好，与“选进了范文”矛盾，此处应用〈优秀〉。"}, {"text": "这个蛋糕很不行，大家都抢着吃。", "explanation": "“不行”表示不好，与“大家都抢着吃”矛盾，此处应用〈好吃〉。"}, {"text": "这座桥很不行，能让很多车安全通过。", "explanation": "“不行”表示质量差，与“能让车安全通过”矛盾，这里应用〈好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写字得不行，要多练。", "corrected_sentence": "他写字写得不行，要多练。", "error_description": "补语结构“写得不行”中漏掉了动词“写”，直接说“得不行”不成句。正确形式是“写得不行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种玩具对小孩子行不行，容易吞下去。", "corrected_sentence": "这种玩具对小孩子不行，容易吞下去。", "error_description": "“行不行”是正反问结构，不能用于陈述句。此处应说“不行”，表示不适合。错误是在“不行”前面多加了“行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
