INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86540, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "正确。“身体不行”的反义是“身体好”，“好”指身体状况良好。"}, {"text": "高兴", "is_correct": false, "explanation": "与“不行”没有反义关系，“高兴”指愉快的心情。"}, {"text": "认真", "is_correct": false, "explanation": "与“不行”没有反义关系，“认真”指做事专心、不马虎。"}, {"text": "干净", "is_correct": false, "explanation": "与“不行”没有反义关系，“干净”指没有脏东西。"}], "correct_answer": "好", "explanations": {"好": "正确。“身体不行”的反义是“身体好”，“好”指身体状况良好。", "高兴": "与“不行”没有反义关系，“高兴”指愉快的心情。", "认真": "与“不行”没有反义关系，“认真”指做事专心、不马虎。", "干净": "与“不行”没有反义关系，“干净”指没有脏东西。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86540, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不可以；不能；不好。", "primary_collocate": null, "pronunciation": "bù xíng", "ipa": "pu˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "你一个人去不行，太晚了。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法不行，我们换一个吧。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子这么小，一个人出门不行。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我能先走吗？不行，还没下课。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不行，我要加班。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有票就进去，不行！", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语还不行，要多练习。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑太旧了，不行了。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么冷，不穿外套不行。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我身体不行，不能跑步。", "target_word": "不行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不行了", "label": "体标"}], "register": "口语", "sense_fingerprint": "不可以、不能、不好；口语中用来拒绝或评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a68a0c0-0cc4-46cf-be05-5ccf26b00493') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86540, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不幸", "is_correct": false, "explanation": "xìng 与 xíng 声调不同（第四声与第二声），意思是不幸运。"}, {"text": "不行", "is_correct": true, "explanation": "正确。bù xíng，意思是不可以、不能、不好。"}, {"text": "不平", "is_correct": false, "explanation": "píng 与 xíng 声母不同（p 与 x），声调相同，意思是不公平。"}, {"text": "不性", "is_correct": false, "explanation": "xìng 与 xíng 声调不同（第四声与第二声）。"}], "explanations": {"不幸": "xìng 与 xíng 声调不同（第四声与第二声），意思是不幸运。", "不行": "正确。bù xíng，意思是不可以、不能、不好。", "不平": "píng 与 xíng 声母不同（p 与 x），声调相同，意思是不公平。", "不性": "xìng 与 xíng 声调不同（第四声与第二声）。"}, "sentence_index": null, "correct_answer": "不行"}, "level_3": {"options": [{"text": "不漂亮", "is_correct": false, "explanation": "语义：「漂亮」说外貌，不能用来评价“去”这件事。"}, {"text": "不行", "is_correct": true, "explanation": "正确。「你一个人去不行」表示不可以，与“太晚了”的理由相合。"}, {"text": "不干净", "is_correct": false, "explanation": "语义：「干净」说卫生状况，与“一个人去”无关，句子不通。"}, {"text": "不流利", "is_correct": false, "explanation": "搭配：「流利」用于说话、写作等能力，不用来描述去的情况。"}], "explanations": {"不漂亮": "语义：「漂亮」说外貌，不能用来评价“去”这件事。", "不行": "正确。「你一个人去不行」表示不可以，与“太晚了”的理由相合。", "不干净": "语义：「干净」说卫生状况，与“一个人去”无关，句子不通。", "不流利": "搭配：「流利」用于说话、写作等能力，不用来描述去的情况。"}, "sentence_index": 0, "correct_answer": "不行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次晚会的节目安排很不行，大家都玩得很开心。", "explanation": "“不行”表示不好，与“大家都玩得很开心”矛盾，此处应用〈好〉。"}, {"text": "我可以走吗？不行，已经下课了，你可以走了。", "explanation": "“不行”表示不允许，与后句“你可以走了”矛盾，此处应用〈可以〉。"}, {"text": "这双鞋很不行，它又舒服又好看。", "explanation": "“不行”表示不好，与“又舒服又好看”矛盾，此处应用〈好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86540, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不醒", "is_correct": false, "explanation": "xǐng 与 xíng 声调不同（第三声与第二声），意思是没有醒来。"}, {"text": "不行", "is_correct": true, "explanation": "正确。bù xíng，意思是不可以、不能、不好。"}, {"text": "不兴", "is_correct": false, "explanation": "xīng 与 xíng 声调不同（第一声与第二声），意思是不流行。"}, {"text": "不明", "is_correct": false, "explanation": "m 与 x 声母不同，声调相同（第二声），意思是不清楚。"}], "explanations": {"不醒": "xǐng 与 xíng 声调不同（第三声与第二声），意思是没有醒来。", "不行": "正确。bù xíng，意思是不可以、不能、不好。", "不兴": "xīng 与 xíng 声调不同（第一声与第二声），意思是不流行。", "不明": "m 与 x 声母不同，声调相同（第二声），意思是不清楚。"}, "sentence_index": null, "correct_answer": "不行"}, "level_3": {"options": [{"text": "不热", "is_correct": false, "explanation": "语义：「热」说温度，不能用来评价汉语水平，句子不通。"}, {"text": "不行", "is_correct": true, "explanation": "正确。「他的汉语还不行」表示水平差，与“要多练习”相合。"}, {"text": "不甜", "is_correct": false, "explanation": "搭配：「甜」用于味道，不用来形容语言能力。"}, {"text": "不咸", "is_correct": false, "explanation": "语义：「咸」说味道，与汉语水平无关，句子不通。"}], "explanations": {"不热": "语义：「热」说温度，不能用来评价汉语水平，句子不通。", "不行": "正确。「他的汉语还不行」表示水平差，与“要多练习”相合。", "不甜": "搭配：「甜」用于味道，不用来形容语言能力。", "不咸": "语义：「咸」说味道，与汉语水平无关，句子不通。"}, "sentence_index": 6, "correct_answer": "不行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的质量很不行，我穿了好几年都没坏。", "explanation": "“不行”表示质量差，与“穿了好几年都没坏”矛盾，此处应用〈结实〉。"}, {"text": "这家餐厅的菜很不行，所以我们每个月都去吃两次。", "explanation": "“不行”表示不好，与“每个月都去”的理由相矛盾，这里应用〈好〉。"}, {"text": "我妹妹不行，比我高半个头。", "explanation": "“不行”只用于能力、质量或可否，不用于比较身高，这里应描述身高，用〈高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个主意不不行，我们换一个。", "corrected_sentence": "这个主意不行，我们换一个。", "error_description": "“不行”前面多加了一个“不”，变成双重否定“不不行”，不是自然的说法。正确形式是“不行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台打印机不行行了，我们换一台吧。", "corrected_sentence": "这台打印机不行了，我们换一台吧。", "error_description": "“不行”后多写了一个“行”，成了“不行行了”，重复的“行”使句子不成词。正确形式是“不行了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
