INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中央是正中间的地方。", "primary_collocate": null, "pronunciation": "zhōng yāng", "ipa": "ʈʂʊŋ˥ jɑŋ˥", "syllable_count": 2, "sentences": [{"text": "广场中央有一个大喷泉。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子中央放着一盆花。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖中央有一个小岛。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在房间的中央。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把椅子放在教室中央。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台中央坐着一位老人。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的中央种着很多树。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市中央有一个大公园。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围着中央的火堆唱歌。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕中央有一颗红色的草莓。", "target_word": "中央", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "正中间的位置，常放在地点名词后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86541, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中央", "is_correct": true, "explanation": "中央（zhōng yāng）：正中间的地方"}, {"text": "中庸", "is_correct": false, "explanation": "yōng 与 yāng 的韵母不同（ong 与 ang），中庸指不偏不倚、适中"}, {"text": "种羊", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng、yáng（第二声）与 yāng 声调都不同，种羊指用于繁殖的羊"}, {"text": "种秧", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng 声调不同，种秧指播种秧苗"}], "explanations": {"中央": "中央（zhōng yāng）：正中间的地方", "中庸": "yōng 与 yāng 的韵母不同（ong 与 ang），中庸指不偏不倚、适中", "种羊": "zhǒng（第三声）与 zhōng、yáng（第二声）与 yāng 声调都不同，种羊指用于繁殖的羊", "种秧": "zhǒng（第三声）与 zhōng 声调不同，种秧指播种秧苗"}, "sentence_index": null, "correct_answer": "中央"}, "level_3": {"options": [{"text": "中央", "is_correct": true, "explanation": "正确：指广场的正中间位置，与“大喷泉”的位置相符"}, {"text": "天上", "is_correct": false, "explanation": "语义：喷泉不能设在天上，句子与常理不符"}, {"text": "海底", "is_correct": false, "explanation": "语义：广场不在海底，大喷泉也不会设在海底"}, {"text": "水中", "is_correct": false, "explanation": "搭配：“广场”是陆地场所，不能与“水中”搭配"}], "explanations": {"中央": "正确：指广场的正中间位置，与“大喷泉”的位置相符", "天上": "语义：喷泉不能设在天上，句子与常理不符", "海底": "语义：广场不在海底，大喷泉也不会设在海底", "水中": "搭配：“广场”是陆地场所，不能与“水中”搭配"}, "sentence_index": 0, "correct_answer": "中央"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上课中央休息了一次。", "explanation": "这里应该用〈中间〉。“中央”只指空间的正中心，不指一段时间的中间"}, {"text": "工程进行到中央。", "explanation": "这里应该用〈中期〉。“中央”不能表示事情进行的阶段"}, {"text": "他的成绩属于中央水平。", "explanation": "这里应该用〈中等〉。“中央”不表示等级或水平的居中"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86541, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "中央", "is_correct": true, "explanation": "中央（zhōng yāng）：正中间的地方"}, {"text": "中英", "is_correct": false, "explanation": "yīng（第一声）与 yāng 韵母不同（ing 与 ang），中英指中国与英国，或中文与英文"}, {"text": "种养", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng 声调不同，yǎng（第三声）与 yāng 声调不同，种养指种植和养殖"}, {"text": "种秧", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng 声调不同，种秧指播种秧苗"}], "explanations": {"中央": "中央（zhōng yāng）：正中间的地方", "中英": "yīng（第一声）与 yāng 韵母不同（ing 与 ang），中英指中国与英国，或中文与英文", "种养": "zhǒng（第三声）与 zhōng 声调不同，yǎng（第三声）与 yāng 声调不同，种养指种植和养殖", "种秧": "zhǒng（第三声）与 zhōng 声调不同，种秧指播种秧苗"}, "sentence_index": null, "correct_answer": "中央"}, "level_3": {"options": [{"text": "中央", "is_correct": true, "explanation": "正确：指路的正中间，与“种着很多树”相符"}, {"text": "天空", "is_correct": false, "explanation": "语义：树不能种在天空中"}, {"text": "空气", "is_correct": false, "explanation": "语义：树不能种在空气里"}, {"text": "海里", "is_correct": false, "explanation": "搭配：“种”的处所应为陆地，“海里”与“这条路”不搭配"}], "explanations": {"中央": "正确：指路的正中间，与“种着很多树”相符", "天空": "语义：树不能种在天空中", "空气": "语义：树不能种在空气里", "海里": "搭配：“种”的处所应为陆地，“海里”与“这条路”不搭配"}, "sentence_index": 6, "correct_answer": "中央"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们小组的中央是小明，大家都听他的。", "explanation": "这里应该用〈领头人〉。“中央”表示空间的正中，不指一组人中的领导者"}, {"text": "这个计划的中央是钱，不是梦想。", "explanation": "这里应该用〈核心〉。“中央”只指空间位置，不指事物的关键部分"}, {"text": "他已经是中央年龄的人了。", "explanation": "这里应该用〈中年〉。“中央”不表示年龄段，指年龄段应说“中年”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她站在舞台上中央，唱了一首歌。", "corrected_sentence": "她站在舞台的中央，唱了一首歌。", "error_description": "位置错误：“中央”本身已表示方位，前面不能再加“上”，应说“站在舞台的中央”，不能说“站在舞台上中央”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把书放在桌子上中央。", "corrected_sentence": "他把书放在桌子中央。", "error_description": "位置错误：“中央”本身已表示方位，前面不能再加“上”，应说“放在桌子中央”，不能说“放在桌子上中央”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
