INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86543, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中间是两边离得一样远的地方。", "primary_collocate": null, "pronunciation": "zhōng jiān", "ipa": "ʈʂʊŋ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "学校在我家和公园中间。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐在爸爸和妈妈中间。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两张桌子中间放着一盆花。", "target_word": "中间", "complexity_tier": "T3", "furigana": "liǎng zhāng zhuōzi zhōngjiān fàngzhe yì pén huā", "sentence_source": "generated"}, {"text": "他站在两个朋友中间。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市中间有一个小火车站。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路中间画着一条白线。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两根柱子中间拉着一根绳子。", "target_word": "中间", "complexity_tier": "T3", "furigana": "liǎng gēn zhùzi zhōngjiān lāzhe yì gēn shéngzi", "sentence_source": "generated"}, {"text": "河中间有一座小岛。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在两个车站中间，走路都要十分钟。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场中间有一条线。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中间儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "中间：两个人、两个地方之间正好居中、与两边距离相等的位置。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中间", "is_correct": true, "explanation": "正确：中间指两者距离相等的位置，“学校在我家和公园中间”符合句意。"}, {"text": "里面", "is_correct": false, "explanation": "语义：“里面”指范围之内，与“在两地的中间位置”的意思不符。"}, {"text": "底下", "is_correct": false, "explanation": "语义：“底下”指位置在下方，学校不能在我家和公园的下方。"}, {"text": "上面", "is_correct": false, "explanation": "语义：“上面”指位置在上方，学校不能在我家和公园的上方。"}], "explanations": {"中间": "正确：中间指两者距离相等的位置，“学校在我家和公园中间”符合句意。", "里面": "语义：“里面”指范围之内，与“在两地的中间位置”的意思不符。", "底下": "语义：“底下”指位置在下方，学校不能在我家和公园的下方。", "上面": "语义：“上面”指位置在上方，学校不能在我家和公园的上方。"}, "sentence_index": 0, "correct_answer": "中间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坐在我中间看书。", "explanation": "这里应该用〈旁边〉。中间指两侧距离相等的位置，只有一个人时不能说“坐在我中间”，应说“坐在我旁边”。"}, {"text": "我站在他中间拍照。", "explanation": "这里应该用〈后面〉。中间要求两侧有对称的参照，站在一个人的中间不能表示站位，应说“站在他后面”。"}, {"text": "他站在一个朋友中间。", "explanation": "这里应该用〈身边〉。中间需要两侧的参照，只有一个朋友时不能说“中间”，应说“站在朋友身边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中间", "is_correct": true, "explanation": "正确：“两根柱子中间拉着一根绳子”指两柱之间的位置，符合句意。"}, {"text": "门口", "is_correct": false, "explanation": "搭配：“门口”需要明确的门，“两根柱子门口”搭配不通。"}, {"text": "山顶", "is_correct": false, "explanation": "语义：“山顶”指山的最高处，与两根柱子之间拉绳子的情境不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的房间，柱子之间不可能在厨房里拉绳子。"}], "explanations": {"中间": "正确：“两根柱子中间拉着一根绳子”指两柱之间的位置，符合句意。", "门口": "搭配：“门口”需要明确的门，“两根柱子门口”搭配不通。", "山顶": "语义：“山顶”指山的最高处，与两根柱子之间拉绳子的情境不符。", "厨房": "语义：“厨房”是做饭的房间，柱子之间不可能在厨房里拉绳子。"}, "sentence_index": 6, "correct_answer": "中间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的中间思想很清楚。", "explanation": "这里应该用〈中心〉。“中心思想”是固定搭配，“中间思想”不这么说。"}, {"text": "他的中间很高。", "explanation": "这里应该用〈身高〉。中间是位置词，不能用来说人的身高。"}, {"text": "他的中间很快乐。", "explanation": "这里应该用〈开心〉。中间是位置词，不能用来形容心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河从两座山中间的流过。", "corrected_sentence": "这条河从两座山中间流过。", "error_description": "错误：“中间”后多出了“的”，“中间的流过”缺少中心语，句子不成立。正确：去掉“的”，写作“这条河从两座山中间流过。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖在中间有一个小亭子。", "corrected_sentence": "湖中间有一个小亭子。", "error_description": "错误：“在”后面缺少地点名词，“湖在中间”不成句。正确：去掉“在”，写作“湖中间有一个小亭子”，“湖中间”表示地点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
