INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两端之间的位置；中心。", "primary_collocate": null, "pronunciation": "zhōng jiān", "ipa": "ʈʂʊŋ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "房间中间有一张大桌子。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书中间有几页画儿。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队伍中间有一个穿红衣服的孩子。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在人群中间，大声唱歌。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影中间有一段很好笑。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间那个杯子是我的。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人中间，他最高。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夹在两片面包中间的是鸡蛋。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕中间有一颗红草莓。", "target_word": "中间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台中间站着一个歌手。", "target_word": "中间", "complexity_tier": "T3", "furigana": "wǔtái zhōngjiān zhànzhe yí ge gēshǒu", "sentence_source": "generated"}], "morphological_forms": [{"form": "中间儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "中间：事物或过程两端之间的部分，或中心的位置。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中间", "is_correct": true, "explanation": "正确：“中间”指一个事物内部的中心位置，“房间中间有一张大桌子”符合句意。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：“天花板”是房顶，房间的天花板上不会摆放一张大桌子。"}, {"text": "上空", "is_correct": false, "explanation": "语义：“上空”指天空中的高处，房间上空不会摆着一张大桌子。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是一个房间名称，不是方位词，“房间厨房有一张大桌子”不成立。"}], "explanations": {"中间": "正确：“中间”指一个事物内部的中心位置，“房间中间有一张大桌子”符合句意。", "天花板": "语义：“天花板”是房顶，房间的天花板上不会摆放一张大桌子。", "上空": "语义：“上空”指天空中的高处，房间上空不会摆着一张大桌子。", "厨房": "搭配：“厨房”是一个房间名称，不是方位词，“房间厨房有一张大桌子”不成立。"}, "sentence_index": 0, "correct_answer": "中间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我站在他中间等车。", "explanation": "这里应该用〈旁边〉。中间需要两侧的参照，只有一个人时不能说“站在他中间”，应说“站在他旁边”。"}, {"text": "他站在我中间，帮我拿东西。", "explanation": "这里应该用〈后面〉。中间要求两侧有对称的参照，站在一个人的中间不能表示站位，应说“站在我后面”。"}, {"text": "他的中间很高。", "explanation": "这里应该用〈身高〉。中间是位置词，不能用来说人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中间", "is_correct": true, "explanation": "正确：“中间”表示在三人之中，“三个人中间，他最高”符合句意。"}, {"text": "旁边", "is_correct": false, "explanation": "语义：“旁边”指靠近某物的一侧，不能用来在三人之中比较高矮。"}, {"text": "外面", "is_correct": false, "explanation": "搭配：“外面”表示范围之外，不能说“三个人外面，他最高”。"}, {"text": "下面", "is_correct": false, "explanation": "语义：“下面”表示位置在下，与比较高矮的意思不相干。"}], "explanations": {"中间": "正确：“中间”表示在三人之中，“三个人中间，他最高”符合句意。", "旁边": "语义：“旁边”指靠近某物的一侧，不能用来在三人之中比较高矮。", "外面": "搭配：“外面”表示范围之外，不能说“三个人外面，他最高”。", "下面": "语义：“下面”表示位置在下，与比较高矮的意思不相干。"}, "sentence_index": 6, "correct_answer": "中间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文的中间论点很明确。", "explanation": "这里应该用〈中心〉。“中心论点”是固定搭配，“中间论点”不这么说。"}, {"text": "他的心情很中间。", "explanation": "这里应该用〈平静〉。中间是位置词，不能直接作形容词描述心情，应说“心情很平静”。"}, {"text": "他的中间很安静。", "explanation": "这里应该用〈性格〉。中间是位置词，不能指人的性格，应说“他的性格很安静”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市在中间有一条大河。", "corrected_sentence": "这座城市中间有一条大河。", "error_description": "错误：“在”后面缺少地点名词，“这座城市在中间”不成句。正确：去掉“在”，写作“这座城市中间有一条大河”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个杯子放在桌子中间的。", "corrected_sentence": "这个杯子放在桌子中间。", "error_description": "错误：句末多出了“的”，“这个杯子放在桌子中间的”不成句。正确：去掉“的”，写作“这个杯子放在桌子中间。”，“中间”作方位词，表示位于桌子两端之间的位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
