INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "局是下棋或比赛的一场。", "primary_collocate": null, "pronunciation": "jú", "ipa": "tɕy˧˥", "syllable_count": 1, "sentences": [{"text": "我和爷爷下了一局棋。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛一共打三局。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一局就赢了对手。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们再来一局，好不好？", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛分五局，谁先赢三局谁就是冠军。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这局棋下了两个小时。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我连输了两局。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一局，他打得特别好。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想和我再下一局象棋。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一局棋还没下完，天就黑了。", "target_word": "局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "量词：下棋或比赛的一场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd727e10f-1248-4124-9d4c-8b97d0ca17dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "局", "is_correct": true, "explanation": "局 jú（第二声）：下棋或比赛的一场。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jú（第二声）声调不同，意思是居住。"}, {"text": "举", "is_correct": false, "explanation": "jǔ（第三声）与 jú（第二声）声调不同，意思是抬起。"}, {"text": "句", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是句子。"}, {"text": "巨", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是巨大。"}], "explanations": {"局": "局 jú（第二声）：下棋或比赛的一场。", "居": "jū（第一声）与 jú（第二声）声调不同，意思是居住。", "举": "jǔ（第三声）与 jú（第二声）声调不同，意思是抬起。", "句": "jù（第四声）与 jú（第二声）声调不同，意思是句子。", "巨": "jù（第四声）与 jú（第二声）声调不同，意思是巨大。"}, "sentence_index": null, "correct_answer": "局"}, "level_3": {"options": [{"text": "局", "is_correct": true, "explanation": "局：量词，计算下棋的一个回合，“一局棋”指一次完整的对局。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”用于衣服、事情等，不能用来计算一次下棋。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、桌子等平面的东西，不能说“一张棋”。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗歌、歌曲，与下棋无关。"}], "explanations": {"局": "局：量词，计算下棋的一个回合，“一局棋”指一次完整的对局。", "件": "搭配：“件”用于衣服、事情等，不能用来计算一次下棋。", "张": "搭配：“张”用于纸、桌子等平面的东西，不能说“一张棋”。", "首": "语义：“首”用于诗歌、歌曲，与下棋无关。"}, "sentence_index": 0, "correct_answer": "局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天看了一局电影。", "explanation": "这里应该用〈场〉。局只用于下棋、比赛中的一个回合，看电影要用场。"}, {"text": "我昨天买了一局书。", "explanation": "这里应该用〈本〉。局是计算棋局或比赛回合的量词，书要用本来计算。"}, {"text": "我昨天听了一局歌。", "explanation": "这里应该用〈首〉。局是计算棋局或比赛回合的量词，歌要用首来计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "局", "is_correct": true, "explanation": "局 jú（第二声）：下棋或比赛的一场。"}, {"text": "剧", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是戏剧。"}, {"text": "聚", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是聚集。"}, {"text": "具", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是工具。"}, {"text": "拒", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是拒绝。"}, {"text": "据", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是根据。"}], "explanations": {"局": "局 jú（第二声）：下棋或比赛的一场。", "剧": "jù（第四声）与 jú（第二声）声调不同，意思是戏剧。", "聚": "jù（第四声）与 jú（第二声）声调不同，意思是聚集。", "具": "jù（第四声）与 jú（第二声）声调不同，意思是工具。", "拒": "jù（第四声）与 jú（第二声）声调不同，意思是拒绝。", "据": "jù（第四声）与 jú（第二声）声调不同，意思是根据。"}, "sentence_index": null, "correct_answer": "局"}, "level_3": {"options": [{"text": "局", "is_correct": true, "explanation": "局：量词，计算比赛中的一个回合，“两局”指两个回合。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于字画、布匹，与比赛的输赢无关。"}, {"text": "份", "is_correct": false, "explanation": "搭配：“份”多用于饭菜、报纸，不能计算比赛的输赢。"}, {"text": "副", "is_correct": false, "explanation": "搭配：“副”用于成对或成套的东西，如眼镜、手套，不能用于输赢。"}], "explanations": {"局": "局：量词，计算比赛中的一个回合，“两局”指两个回合。", "幅": "语义：“幅”用于字画、布匹，与比赛的输赢无关。", "份": "搭配：“份”多用于饭菜、报纸，不能计算比赛的输赢。", "副": "搭配：“副”用于成对或成套的东西，如眼镜、手套，不能用于输赢。"}, "sentence_index": 6, "correct_answer": "局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他早上喝了一局牛奶。", "explanation": "这里应该用〈杯〉。局只用于下棋或比赛的一场，牛奶要用杯。"}, {"text": "我家养了一局小狗。", "explanation": "这里应该用〈只〉。局只用于下棋或比赛的一场，小狗要用只。"}, {"text": "她穿了一局新衣服。", "explanation": "这里应该用〈件〉。局只用于下棋或比赛的一场，衣服要用件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天喝了一局茶。", "corrected_sentence": "我们昨天喝了一杯茶。", "error_description": "量词错误：「局」只用于下棋或比赛中的一个回合，计量茶要用「杯」。应说「喝了一杯茶」，这里误用「局」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他和我下了一个局棋。", "corrected_sentence": "他和我下了一局棋。", "error_description": "量词错误：“局”本身就是量词，前面不能再加“个”。正确说法是“下了一局棋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以后", "is_correct": true, "explanation": "正确。“以前”指过去，“以后”指将来，两者是时间上的反义词。"}, {"text": "白天", "is_correct": false, "explanation": "与“以前”没有反义关系，“白天”指白昼的时段。"}, {"text": "今天", "is_correct": false, "explanation": "与“以前”没有反义关系，“今天”指当天。"}, {"text": "春天", "is_correct": false, "explanation": "与“以前”没有反义关系，“春天”指一年中的季节。"}], "correct_answer": "以后", "explanations": {"以后": "正确。“以前”指过去，“以后”指将来，两者是时间上的反义词。", "白天": "与“以前”没有反义关系，“白天”指白昼的时段。", "今天": "与“以前”没有反义关系，“今天”指当天。", "春天": "与“以前”没有反义关系，“春天”指一年中的季节。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以后", "is_correct": true, "explanation": "正确。“以前”指过去，“以后”指将来，两者是时间上的反义词。"}, {"text": "上午", "is_correct": false, "explanation": "与“以前”没有反义关系，“上午”指中午以前的时段。"}, {"text": "夏天", "is_correct": false, "explanation": "与“以前”没有反义关系，“夏天”指一年中的季节。"}, {"text": "下午", "is_correct": false, "explanation": "与“以前”没有反义关系，“下午”指中午以后的时段。"}], "correct_answer": "以后", "explanations": {"以后": "正确。“以前”指过去，“以后”指将来，两者是时间上的反义词。", "上午": "与“以前”没有反义关系，“上午”指中午以前的时段。", "夏天": "与“以前”没有反义关系，“夏天”指一年中的季节。", "下午": "与“以前”没有反义关系，“下午”指中午以后的时段。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以前是现在过去了的时候。", "primary_collocate": null, "pronunciation": "yǐ qián", "ipa": "i˨˩ t͡ɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "以前我家很小，现在大了。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前是我的同学。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里以前没有地铁。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前我不喜欢喝茶。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以前去过那个公园吗？", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的事，我都忘了。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶以前常给我讲故事。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以前不会游泳，现在会了。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前这条路很窄。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们以前见过面，你还记得吗？", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "单用，指现在以前的过去时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a68a0c0-0cc4-46cf-be05-5ccf26b00493') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以后", "is_correct": false, "explanation": "语义：「以后」指将来，与“现在大了”的对比相冲突，句意不通。"}, {"text": "以前", "is_correct": true, "explanation": "正确。「以前」指过去的时期，与“现在大了”形成对比。"}, {"text": "明天", "is_correct": false, "explanation": "语义：「明天」指次日，不能与“现在大了”构成过去的对比。"}, {"text": "未来", "is_correct": false, "explanation": "语义：「未来」指将来，而句子说的是过去的家，与“现在大了”的对比不符。"}], "explanations": {"以后": "语义：「以后」指将来，与“现在大了”的对比相冲突，句意不通。", "以前": "正确。「以前」指过去的时期，与“现在大了”形成对比。", "明天": "语义：「明天」指次日，不能与“现在大了”构成过去的对比。", "未来": "语义：「未来」指将来，而句子说的是过去的家，与“现在大了”的对比不符。"}, "sentence_index": 0, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我以前明年要去北京。", "explanation": "这里应该用〈以后〉。「以前」指过去，与表示将来的“明年”矛盾。"}, {"text": "我以前后天要去北京。", "explanation": "“以前”只指过去，不能与“后天”这样的将来时间搭配，此处应去掉“以前”。"}, {"text": "我们以前明天见面吧。", "explanation": "“以前”指过去，与“明天见面”的将来时间矛盾，此处应去掉“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "语义：「昨天」指一天，不能与表示经常的“常”搭配，句意不通。"}, {"text": "以前", "is_correct": true, "explanation": "正确。「奶奶以前常给我讲故事」指过去的一段时期，与“常”相合。"}, {"text": "今天", "is_correct": false, "explanation": "语义：「今天」指当天，不能与“常”构成经常发生的时间，句意不通。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：「刚才」指刚过去的时点，不与表示经常的“常”搭配。"}], "explanations": {"昨天": "语义：「昨天」指一天，不能与表示经常的“常”搭配，句意不通。", "以前": "正确。「奶奶以前常给我讲故事」指过去的一段时期，与“常”相合。", "今天": "语义：「今天」指当天，不能与“常”构成经常发生的时间，句意不通。", "刚才": "搭配：「刚才」指刚过去的时点，不与表示经常的“常”搭配。"}, "sentence_index": 6, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们将来以前见过面，你还记得吗？", "explanation": "“以前”指过去，与“将来”矛盾，此处应去掉“将来”。"}, {"text": "我们以前马上就要见面，你还记得吗？", "explanation": "“以前”指过去，与“马上就要”的近将来矛盾，此处应去掉“以前”。"}, {"text": "我们以前后天要见面，你还记得吗？", "explanation": "“以前”指过去，与“后天要”的将来时间矛盾，此处应去掉“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前的学过法语。", "corrected_sentence": "我以前学过法语。", "error_description": "“以前”后面多加了“的”，变成“以前的学过法语”，不通。“以前”在句中作时间状语，直接放在动词前，应说“我以前学过法语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前了住在北京。", "corrected_sentence": "我们以前住在北京。", "error_description": "“了”不能放在“以前”和动词之间。错误形式“以前了住”不通，正确形式为“以前住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
