INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指现在或某一时间之前的时期。", "primary_collocate": null, "pronunciation": "yǐ qián", "ipa": "i˨˩ t͡ɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "十点以前，请你回家。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国以前，我学过一年汉语。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三年以前，他还在北京工作。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭以前，要先洗手。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，我每天都复习。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五年以前，这里是一片田地。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以前，老师不让我们走。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，他喜欢听音乐。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期五以前，请把作业交给我。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年以前，我们住在同一个城市。", "target_word": "以前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "接在时间或动作后面，指某一时间之前的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a68a0c0-0cc4-46cf-be05-5ccf26b00493') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以外", "is_correct": false, "explanation": "语义：「以外」表示范围之外，不指时间的先后，“十点以外”句意不通。"}, {"text": "以前", "is_correct": true, "explanation": "正确。「十点以前」指十点之前的时期，与“请你回家”相合。"}, {"text": "以下", "is_correct": false, "explanation": "语义：「以下」多指数量或等级，不用于时间点，“十点以下”句意不通。"}, {"text": "以南", "is_correct": false, "explanation": "搭配：「以南」是方位词，不接在时间后面，“十点以南”不通。"}], "explanations": {"以外": "语义：「以外」表示范围之外，不指时间的先后，“十点以外”句意不通。", "以前": "正确。「十点以前」指十点之前的时期，与“请你回家”相合。", "以下": "语义：「以下」多指数量或等级，不用于时间点，“十点以下”句意不通。", "以南": "搭配：「以南」是方位词，不接在时间后面，“十点以南”不通。"}, "sentence_index": 0, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试以前，我已经考完了。", "explanation": "这里应用〈以后〉。“考试以前”指考试之前，“已经考完了”说明考试已经结束，时间矛盾。"}, {"text": "吃饭以前，我们已经吃饱了，就去洗碗吧。", "explanation": "这里应用〈以后〉。“吃饭以前”指还没吃饭，与“已经吃饱了”矛盾。"}, {"text": "这个会议以前，他已经讲完了。", "explanation": "这里应用〈以后〉。“以前”指某一时间之前，“已经讲完了”与会议之前的时间矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以北", "is_correct": false, "explanation": "语义：「以北」是方位，不指时间的先后，“下课以北”句意不通。"}, {"text": "以东", "is_correct": false, "explanation": "搭配：「以东」是方位词，不接在动作后面表示时间，“下课以东”不通。"}, {"text": "以前", "is_correct": true, "explanation": "正确。「下课以前」指下课之前的时期，与“老师不让我们走”相合。"}, {"text": "以西", "is_correct": false, "explanation": "语义：「以西」是方位，不指时间的先后，“下课以西”句意不通。"}], "explanations": {"以北": "语义：「以北」是方位，不指时间的先后，“下课以北”句意不通。", "以东": "搭配：「以东」是方位词，不接在动作后面表示时间，“下课以东”不通。", "以前": "正确。「下课以前」指下课之前的时期，与“老师不让我们走”相合。", "以西": "语义：「以西」是方位，不指时间的先后，“下课以西”句意不通。"}, "sentence_index": 6, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十年以前，我们会在同一个城市见面。", "explanation": "“以前”指过去，与“会”表示的将来矛盾，时间不一致。"}, {"text": "十年以前，我们将住在同一个城市。", "explanation": "“以前”指某时之前的过去，与“将”表示的将来矛盾，此处应用〈以后〉。"}, {"text": "十年以前，我们将来住在同一个城市。", "explanation": "“以前”指过去，与“将来”矛盾，此处应去掉“将来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上课的以前，他要先准备。", "corrected_sentence": "上课以前，他要先准备。", "error_description": "“以前”前面不能直接用“的”接动词短语，“上课的以前”不通，应说“上课以前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个小时的以前，他离开了。", "corrected_sentence": "两个小时以前，他离开了。", "error_description": "“以前”前面不能直接用“的”接数量词短语，“两个小时的以前”不通，应说“两个小时以前”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
