INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86551, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做到是把事情做好，真的完成了。", "primary_collocate": null, "pronunciation": "zuò dào", "ipa": "tsuɔ˥˩ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这次比赛很难，但我们终于做到了。", "target_word": "做到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很难，但他做到了。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你答应我的事，做到了吗？", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天跑步一小时，我做到了。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说得容易，做到很难。", "target_word": "做到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师要我们每天写字，我都做到了。", "target_word": "做到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说三天完成，真的做到了。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要做到准时，就要早点出门。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想学好中文，一定要做到每天说。", "target_word": "做到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做到了每天早起。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做到了", "label": "体标"}], "register": "通用", "sense_fingerprint": "做到：动词，把事情真正做好、完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86551, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“终于……了”表示达成目标的语义不符，句意不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是负面结果，与“终于”表示达成目标的语境相反，句意不通。"}, {"text": "做到", "is_correct": true, "explanation": "正确。表示克服困难后真的完成了目标，与“但”形成转折，符合句意。"}, {"text": "开车", "is_correct": false, "explanation": "语义：“开车”与比赛语境无关，句意不通。"}], "explanations": {"忘记": "语义：“忘记”与“终于……了”表示达成目标的语义不符，句意不通。", "迟到": "语义：“迟到”是负面结果，与“终于”表示达成目标的语境相反，句意不通。", "做到": "正确。表示克服困难后真的完成了目标，与“但”形成转折，符合句意。", "开车": "语义：“开车”与比赛语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "做到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于做到了作业。", "explanation": "这里应该用〈完成〉。做到用于做成所要求或所说的事，具体的作业要说“完成”。"}, {"text": "他做到了一首歌。", "explanation": "这里应该用〈创作〉。做到用于实现所要求或所说的事，写歌要说“创作”。"}, {"text": "他做到了房间。", "explanation": "这里应该用〈打扫〉。做到用于完成所要求的事，打扫房间要用“打扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”与“完成”没有搭配关系，“真的吃了”与“说三天完成”不协调。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“说三天完成”的语境不相干，句意不通。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”与“说三天完成”的承诺语境矛盾，句意不通。"}, {"text": "做到", "is_correct": true, "explanation": "正确。表示真的完成了所说的事，符合“说三天完成”的语境。"}], "explanations": {"吃": "搭配：“吃”与“完成”没有搭配关系，“真的吃了”与“说三天完成”不协调。", "哭": "语义：“哭”与“说三天完成”的语境不相干，句意不通。", "忘": "语义：“忘”与“说三天完成”的承诺语境矛盾，句意不通。", "做到": "正确。表示真的完成了所说的事，符合“说三天完成”的语境。"}, "sentence_index": 6, "correct_answer": "做到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做到了一张桌子。", "explanation": "这里应该用〈做成〉。做到用于实现所要求或所说的事，制成具体物品要说“做成”。"}, {"text": "她做到了一顿早饭。", "explanation": "这里应该用〈做〉。做到用于实现所要求或所说的事，做早饭这类具体动作要说“做”。"}, {"text": "他做到了奖学金。", "explanation": "这里应该用〈拿到〉。做到不能与奖学金这类结果搭配，获得奖学金要用“拿到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于做到着每天早起。", "corrected_sentence": "她终于做到了每天早起。", "error_description": "错误：“做到”表示已经完成，句中应用完成体“了”，不能用表示持续的“着”。正确应为“她终于做到了每天早起。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我答应你的事，明天一定做到了。", "corrected_sentence": "我答应你的事，明天一定做到。", "error_description": "错误：“明天一定做到”说的是还没发生的事，不能加表示完成的“了”。正确应为“我答应你的事，明天一定做到。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
