INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "实现；完成（所要求或所说的事）。", "primary_collocate": null, "pronunciation": "zuò dào", "ipa": "tsuɔ˥˩ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老板要我今天交报告，我做到了。", "target_word": "做到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说会来，果然做到了。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要做到这一点，并不容易。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说一周学会游泳，现在做到了。", "target_word": "做到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要求准时上班，大家都做到了。", "target_word": "做到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说要戒烟，现在做到了吗？", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做到按时睡觉，对身体很好。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈让我少玩手机，我终于做到了。", "target_word": "做到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想做到这么好，需要很多练习。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她答应帮忙，也做到了。", "target_word": "做到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做到了", "label": "体标"}], "register": "通用", "sense_fingerprint": "做到：动词，实现、完成所要求或所说的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘", "is_correct": false, "explanation": "语义：“忘”与“老板要我今天交报告”这一要求相悖，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”与“交报告”没有搭配关系，“我吃了”无法接续上文的要求。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与前文要求今天交报告的语境不符，句意不通。"}, {"text": "做到", "is_correct": true, "explanation": "正确。表示实现了老板所要求的事，符合句意。"}], "explanations": {"忘": "语义：“忘”与“老板要我今天交报告”这一要求相悖，句意不通。", "吃": "搭配：“吃”与“交报告”没有搭配关系，“我吃了”无法接续上文的要求。", "睡": "语义：“睡”与前文要求今天交报告的语境不符，句意不通。", "做到": "正确。表示实现了老板所要求的事，符合句意。"}, "sentence_index": 0, "correct_answer": "做到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做到了一把椅子。", "explanation": "这里应该用〈做成〉。做到用于实现所要求或所说的事，制成具体物品要说“做成”。"}, {"text": "他做到了一道菜。", "explanation": "这里应该用〈做好〉。做到用于实现所要求或所说的事，做菜这类具体动作要说“做好”。"}, {"text": "他做到了一条路。", "explanation": "这里应该用〈修〉。做到用于实现所要求或所说的事，修路这类具体工程要说“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记按时睡觉”与“对身体很好”的评价不协调，句意不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝按时睡觉”与“对身体很好”的评价相矛盾，句意不通。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能与“按时睡觉”搭配，句子不通。"}, {"text": "做到", "is_correct": true, "explanation": "正确。表示能够实现按时睡觉这件事，符合句意。"}], "explanations": {"忘记": "语义：“忘记按时睡觉”与“对身体很好”的评价不协调，句意不通。", "拒绝": "语义：“拒绝按时睡觉”与“对身体很好”的评价相矛盾，句意不通。", "哭": "搭配：“哭”不能与“按时睡觉”搭配，句子不通。", "做到": "正确。表示能够实现按时睡觉这件事，符合句意。"}, "sentence_index": 6, "correct_answer": "做到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做到了一份好工作。", "explanation": "这里应该用〈找到〉。做到用于实现所说的事，获得工作要说“找到”。"}, {"text": "他做到了一碗面。", "explanation": "这里应该用〈煮〉。做到用于实现所要求或所说的事，煮面这类具体动作要说“煮”。"}, {"text": "这个方法做到了作用。", "explanation": "这里应该用〈起到〉。做到用于实现所说的事，“起到作用”是固定搭配，不能用做到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他坚持两个月，终于做到了了。", "corrected_sentence": "他坚持两个月，终于做到了。", "error_description": "错误：“做到了”后又多加了一个“了”，句中“了”重复。正确应只保留一个，即“他坚持两个月，终于做到了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他答应的事，最后也没做到了。", "corrected_sentence": "他答应的事，最后也没做到。", "error_description": "错误：“没”否定已发生的事时，句末不能再加“了”。正确应为“他答应的事，最后也没做到。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
