INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86553, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "先生是对男人的客气叫法，也是老师的叫法。", "primary_collocate": null, "pronunciation": "xiān sheng", "ipa": "ɕi̯ɛn˥ ʂɤŋ", "syllable_count": 2, "sentences": [{"text": "服务员说：“先生，请这边坐。”", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位先生，您的包忘在车上了。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生是我们公司的新经理。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生，您要茶还是咖啡？", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "私塾里的先生每天教我们写字。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位先生正在大门口等人。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，先生贵姓？", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李先生今天不在，请明天再来。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位很有礼貌的先生。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位先生教了我们三年语文。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位先生", "label": "量词"}, {"form": "先生们", "label": "复数"}, {"form": "老先生", "label": "复合"}], "register": "中性", "sense_fingerprint": "先生：客气地称呼男人，也指老师", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，服务员不会请桌子“这边坐”。"}, {"text": "先生", "is_correct": true, "explanation": "“先生”是对男子的客气称呼，服务员用来招呼顾客，符合“请这边坐”的语境。"}, {"text": "胖子", "is_correct": false, "explanation": "语域：用“胖子”称呼顾客带有冒犯，不符合服务场合的礼貌用语。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师在后厨工作，不是需要服务员请到座位上的客人。"}], "explanations": {"桌子": "语义：桌子不是人，服务员不会请桌子“这边坐”。", "先生": "“先生”是对男子的客气称呼，服务员用来招呼顾客，符合“请这边坐”的语境。", "胖子": "语域：用“胖子”称呼顾客带有冒犯，不符合服务场合的礼貌用语。", "厨师": "语义：厨师在后厨工作，不是需要服务员请到座位上的客人。"}, "sentence_index": 0, "correct_answer": "先生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是个很温柔的先生，大家都很喜欢她。", "explanation": "这里应该用〈女士〉。先生用于称呼男子，句中的“她”是女性，不能称为先生。"}, {"text": "我们班的先生都很努力学习，成绩很好。", "explanation": "这里应该用〈学生〉。先生指老师或对男子的尊称，努力学习的人是学生。"}, {"text": "我们饭店的先生每天很早就来做菜。", "explanation": "这里应该用〈厨师〉。先生不指做菜的人，做菜的人应称厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：“贵姓”只用于问人，电脑不能有姓氏。"}, {"text": "先生", "is_correct": true, "explanation": "“先生”是对男子的尊称，询问对方姓氏时可以这样称呼。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：动物没有姓氏，不能问“贵姓”。"}, {"text": "孩子", "is_correct": false, "explanation": "语域：“贵姓”是对成年人的敬辞，不用于询问小孩的姓氏。"}], "explanations": {"电脑": "语义：“贵姓”只用于问人，电脑不能有姓氏。", "先生": "“先生”是对男子的尊称，询问对方姓氏时可以这样称呼。", "老虎": "语义：动物没有姓氏，不能问“贵姓”。", "孩子": "语域：“贵姓”是对成年人的敬辞，不用于询问小孩的姓氏。"}, "sentence_index": 6, "correct_answer": "先生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是个漂亮的先生，很爱笑。", "explanation": "这里应该用〈姑娘〉。先生用于称呼男子，句中的“她”是女性，不能称为先生。"}, {"text": "这位先生今年才十岁，正在小学里读书。", "explanation": "这里应该用〈小朋友〉。先生指成年男子或老师，不用于称呼十岁的孩子。"}, {"text": "她是我们小区里最热心的先生。", "explanation": "这里应该用〈阿姨〉。先生指男子，句中的“她”是女性，应称阿姨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只先生是我们的历史老师。", "corrected_sentence": "那位先生是我们的历史老师。", "error_description": "量词错误：先生指人，应该用量词“位”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位先生们在会议室等我们。", "corrected_sentence": "三位先生在会议室等我们。", "error_description": "复数错误：“三位”已经表示数量，不能再加“们”，应说“三位先生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
