INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86554, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86554, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对男子的尊称；也用来称呼老师，或指丈夫（自己的或他人的）。", "primary_collocate": null, "pronunciation": "xiān sheng", "ipa": "ɕi̯ɛn˥ ʂɤŋ", "syllable_count": 2, "sentences": [{"text": "我先生今天加班，晚饭不回家吃。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先生在银行工作。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我先生，他姓张。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲁迅先生写过很多有名的文章。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很尊敬这位先生。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您先生最近身体好吗？", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张先生，欢迎您来我们学校。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学堂里的先生请大家安静。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以后，我去办公室问先生一道题。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位先生帮我们拍了一张照片。", "target_word": "先生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位先生", "label": "量词"}, {"form": "先生们", "label": "复数"}, {"form": "老先生", "label": "复合"}], "register": "中性", "sense_fingerprint": "先生：尊称男子，也称老师或丈夫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙发", "is_correct": false, "explanation": "语义：沙发不是人，不会加班，也不会回家吃饭。"}, {"text": "先生", "is_correct": true, "explanation": "“先生”指丈夫，“我先生”是对自己丈夫的称呼，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人，不能加班，也不会回家吃晚饭。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是人，不能加班，也不吃晚饭。"}], "explanations": {"沙发": "语义：沙发不是人，不会加班，也不会回家吃饭。", "先生": "“先生”指丈夫，“我先生”是对自己丈夫的称呼，符合句意。", "冰箱": "语义：冰箱不是人，不能加班，也不会回家吃晚饭。", "书包": "语义：书包不是人，不能加班，也不吃晚饭。"}, "sentence_index": 0, "correct_answer": "先生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她总是很温柔，大家都说她是个好先生。", "explanation": "这里应该用〈女士〉。先生指男子或丈夫，句中的“她”是女性，不能称为先生。"}, {"text": "我妈妈是医院的先生，每天给病人看病。", "explanation": "这里应该用〈医生〉。句中“妈妈”是女性，不能称为先生；给病人看病的人应称医生。"}, {"text": "她是我们楼上的先生，每天早上去公园跳舞。", "explanation": "这里应该用〈阿姨〉。先生指男子或丈夫，楼上这位是女性，应称阿姨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小子", "is_correct": false, "explanation": "语域：“小子”带有轻慢色彩，与“欢迎您”的敬意不符。"}, {"text": "先生", "is_correct": true, "explanation": "“先生”是对男子的敬称，欢迎来宾时可以这样称呼。"}, {"text": "宝贝", "is_correct": false, "explanation": "语域：“宝贝”是对小孩的亲昵称呼，不用于欢迎来宾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是人，不能被欢迎来学校。"}], "explanations": {"小子": "语域：“小子”带有轻慢色彩，与“欢迎您”的敬意不符。", "先生": "“先生”是对男子的敬称，欢迎来宾时可以这样称呼。", "宝贝": "语域：“宝贝”是对小孩的亲昵称呼，不用于欢迎来宾。", "电脑": "语义：电脑不是人，不能被欢迎来学校。"}, "sentence_index": 6, "correct_answer": "先生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园里有一群先生在玩滑梯。", "explanation": "这里应该用〈孩子〉。先生指成年男子或老师，玩滑梯的是孩子，不能称先生。"}, {"text": "她是个可爱的先生，很爱笑。", "explanation": "这里应该用〈姑娘〉。先生指男子或丈夫，句中的“她”是女性，不能称为先生。"}, {"text": "她是酒店的先生，很热情。", "explanation": "这里应该用〈小姐〉。先生指男子，句中的“她”是女性，不能用先生称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先生们出差去了上海。", "corrected_sentence": "我先生出差去了上海。", "error_description": "复数错误：“先生”指丈夫时，前面有“我”，后面不能再加“们”，应说“我先生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只老先生在公园里下棋。", "corrected_sentence": "一位老先生在公园里下棋。", "error_description": "量词错误：“老先生”指人，应该用量词“位”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示一个一个分开地做。", "primary_collocate": null, "pronunciation": "fēn bié", "ipa": "fən˥ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我和姐姐分别去了两个城市。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师分别问了三个学生。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分别坐飞机和火车来。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们分别给爸爸妈妈打了电话。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们分别走进了考场。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把苹果和梨分别放在两个盘子里。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分别买了红色和蓝色的鞋。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人分别说出了自己的想法。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天分别去看爷爷和奶奶。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试后，老师分别和每个学生谈了话。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，放在动词前，表示各自分开地做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a68a0c0-0cc4-46cf-be05-5ccf26b00493') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分别", "is_correct": true, "explanation": "正确。“分别”表示两人各自分开去不同的城市，与“两个城市”相合。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人单独做，而句子的主语“我和姐姐”是两个人，不能说独自。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与“不”“没”等否定词搭配，不能说“从来去了”。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与表示已完成的“去了”矛盾。"}], "explanations": {"分别": "正确。“分别”表示两人各自分开去不同的城市，与“两个城市”相合。", "独自": "语义：“独自”指一个人单独做，而句子的主语“我和姐姐”是两个人，不能说独自。", "从来": "搭配：“从来”通常与“不”“没”等否定词搭配，不能说“从来去了”。", "正在": "体貌：“正在”表示动作进行中，与表示已完成的“去了”矛盾。"}, "sentence_index": 0, "correct_answer": "分别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他分别去了北京。", "explanation": "这里应该用〈单独〉。“分别”要求两个或以上的对象各自做，只有一个人去一个地方时要说“单独”。"}, {"text": "全班分别站成一排，等老师拍照。", "explanation": "这里应该用〈整体〉。“分别”要求几个对象各自行动，“站成一排”是整体的站法，与“分别”矛盾。"}, {"text": "我们分别一起去了公园。", "explanation": "这里是把“分别”用成了〈共同〉的意思。“分别”表示各自分开去，不能表示大家共同去，所以与“一起”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分别", "is_correct": true, "explanation": "正确。“分别”表示各自分开做，与“红色和蓝色的鞋”两种颜色相合。"}, {"text": "轮流", "is_correct": false, "explanation": "语义：“轮流”需要多人依次做，而句子的主语“他”只有一个人。"}, {"text": "互相", "is_correct": false, "explanation": "语义：“互相”表示彼此对待，需要两方以上，与单一主语“他”不合。"}, {"text": "永远", "is_correct": false, "explanation": "体貌：“永远”表示持续不变，不能与表示已完成的“买了”搭配。"}], "explanations": {"分别": "正确。“分别”表示各自分开做，与“红色和蓝色的鞋”两种颜色相合。", "轮流": "语义：“轮流”需要多人依次做，而句子的主语“他”只有一个人。", "互相": "语义：“互相”表示彼此对待，需要两方以上，与单一主语“他”不合。", "永远": "体貌：“永远”表示持续不变，不能与表示已完成的“买了”搭配。"}, "sentence_index": 6, "correct_answer": "分别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把三本书分别合在一起放进了包里。", "explanation": "这里是把“分别”用成了〈合并〉的意思。“分别”表示各自分开，而“合在一起”是合为一处，两者意思相反。"}, {"text": "考试后，老师分别和全班同学集体谈了话。", "explanation": "这里是把“分别”用成了〈共同〉的意思。“分别”是逐个分开进行，与大家共同进行的做法意思相反。"}, {"text": "考试后，老师分别和班长谈了话。", "explanation": "这里是把“分别”用成了〈只、仅〉的意思。“分别”要求两个或以上的对象各自处理，这里只有班长一人，不能用“分别”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们分别分别去了两家超市。", "corrected_sentence": "我们分别去了两家超市。", "error_description": "“分别”重复使用，变成“分别分别”，不通。“分别”是副词，只用一次，放在动词“去”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位老师分别的批改了作业。", "corrected_sentence": "三位老师分别批改了作业。", "error_description": "“分别”后面多加了“的”。“分别”是副词，后面直接接动词，不能加“的”，应说“分别批改了作业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
