INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86556, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示各自、各个，不是放在一起。", "primary_collocate": null, "pronunciation": "fēn bié", "ipa": "fən˥ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "苹果和香蕉分别多少钱？", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人分别住在北京和上海。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请分别写下你们的名字。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三个问题，我分别回答。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈分别给了我一件礼物。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红队和蓝队分别得了第一名和第二名。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们分别用中文和英文写了信。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人分别拿着一本书。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱分别放在两个包里。", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种水果分别是什么味道？", "target_word": "分别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，表示几个人或事物各自、各个，不合在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a68a0c0-0cc4-46cf-be05-5ccf26b00493') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分别", "is_correct": true, "explanation": "正确。“分别”表示几样东西各自的情况，与“苹果和香蕉”各自的价格相合。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”指本人亲身去做，主语“苹果和香蕉”是事物，不能说亲自。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人单独，与“苹果和香蕉”两样东西不合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词搭配，不能用于询问价格。"}], "explanations": {"分别": "正确。“分别”表示几样东西各自的情况，与“苹果和香蕉”各自的价格相合。", "亲自": "语义：“亲自”指本人亲身去做，主语“苹果和香蕉”是事物，不能说亲自。", "独自": "语义：“独自”指一个人单独，与“苹果和香蕉”两样东西不合。", "从来": "搭配：“从来”通常与否定词搭配，不能用于询问价格。"}, "sentence_index": 0, "correct_answer": "分别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题，我分别回答。", "explanation": "这里应该用〈单独〉。“分别”表示几个事物各自处理，这里只有一个问题，要用“单独”。"}, {"text": "这三篇课文，我们分别齐声朗读。", "explanation": "这里是把“分别”用成了〈共同〉的意思。“分别”表示各自分开进行，而“齐声”表示大家同时出声，两者矛盾。"}, {"text": "这三个问题，我分别一起回答。", "explanation": "这里是把“分别”用成了〈共同〉的意思。“分别”表示各自分开做，不能表示大家共同做，与“一起回答”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分别", "is_correct": true, "explanation": "正确。“分别”表示各自用不同的语言写，与“中文和英文”相合。"}, {"text": "永远", "is_correct": false, "explanation": "体貌：“永远”表示持续不变，不能与表示已完成的“写了”搭配。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与表示已完成的“写了信”矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能修饰“用……写信”这类动作。"}], "explanations": {"分别": "正确。“分别”表示各自用不同的语言写，与“中文和英文”相合。", "永远": "体貌：“永远”表示持续不变，不能与表示已完成的“写了”搭配。", "正在": "体貌：“正在”表示动作进行中，与表示已完成的“写了信”矛盾。", "非常": "搭配：“非常”修饰形容词或心理动词，不能修饰“用……写信”这类动作。"}, "sentence_index": 6, "correct_answer": "分别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两种水果分别在同一时间成熟，我们等了很久。", "explanation": "这里是把“分别”用成了〈同时〉的意思。“分别”表示各自进行，与“在同一时间”所指的同时发生相矛盾。"}, {"text": "这两种水果分别混在一起卖。", "explanation": "这里是把“分别”用成了〈合并〉的意思。“分别”表示各自分开，与合并在一起卖的意思矛盾。"}, {"text": "这种水果分别是什么味道？", "explanation": "这里是把“分别”用成了〈只〉的意思。“分别”要求两个或以上的事物各自处理，这里只有一种水果，应说“这种水果是什么味道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书和笔一共分别多少钱？", "corrected_sentence": "书和笔分别多少钱？", "error_description": "“一共”表示总计，与“分别”表示各自的意思相矛盾。此处应去掉“一共”，正确形式是“书和笔分别多少钱？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两件衣服一起分别是红色和蓝色的。", "corrected_sentence": "这两件衣服分别是红色和蓝色的。", "error_description": "“一起”表示合在一起，与“分别”表示各自的意思相矛盾。此处应去掉“一起”，正确形式是“这两件衣服分别是红色和蓝色的。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
