INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86559, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全部是所有的，一个也不少。", "primary_collocate": null, "pronunciation": "quán bù", "ipa": "tɕʰɥɛn˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我把全部的钱都给了妈妈。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全部同学都来了。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读完了全部的书。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请了全部的朋友来参加生日会。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全部的作业我都做完了。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把全部的灯关上。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全部学生都在教室里。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用全部的时间学中文。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他卖了家里全部的东西。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司全部的人都很忙。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "所有的人或事物，一个也不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全部", "is_correct": true, "explanation": "正确。“全部”表示所有、一个也不少，与后面的“都”呼应。"}, {"text": "部分", "is_correct": false, "explanation": "语义：“部分”指一部分，与后面的“都”所表示的全体相矛盾。"}, {"text": "全身", "is_correct": false, "explanation": "搭配：“全身”指整个身体，不能修饰“钱”。"}, {"text": "半天", "is_correct": false, "explanation": "搭配：“半天”是时间词，不能修饰“钱”。"}], "explanations": {"全部": "正确。“全部”表示所有、一个也不少，与后面的“都”呼应。", "部分": "语义：“部分”指一部分，与后面的“都”所表示的全体相矛盾。", "全身": "搭配：“全身”指整个身体，不能修饰“钱”。", "半天": "搭配：“半天”是时间词，不能修饰“钱”。"}, "sentence_index": 0, "correct_answer": "全部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把全部的苹果都吃了，还剩下一个。", "explanation": "〈全部〉表示一个也不剩，这里却说还剩下一个，二者矛盾，不能这样用。"}, {"text": "全部同学都来了，但小王没到。", "explanation": "〈全部〉表示一个也不少，这里却说有人没到，二者矛盾，不能这样用。"}, {"text": "我把全部的书都扔了，还留着一本。", "explanation": "〈全部〉表示一个也不剩，这里却说还留着一本，二者矛盾，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全部", "is_correct": true, "explanation": "正确。“全部”修饰“学生”，表示一个也不少。"}, {"text": "全速", "is_correct": false, "explanation": "搭配：“全速”指最高速度，不能修饰“学生”。"}, {"text": "全身", "is_correct": false, "explanation": "搭配：“全身”指身体，不能修饰“学生”。"}, {"text": "全程", "is_correct": false, "explanation": "语义：“全程”指整个过程，不能用来表示人数的全体。"}], "explanations": {"全部": "正确。“全部”修饰“学生”，表示一个也不少。", "全速": "搭配：“全速”指最高速度，不能修饰“学生”。", "全身": "搭配：“全身”指身体，不能修饰“学生”。", "全程": "语义：“全程”指整个过程，不能用来表示人数的全体。"}, "sentence_index": 6, "correct_answer": "全部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司全部的人都很忙，只有一个人在忙。", "explanation": "〈全部〉表示一个也不少，而后半句的限定与此冲突，两者不能同时成立。"}, {"text": "公司全部的人都下班了，还有两个人留在办公室。", "explanation": "〈全部〉表示一个也不少，这里却说仍有人留下，二者矛盾，不能这样用。"}, {"text": "我们公司的全部员工，大约一半都很忙。", "explanation": "〈全部〉表示一个也不少，这里却指只占一半左右的人，二者矛盾，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把全部地书都卖了。", "corrected_sentence": "我把全部的书都卖了。", "error_description": "错误：“全部”修饰名词时，中间要用“的”，这里写成了“地”。正确：“全部的书”，“的”是定语标记，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
