INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指整个的、各个方面的总和，没有遗漏。", "primary_collocate": null, "pronunciation": "quán bù", "ipa": "tɕʰɥɛn˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这是故事的全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作就是他生活的全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子是她生活的全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要告诉我事情的全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情的全部都讲出来了。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了他一生的全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不是问题的全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐是我生活的全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只讲了事情的一部分，没讲全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道了这件事的全部。", "target_word": "全部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "事物各个方面的总和，没有遗漏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全部", "is_correct": true, "explanation": "正确。“全部”指事情各方面的总和，没有遗漏，可以用在“故事的”之后。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人的高矮，不能修饰“故事”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或动物的重量，不能用来说“故事”。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“敌人”是人，“故事的敌人”在语义上不成立。"}], "explanations": {"全部": "正确。“全部”指事情各方面的总和，没有遗漏，可以用在“故事的”之后。", "身高": "搭配：“身高”指人的高矮，不能修饰“故事”。", "体重": "搭配：“体重”指人或动物的重量，不能用来说“故事”。", "敌人": "语义：“敌人”是人，“故事的敌人”在语义上不成立。"}, "sentence_index": 0, "correct_answer": "全部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把事情的全部都告诉了你，但还有一件事没说。", "explanation": "〈全部〉表示没有遗漏，这里却说还有事情没说，二者矛盾，不能这样用。"}, {"text": "他讲出了事情的一半，也就是全部。", "explanation": "〈全部〉指没有遗漏的整体，这里却把只讲了一部分的情形称为全部，二者矛盾。"}, {"text": "他讲出了事情的全部，却漏掉了最关键的一段。", "explanation": "〈全部〉表示没有遗漏，这里却说漏掉了关键的一段，二者矛盾，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全部", "is_correct": true, "explanation": "正确。“全部”指问题各方面的总和，与“不是……的”搭配，句意通顺。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“性别”指人的生理特征，不能修饰“问题”。"}, {"text": "国籍", "is_correct": false, "explanation": "搭配：“国籍”属于人，与“问题”不能搭配。"}, {"text": "女儿", "is_correct": false, "explanation": "语义：“女儿”是人，“问题的女儿”在语义上不成立。"}], "explanations": {"全部": "正确。“全部”指问题各方面的总和，与“不是……的”搭配，句意通顺。", "性别": "搭配：“性别”指人的生理特征，不能修饰“问题”。", "国籍": "搭配：“国籍”属于人，与“问题”不能搭配。", "女儿": "语义：“女儿”是人，“问题的女儿”在语义上不成立。"}, "sentence_index": 6, "correct_answer": "全部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我连这件事的一半都没听完，却说自己知道了全部。", "explanation": "〈全部〉表示没有遗漏，这里说没听完一半却知道全部，二者矛盾，不能这样用。"}, {"text": "我记得这件事的全部，却忘了最关键的一句。", "explanation": "〈全部〉表示没有遗漏，这里却说忘了关键的一句，二者矛盾，不能这样用。"}, {"text": "他讲了一半就停了，这就是事情的全部。", "explanation": "〈全部〉指没有遗漏的整体，只讲了一半不能称为事情的全部，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他讲出了事情全部。", "corrected_sentence": "他讲出了事情的全部。", "error_description": "错误：“事情”和“全部”之间漏掉了“的”。正确：“事情的全部”，“的”连接定语“事情”和名词“全部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这就是问题地全部。", "corrected_sentence": "这就是问题的全部。", "error_description": "错误：“问题”与“全部”之间的“的”写成了“地”。正确：“问题的全部”，“的”是定语标记，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
