INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86561, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86561, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "宣布是当着大家的面公开说出一件事或一个决定。", "primary_collocate": null, "pronunciation": "xuān bù", "ipa": "ɕɥɛn˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "老师站起来，大声宣布：明天不上课。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长对全班同学宣布了一个好消息。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理走进会议室，宣布马上开会。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起话筒，向大家宣布比赛开始。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈高兴地宣布：今晚吃火锅！", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游站在车前，宣布下午三点集合。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机停下车，宣布大家可以下车了。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人宣布晚会正式开始。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门就宣布自己找到了工作。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在操场上宣布放假三天。", "target_word": "宣布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣布了", "label": "完成体"}, {"form": "宣布过", "label": "经历体"}, {"form": "宣佈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "当着大家的面公开说出一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86561, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣布", "is_correct": true, "explanation": "正确。“宣布”指当众大声说出一件事，与“大声”和后面的通知相符。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”是不让别人知道，与“大声”矛盾，也不能引出通知内容。"}, {"text": "低语", "is_correct": false, "explanation": "语义：“低语”是小声说话，与“大声”正好相反。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”是称赞人或事物，不能用来引出“明天不上课”这样的通知。"}], "explanations": {"宣布": "正确。“宣布”指当众大声说出一件事，与“大声”和后面的通知相符。", "隐瞒": "语义：“隐瞒”是不让别人知道，与“大声”矛盾，也不能引出通知内容。", "低语": "语义：“低语”是小声说话，与“大声”正好相反。", "赞美": "搭配：“赞美”是称赞人或事物，不能用来引出“明天不上课”这样的通知。"}, "sentence_index": 0, "correct_answer": "宣布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长在典礼上宣布了这篇讲话稿。", "explanation": "这里应该用〈宣读〉。“宣布”指公开说出决定或消息，朗读书面稿件要用“宣读”。"}, {"text": "他宣布了一把椅子。", "explanation": "这里应该用〈搬〉。“搬”指把物品从一处挪到另一处，“宣布”只能用于公开说出决定或消息，不能用于椅子。"}, {"text": "他在心里宣布了这个决定。", "explanation": "“宣布”必须公开说出，心里的想法是私下的，这里应该说“他在心里做了这个决定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣布", "is_correct": true, "explanation": "正确。“宣布”表示当众正式说出一件事，与“可以下车了”的通知相符。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”表示不许，与“可以下车”的许可意思矛盾。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：“惩罚”表示处罚，与“可以下车”的允许语境不符。"}, {"text": "哭泣", "is_correct": false, "explanation": "配价：“哭泣”是不及物动词，不能带“大家可以下车了”这样的宾语。"}], "explanations": {"宣布": "正确。“宣布”表示当众正式说出一件事，与“可以下车了”的通知相符。", "禁止": "语义：“禁止”表示不许，与“可以下车”的许可意思矛盾。", "惩罚": "语义：“惩罚”表示处罚，与“可以下车”的允许语境不符。", "哭泣": "配价：“哭泣”是不及物动词，不能带“大家可以下车了”这样的宾语。"}, "sentence_index": 6, "correct_answer": "宣布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在黑板前宣布了这道题的做法。", "explanation": "这里应该用〈讲解〉。“宣布”指正式公开说出决定或消息，讲解解题方法要用“讲解”。"}, {"text": "他宣布了一碗热腾腾的面条。", "explanation": "这里应该用〈吃〉。“吃”指把食物送入口中咽下，“宣布”只能用于公开说出决定或消息，不能用于面条。"}, {"text": "他一个人在房间里悄悄地宣布了自己的秘密。", "explanation": "“宣布”是当着大家的面公开说出，一个人悄悄说不能用“宣布”，这里应该用〈说出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班主任在教室里宣布得开学典礼推迟了。", "corrected_sentence": "班主任在教室里宣布开学典礼推迟了。", "error_description": "“宣布”后面不能直接加“得”，这里没有补语。应去掉“得”，改为“宣布开学典礼推迟了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市长明天宣布了新的规定。", "corrected_sentence": "市长明天宣布新的规定。", "error_description": "“了”表示动作已经完成，而“明天”指将来，二者矛盾。应去掉“了”，改为“明天宣布新的规定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
