INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分配人去担任工作或前往某处；委派。", "primary_collocate": null, "pronunciation": "pài", "ipa": "pʰaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "公司派他去上海工作。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校派两位老师去外地学习。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家派了很多医生去山区。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把他派到国外工作。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "单位派我去北京开会。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛学校会派谁去？", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报社派记者去灾区写新闻。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院派了三位医生去那个小镇。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司打算派小李当新经理。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板派他管理那家新商店。", "target_word": "派", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "派了", "label": "体标"}, {"form": "派过", "label": "体标"}, {"form": "派到", "label": "复合"}], "register": "中性", "sense_fingerprint": "委派人去某处工作或担任职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55ba4b8-27ee-40aa-8987-109ad1bec8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86566, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "派", "is_correct": true, "explanation": "派（pài）：委派人去某处工作或担任职务。"}, {"text": "拍", "is_correct": false, "explanation": "pāi（第一声）与 pài（第四声）声调不同，意思是拍照、拍打。"}, {"text": "牌", "is_correct": false, "explanation": "pái（第二声）与 pài（第四声）声调不同，意思是牌子、纸牌。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 pài 声母不同（b 与 p），意思是拜访。"}, {"text": "盼", "is_correct": false, "explanation": "pàn 与 pài 韵母不同（an 与 ai），意思是盼望。"}], "explanations": {"派": "派（pài）：委派人去某处工作或担任职务。", "拍": "pāi（第一声）与 pài（第四声）声调不同，意思是拍照、拍打。", "牌": "pái（第二声）与 pài（第四声）声调不同，意思是牌子、纸牌。", "拜": "bài 与 pài 声母不同（b 与 p），意思是拜访。", "盼": "pàn 与 pài 韵母不同（an 与 ai），意思是盼望。"}, "sentence_index": null, "correct_answer": "派"}, "level_3": {"options": [{"text": "派", "is_correct": true, "explanation": "“派”表示委派人去某处工作，“公司派他去上海工作”符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示进食，“公司吃他去上海工作”语义不通。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“他”作宾语。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能用来表示安排人去上海工作，与这类任务搭配不当。"}], "explanations": {"派": "“派”表示委派人去某处工作，“公司派他去上海工作”符合语境。", "吃": "语义：“吃”表示进食，“公司吃他去上海工作”语义不通。", "哭": "配价：“哭”是不及物动词，不能带“他”作宾语。", "咬": "搭配：“咬”不能用来表示安排人去上海工作，与这类任务搭配不当。"}, "sentence_index": 0, "correct_answer": "派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司把合同派到国外总部。", "explanation": "这里应该用〈寄〉。派只用于分派人员去担任工作或前往某处，合同这类文件要用寄。"}, {"text": "妈妈派我一个苹果。", "explanation": "这里应该用〈给〉。派用于分派人去工作或前往某处，把东西交给别人要用给。"}, {"text": "妈妈派我去国外旅游。", "explanation": "这里应该用〈带〉。派用于分派工作或任务，带我出国旅游不能用派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86566, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "派", "is_correct": true, "explanation": "派（pài）：委派人去某处工作或担任职务。"}, {"text": "排", "is_correct": false, "explanation": "pái（第二声）与 pài（第四声）声调不同，意思是排列。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 pài 声母不同（b 与 p），意思是失败。"}, {"text": "怕", "is_correct": false, "explanation": "pà 与 pài 韵母不同（少了 i 音），意思是害怕。"}, {"text": "佩", "is_correct": false, "explanation": "pèi 与 pài 韵母不同（ei 与 ai），意思是佩戴。"}], "explanations": {"派": "派（pài）：委派人去某处工作或担任职务。", "排": "pái（第二声）与 pài（第四声）声调不同，意思是排列。", "败": "bài 与 pài 声母不同（b 与 p），意思是失败。", "怕": "pà 与 pài 韵母不同（少了 i 音），意思是害怕。", "佩": "pèi 与 pài 韵母不同（ei 与 ai），意思是佩戴。"}, "sentence_index": null, "correct_answer": "派"}, "level_3": {"options": [{"text": "派", "is_correct": true, "explanation": "“派”表示委派人去某处工作，“报社派记者去灾区写新闻”符合语境。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“记者”作宾语。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”表示加热食物，与报社派记者去灾区写新闻的语境不符。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”表示采取、摘取，“报社摘记者”语义荒谬。"}], "explanations": {"派": "“派”表示委派人去某处工作，“报社派记者去灾区写新闻”符合语境。", "睡": "配价：“睡”是不及物动词，不能带“记者”作宾语。", "烤": "语义：“烤”表示加热食物，与报社派记者去灾区写新闻的语境不符。", "摘": "语义：“摘”表示采取、摘取，“报社摘记者”语义荒谬。"}, "sentence_index": 6, "correct_answer": "派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我派自己去国外工作。", "explanation": "这里应该用〈申请〉。派是别人作出安排，自己主动要求去工作应该用申请，不能用派。"}, {"text": "医生派病人去国外治疗。", "explanation": "这里应该用〈送〉。派只用于分派人员担任工作或前往某处，送病人去国外治疗不能用派。"}, {"text": "老师派我一个问题。", "explanation": "这里应该用〈问〉。派用于分派人去工作或前往某处，向别人提出问题要用问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDE