INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板派一名员工外地收账。", "corrected_sentence": "老板派一名员工去外地收账。", "error_description": "“派”后带人去某地时，“去”不能省略。错误形式：派一名员工外地收账；正确形式：派一名员工去外地收账。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01d16067-8674-448b-a625-f8be5da56510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
