INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "当地是说话的人正说到的那个地方。", "primary_collocate": null, "pronunciation": "dāng dì", "ipa": "taŋ˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这个小镇很美，当地的房子都是白色的。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边玩，当地的孩子教我们捡贝壳。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去日本旅游，住在当地的一户人家里。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地的冬天很长，常常下雪。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前，我查了当地的时间。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果是当地的特产。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震发生后，当地的居民马上互相帮忙。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问当地的老人，路怎么走。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在北京出生，所以很了解当地的历史。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请我们吃了当地最有名的鱼。", "target_word": "当地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说话的人正说到的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89977fd-f280-49cb-8f9f-d28e7bd372bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当地", "is_correct": true, "explanation": "正确：「当地」指说话人所说到的那个地方，「当地的房子」指小镇的房子，与句意相符。"}, {"text": "首都", "is_correct": false, "explanation": "语义：「首都」指国家的首都城市，与「这个小镇很美」所指的地方不一致。"}, {"text": "明天", "is_correct": false, "explanation": "语义：「明天」是时间词，「明天的房子都是白色的」说不通，前文说的是小镇这个地方。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：「课本」不能修饰「房子」，「课本的房子」搭配不当。"}], "explanations": {"当地": "正确：「当地」指说话人所说到的那个地方，「当地的房子」指小镇的房子，与句意相符。", "首都": "语义：「首都」指国家的首都城市，与「这个小镇很美」所指的地方不一致。", "明天": "语义：「明天」是时间词，「明天的房子都是白色的」说不通，前文说的是小镇这个地方。", "课本": "搭配：「课本」不能修饰「房子」，「课本的房子」搭配不当。"}, "sentence_index": 0, "correct_answer": "当地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司的当地在北京。", "explanation": "这里应该用〈所在地〉。当地指所说到的地方，不指机构的位置。"}, {"text": "一九九九年的当地，我还没有出生。", "explanation": "这里应该用〈当时〉。当地指地方，不指时间，「一九九九年的当地」说不通。"}, {"text": "我们家的当地很大，有一个院子。", "explanation": "这里应该用〈面积〉。当地指地方，不用来描述房子或院子的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当地", "is_correct": true, "explanation": "正确：「当地」指所说到的那个地方，「当地的居民」指那里的居民，与句意相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：「游客」指来旅游的人，不能指当地的居民，「游客的居民」说法矛盾。"}, {"text": "敌方", "is_correct": false, "explanation": "语义：「敌方」指敌对的一方，「敌方的居民」与「马上互相帮忙」矛盾。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：「昨天」是时间词，「昨天的居民」指过去的居民，不能与「地震发生后」这一当下事件搭配。"}], "explanations": {"当地": "正确：「当地」指所说到的那个地方，「当地的居民」指那里的居民，与句意相符。", "游客": "语义：「游客」指来旅游的人，不能指当地的居民，「游客的居民」说法矛盾。", "敌方": "语义：「敌方」指敌对的一方，「敌方的居民」与「马上互相帮忙」矛盾。", "昨天": "语义：「昨天」是时间词，「昨天的居民」指过去的居民，不能与「地震发生后」这一当下事件搭配。"}, "sentence_index": 6, "correct_answer": "当地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说有很多精彩的当地。", "explanation": "这里应该用〈地方〉（指部分、方面）。当地指某个区域或所说到的地方，不指作品中精彩的部分。"}, {"text": "他在朋友中的当地很高。", "explanation": "这里应该用〈地位〉。当地指地方，不指人在群体中的身份或位置。"}, {"text": "他陷入了困难的当地。", "explanation": "这里应该用〈境地〉。当地指地方，不指人所处的境况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我当地工作了五年。", "corrected_sentence": "我在当地工作了五年。", "error_description": "错误：「当地」前缺少介词「在」。正确形式是「在当地工作了五年」，表示工作的地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在当地的玩得很开心。", "corrected_sentence": "我们在当地玩得很开心。", "error_description": "错误：「当地」后多加了结构助词「的」，「当地的玩」不成词组。正确形式是「在当地玩得很开心」，地点作状语直接放在动词「玩」前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
