INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86569, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发表是在公开场合把自己的想法、看法或讲话说出来，让大家听到。", "primary_collocate": null, "pronunciation": "fā biǎo", "ipa": "fa˥ pjɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "开会时，经理先发表了自己的看法。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你对这件事发表一下意见。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长在大会上发表了讲话。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都想听听你发表什么看法。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很少在会上发表自己的意见。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们站起来发表看法。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统昨天发表了重要的电视讲话。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对比赛结果没有发表任何意见。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先别急着发表意见，听听大家怎么说。", "target_word": "发表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在会议上发表了对新计划的看法。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发表了", "label": "体标"}, {"form": "发表过", "label": "体标"}, {"form": "發表", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公开说出自己的看法、意见或讲话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86569, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发表", "is_correct": true, "explanation": "公开说出，与“看法”搭配，句意通顺。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物或方法，不能用于“看法”。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指把书刊印出来，不能用于口头表达的看法。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”的对象是影像，不能说“拍摄看法”。"}], "explanations": {"发表": "公开说出，与“看法”搭配，句意通顺。", "发明": "语义：“发明”指创造新事物或方法，不能用于“看法”。", "出版": "语义：“出版”指把书刊印出来，不能用于口头表达的看法。", "拍摄": "搭配：“拍摄”的对象是影像，不能说“拍摄看法”。"}, "sentence_index": 0, "correct_answer": "发表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用歌声发表了自己的感情。", "explanation": "这里应该用〈表达〉。发表指公开说出看法、意见；感情、心意要用表达。"}, {"text": "他点头发表了同意。", "explanation": "这里应该用〈表示〉。发表的宾语是看法、讲话等内容；点头表示态度要用表示。"}, {"text": "他用力发表了一拳。", "explanation": "这里应该用〈打〉。发表的宾语是看法、意见、讲话等内容，不能指击打的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86569, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物，不能用于讲话。"}, {"text": "发表", "is_correct": true, "explanation": "公开发布讲话，与“讲话”搭配，句意通顺。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造建筑或设施，不能用于讲话。"}, {"text": "烧制", "is_correct": false, "explanation": "搭配：“烧制”用于陶瓷等物品的加工，不能用于讲话。"}], "explanations": {"种植": "搭配：“种植”用于植物，不能用于讲话。", "发表": "公开发布讲话，与“讲话”搭配，句意通顺。", "修建": "语义：“修建”指建造建筑或设施，不能用于讲话。", "烧制": "搭配：“烧制”用于陶瓷等物品的加工，不能用于讲话。"}, "sentence_index": 6, "correct_answer": "发表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在班里发表了他。", "explanation": "这里应该用〈表扬〉。发表的宾语是看法、讲话等内容，不能指人。"}, {"text": "大家都在发表这个问题。", "explanation": "这里应该用〈讨论〉。发表指公开说出看法，不能直接以问题作宾语。"}, {"text": "他向领导发表了工作。", "explanation": "这里应该用〈汇报〉。向上级报告工作要用汇报，发表用于公开表达看法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在发表了一个看法。", "corrected_sentence": "他发表了一个看法。", "error_description": "错误：“正在”表示动作进行，与表示完成的“了”不能同时用。应删去“正在”，改为“他发表了一个看法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市长在会上发表了一本讲话。", "corrected_sentence": "市长在会上发表了一篇讲话。", "error_description": "错误：量词用错了。“发表”的“讲话”要用量词“篇”，“本”用于书。应说“发表了一篇讲话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
