INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发表是把文章、作品等登在报刊、网站等媒体上，让大家看到。", "primary_collocate": null, "pronunciation": "fā biǎo", "ipa": "fa˥ pjɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的文章发表在今天的报纸上。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章是她去年发表的。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在杂志上发表了一首小诗。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家又发表了一部新小说。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的论文发表以后，很多人都看过。", "target_word": "发表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我写的短文终于发表了，真高兴！", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇报道还没发表，请先别告诉别人。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每年都会发表几篇研究文章。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把写好的故事发表在网站上。", "target_word": "发表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位同学的作品发表在学校的杂志上。", "target_word": "发表", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发表了", "label": "体标"}, {"form": "发表过", "label": "体标"}, {"form": "發表", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把文章、作品登在报刊网站上让人看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "购买", "is_correct": false, "explanation": "搭配：“购买”指买东西，不能说“文章购买在报纸上”。"}, {"text": "发表", "is_correct": true, "explanation": "把文章登在报纸上，句意通顺。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”指去掉内容，不能说“文章删除在报纸上”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修补损坏的东西，不用于文章登报。"}], "explanations": {"购买": "搭配：“购买”指买东西，不能说“文章购买在报纸上”。", "发表": "把文章登在报纸上，句意通顺。", "删除": "语义：“删除”指去掉内容，不能说“文章删除在报纸上”。", "修理": "语义：“修理”指修补损坏的东西，不用于文章登报。"}, "sentence_index": 0, "correct_answer": "发表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她对着镜子发表了一个笑容。", "explanation": "这里应该用〈露出〉。发表用于文章、作品或言论，表情要用露出。"}, {"text": "他在会上发表了一位新同事。", "explanation": "这里应该用〈介绍〉。发表用于言论、作品，不能指人；把新同事介绍给大家要用介绍。"}, {"text": "学校发表了一场运动会。", "explanation": "这里应该用〈举行〉。发表指把文章、作品登出来或公开表达看法，举办活动要用举行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栽培", "is_correct": false, "explanation": "搭配：“栽培”用于培育植物或人才，不能用于报道。"}, {"text": "发表", "is_correct": true, "explanation": "指报道还没登出来，与“没”搭配，句意通顺。"}, {"text": "酿造", "is_correct": false, "explanation": "语义：“酿造”指发酵制作酒、醋等，与报道无关。"}, {"text": "烘焙", "is_correct": false, "explanation": "搭配：“烘焙”指烤制面点，不能用于报道。"}], "explanations": {"栽培": "搭配：“栽培”用于培育植物或人才，不能用于报道。", "发表": "指报道还没登出来，与“没”搭配，句意通顺。", "酿造": "语义：“酿造”指发酵制作酒、醋等，与报道无关。", "烘焙": "搭配：“烘焙”指烤制面点，不能用于报道。"}, "sentence_index": 6, "correct_answer": "发表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影明天在全国发表。", "explanation": "这里应该用〈上映〉。电影供公众观看要用上映；“发表”用于文章、作品登在报刊上。"}, {"text": "工人们发表了一座新桥。", "explanation": "这里应该用〈建造〉。“发表”只用于文章、作品或言论，不能指建造建筑。"}, {"text": "我向朋友发表了这本书。", "explanation": "这里应该用〈推荐〉。把好书介绍给别人要用推荐，发表指把文章、作品登出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章发表上周的报纸上。", "corrected_sentence": "这篇文章发表在上周的报纸上。", "error_description": "错误：“发表”后漏掉介词“在”。应改为“发表在……上”，即“这篇文章发表在上周的报纸上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在杂志一共发表了三篇论文。", "corrected_sentence": "他在杂志上一共发表了三篇论文。", "error_description": "错误：“在杂志”缺少方位词“上”。发表的处所要说“在……上”，应改为“他在杂志上一共发表了三篇论文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不然的话，表示如果不这样就会怎样，引出否则的结果。", "primary_collocate": null, "pronunciation": "yào bù", "ipa": "jɑʊ˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "快走吧，要不就迟到了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多穿点儿衣服，要不会感冒的。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你得早点睡，要不明天起不来。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我得带伞，要不就要淋雨了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点吃，要不饭就凉了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得快点儿，要不就赶不上车了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好学习，要不考试会不及格。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先给他打电话，要不他会担心。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带上手机，要不我找不到你。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快去买票，要不就没有了。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "要不然", "label": "复合"}], "register": "口语", "sense_fingerprint": "要不：不然的话，引出否则的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '749151d6-7ed4-4f35-af8d-c2dbfaf13d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要不", "is_correct": true, "explanation": "正确答案。要不（yào bù）：表示不然的话，引出否则的结果。"}, {"text": "腰部", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是腰部，不是要不。"}, {"text": "药物", "is_correct": false, "explanation": "wù 与 bù 声母不同，意思是药品，不是要不。"}, {"text": "要素", "is_correct": false, "explanation": "sù 与 bù 声母不同，意思是要素、基本成分，不是要不。"}, {"text": "药铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是卖药的店铺，不是要不。"}], "explanations": {"要不": "正确答案。要不（yào bù）：表示不然的话，引出否则的结果。", "腰部": "yāo（第一声）与 yào（第四声）声调不同，意思是腰部，不是要不。", "药物": "wù 与 bù 声母不同，意思是药品，不是要不。", "要素": "sù 与 bù 声母不同，意思是要素、基本成分，不是要不。", "药铺": "pù 与 bù 声母不同（p 与 b），意思是卖药的店铺，不是要不。"}, "sentence_index": null, "correct_answer": "要不"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "搭配：“因为”引出原因，后面需接结果，“快走吧，因为就迟到了”不成句。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”表示充分条件，“快走吧”并不是“迟到”的充分条件，句意说不通。"}, {"text": "要不", "is_correct": true, "explanation": "正确答案。“要不”表示不然的话，引出不利的结果，与“快走吧”和“迟到”的语境相符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”或“却”配合表示让步，这里不能这样用。"}], "explanations": {"因为": "搭配：“因为”引出原因，后面需接结果，“快走吧，因为就迟到了”不成句。", "只要": "语义：“只要”表示充分条件，“快走吧”并不是“迟到”的充分条件，句意说不通。", "要不": "正确答案。“要不”表示不然的话，引出不利的结果，与“快走吧”和“迟到”的语境相符。", "虽然": "搭配：“虽然”要与“但是”或“却”配合表示让步，这里不能这样用。"}, "sentence_index": 0, "correct_answer": "要不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认真复习，要不考试很容易。", "explanation": "这里应该用〈因此〉，表示因果。〈要不〉表示“不然的话”，后面要接不利的结果，不能接“考试很容易”这样的好结果。"}, {"text": "要不下雨，我就带伞。", "explanation": "这里应该用〈要是〉，引出假设条件。〈要不〉表示不然的话，引出不利的结果，不能引出假设。"}, {"text": "这个菜很好吃，要不很便宜。", "explanation": "这里应该用〈而且〉，表示递进。〈要不〉表示不然的话，后面要接不利的结果，不能接“很便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要不", "is_correct": true, "explanation": "正确答案。要不（yào bù）：表示不然的话，引出否则的结果。"}, {"text": "要务", "is_correct": false, "explanation": "wù 与 bù 声母不同，意思是重要的事务，不是要不。"}, {"text": "要路", "is_correct": false, "explanation": "lù 与 bù 声母不同，意思是重要的道路或位置，不是要不。"}, {"text": "腰部", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是身体的腰，不是要不。"}], "explanations": {"要不": "正确答案。要不（yào bù）：表示不然的话，引出否则的结果。", "要务": "wù 与 bù 声母不同，意思是重要的事务，不是要不。", "要路": "lù 与 bù 声母不同，意思是重要的道路或位置，不是要不。", "腰部": "yāo（第一声）与 yào（第四声）声调不同，意思是身体的腰，不是要不。"}, "sentence_index": null, "correct_answer": "要不"}, "level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“好好学习，所以考试会不及格”前后因果颠倒，不符合句意。"}, {"text": "要不", "is_correct": true, "explanation": "正确答案。“要不”表示不然的话，引出不利的结果，与“好好学习”和“考试会不及格”的语境相符。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示时间先后，“好好学习，然后考试会不及格”顺序不通，不符合句意。"}, {"text": "只有", "is_correct": false, "explanation": "语义：“只有”表示唯一条件，“好好学习”不是“考试不及格”的唯一条件，句意不通。"}], "explanations": {"所以": "语义：“所以”表示因果，“好好学习，所以考试会不及格”前后因果颠倒，不符合句意。", "要不": "正确答案。“要不”表示不然的话，引出不利的结果，与“好好学习”和“考试会不及格”的语境相符。", "然后": "语义：“然后”表示时间先后，“好好学习，然后考试会不及格”顺序不通，不符合句意。", "只有": "语义：“只有”表示唯一条件，“好好学习”不是“考试不及格”的唯一条件，句意不通。"}, "sentence_index": 6, "correct_answer": "要不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间很小，要不很安静。", "explanation": "这里应该用〈却〉，表示转折。〈要不〉表示不然的话，后面要引出不利的结果，不能接“很安静”。"}, {"text": "我以为很便宜，要不结果很贵。", "explanation": "这里应该用〈没想到〉，表示出乎意料。〈要不〉表示“不然的话”，不能表示转折或意外的结果。"}, {"text": "他每天早起，要不身体很好。", "explanation": "这里应该用〈因此〉，表示因果。〈要不〉表示不然的话，后面要引出不利的结果，不能接“身体很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天得早起，要不如果就赶不上车了。", "corrected_sentence": "明天得早起，要不就赶不上车了。", "error_description": "错误形式是“要不如果”，正确形式是“要不”。“要不”已表示不然的话，再加“如果”会造成条件连词重复，应去掉“如果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "快去拿伞，要不是就淋湿了。", "corrected_sentence": "快去拿伞，要不就淋湿了。", "error_description": "错误形式是“要不是”，正确形式是“要不”。“要不是”表示假设相反的情况，此处表示不然的话，应去掉“是”，用“要不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
