INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示如果不这样，就另有选择；用于提出另一种办法。", "primary_collocate": null, "pronunciation": "yào bù", "ipa": "jɑʊ˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "你累了吧？要不我们休息一下。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太冷，要不明天再去吧。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆人太多，要不去那家吧。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没空，要不你去问问小李。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不你给他打个电话吧。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢这件吗？要不再看看别的。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车太慢，要不我们走路去。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，要不你在我家住一晚。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太晚了，要不你明天早上走吧。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会做这个，要不你来试试。", "target_word": "要不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "要不然", "label": "复合"}], "register": "口语", "sense_fingerprint": "要不：提出另一种办法或建议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '749151d6-7ed4-4f35-af8d-c2dbfaf13d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要不", "is_correct": true, "explanation": "正确答案。要不（yào bù）：表示如果不这样，就另有选择，用于提出另一种办法。"}, {"text": "腰部", "is_correct": false, "explanation": "yāo（第一声）与 yào（第四声）声调不同，意思是腰部，不是要不。"}, {"text": "药物", "is_correct": false, "explanation": "wù 与 bù 声母不同，意思是药品，不是要不。"}, {"text": "要素", "is_correct": false, "explanation": "sù 与 bù 声母不同，意思是要素、基本成分，不是要不。"}, {"text": "药铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是卖药的店铺，不是要不。"}], "explanations": {"要不": "正确答案。要不（yào bù）：表示如果不这样，就另有选择，用于提出另一种办法。", "腰部": "yāo（第一声）与 yào（第四声）声调不同，意思是腰部，不是要不。", "药物": "wù 与 bù 声母不同，意思是药品，不是要不。", "要素": "sù 与 bù 声母不同，意思是要素、基本成分，不是要不。", "药铺": "pù 与 bù 声母不同（p 与 b），意思是卖药的店铺，不是要不。"}, "sentence_index": null, "correct_answer": "要不"}, "level_3": {"options": [{"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不这样就会怎样，前面要有明确的要求或假设，不能用来在“你累了吧？”之后提出建议。"}, {"text": "要不", "is_correct": true, "explanation": "正确答案。“要不”表示如果不这样，就另有选择，此处用来提出另一种办法，与“你累了吧？”的语境相符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”或“却”配合表示让步，此处后半句没有对应的转折，句子不成立。"}, {"text": "因为", "is_correct": false, "explanation": "搭配：“因为”要引出原因，后面需接结果，“你累了吧？因为我们休息一下”说不通。"}], "explanations": {"否则": "语义：“否则”表示不这样就会怎样，前面要有明确的要求或假设，不能用来在“你累了吧？”之后提出建议。", "要不": "正确答案。“要不”表示如果不这样，就另有选择，此处用来提出另一种办法，与“你累了吧？”的语境相符。", "虽然": "搭配：“虽然”要与“但是”或“却”配合表示让步，此处后半句没有对应的转折，句子不成立。", "因为": "搭配：“因为”要引出原因，后面需接结果，“你累了吧？因为我们休息一下”说不通。"}, "sentence_index": 0, "correct_answer": "要不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们快点走，要不就能看到日出了。", "explanation": "这里应该用〈这样〉，表示这样做就会有某个结果。〈要不〉表示“不然的话”，后面要接不利的结果，接“能看到日出”这样的好结果说不通。"}, {"text": "他昨天没来，要不今天来了。", "explanation": "这里应该用〈然后〉，表示先后顺序。〈要不〉表示提出办法或“不然的话”，不能表示时间上的先后。"}, {"text": "他很努力，要不成绩很好。", "explanation": "这里应该用〈因此〉，表示因果。〈要不〉表示“不然的话”，后面要接不利的结果，不能引出好的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要不", "is_correct": true, "explanation": "正确答案。要不（yào bù）：表示如果不这样，就另有选择，用于提出另一种办法。"}, {"text": "要补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充、弥补，不是要不。"}, {"text": "要务", "is_correct": false, "explanation": "wù 与 bù 声母不同，意思是重要的事务，不是要不。"}, {"text": "要付", "is_correct": false, "explanation": "fù 与 bù 声母不同，意思是支付，不是要不。"}, {"text": "要路", "is_correct": false, "explanation": "lù 与 bù 声母不同，意思是重要的道路或位置，不是要不。"}], "explanations": {"要不": "正确答案。要不（yào bù）：表示如果不这样，就另有选择，用于提出另一种办法。", "要补": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充、弥补，不是要不。", "要务": "wù 与 bù 声母不同，意思是重要的事务，不是要不。", "要付": "fù 与 bù 声母不同，意思是支付，不是要不。", "要路": "lù 与 bù 声母不同，意思是重要的道路或位置，不是要不。"}, "sentence_index": null, "correct_answer": "要不"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "搭配：“因为”要引出原因，后面需接结果，“坐车太慢，因为我们走路去”不成句，也与提议语境不合。"}, {"text": "而", "is_correct": false, "explanation": "语域：“而”是书面连词，口语中不这样接在“我们”前面，句子生硬。"}, {"text": "要不", "is_correct": true, "explanation": "正确答案。“要不”表示如果不这样，就另有选择，此处用来提出另一种办法，与“坐车太慢”的语境相符。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”表示转折，须放在主语之后，“坐车太慢，却我们走路去”语序不通。"}], "explanations": {"因为": "搭配：“因为”要引出原因，后面需接结果，“坐车太慢，因为我们走路去”不成句，也与提议语境不合。", "而": "语域：“而”是书面连词，口语中不这样接在“我们”前面，句子生硬。", "要不": "正确答案。“要不”表示如果不这样，就另有选择，此处用来提出另一种办法，与“坐车太慢”的语境相符。", "却": "搭配：“却”表示转折，须放在主语之后，“坐车太慢，却我们走路去”语序不通。"}, "sentence_index": 6, "correct_answer": "要不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很想去，要不没有时间。", "explanation": "这里应该用〈但是〉，表示转折。〈要不〉表示提出办法或“不然的话”，不能表示转折。"}, {"text": "这个电影很长，要不很无聊。", "explanation": "这里应该用〈而且〉，表示递进。〈要不〉表示提出办法或“不然的话”，不能用来并列两个描述。"}, {"text": "他说他会来，要不现在还没到。", "explanation": "这里应该用〈却〉，表示转折。〈要不〉不表示转折，后面应接不利的结果，不能用来描述现状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "外面下雨了，很要不我们明天再出去吧。", "corrected_sentence": "外面下雨了，要不我们明天再出去吧。", "error_description": "错误形式：“很要不”；正确形式：“要不”。“很”只能修饰形容词等，不能修饰连词“要不”，应直接用“要不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天下雨，要不是我们改天再去吧。", "corrected_sentence": "明天下雨，要不我们改天再去吧。", "error_description": "错误形式是“要不是”，正确形式是“要不”。“要不是”表示假设相反的情况，后面要接结论；这里是提出办法，应去掉“是”，用“要不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
