INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86573, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "要人是很重要、很有名的人。", "primary_collocate": null, "pronunciation": "yào rén", "ipa": "jɑʊ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这个人很有名，是个要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店里住着几位要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当一个社会上的要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在大公司工作，认识不少要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位要人一来，大家都站起来了。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是要人，只是普通的老师。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天有要人来学校看我们。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口停着好几辆车，里面坐着要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上见过这位要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市常有各国要人来访。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "书面", "sense_fingerprint": "要人：很重要、很有名的人，泛指各界有名望的人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86573, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要人", "is_correct": true, "explanation": "要人（yào rén）：很重要、很有名的人，泛指各界有名望的人物"}, {"text": "咬人", "is_correct": false, "explanation": "yǎo（第三声）与 yào（第四声）声调不同，咬人指用牙齿咬别人"}, {"text": "邀人", "is_correct": false, "explanation": "声调混淆：yāo（第一声）与 yào（第四声）声调不同，邀人指邀请别人"}, {"text": "妖人", "is_correct": false, "explanation": "声调混淆：yāo（第一声）与 yào（第四声）声调不同，妖人指行邪术、害人的人"}, {"text": "摇人", "is_correct": false, "explanation": "yáo（第二声）与 yào（第四声）声调不同，摇人指号召别人来帮忙"}], "explanations": {"要人": "要人（yào rén）：很重要、很有名的人，泛指各界有名望的人物", "咬人": "yǎo（第三声）与 yào（第四声）声调不同，咬人指用牙齿咬别人", "邀人": "声调混淆：yāo（第一声）与 yào（第四声）声调不同，邀人指邀请别人", "妖人": "声调混淆：yāo（第一声）与 yào（第四声）声调不同，妖人指行邪术、害人的人", "摇人": "yáo（第二声）与 yào（第四声）声调不同，摇人指号召别人来帮忙"}, "sentence_index": null, "correct_answer": "要人"}, "level_3": {"options": [{"text": "要人", "is_correct": true, "explanation": "正确：指很重要、很有名的人，与“很有名”相符"}, {"text": "凡人", "is_correct": false, "explanation": "语义：凡人指普通人，与“很有名”相矛盾"}, {"text": "草民", "is_correct": false, "explanation": "语域：草民是旧时对平民的称呼，不用于描写现代有名的人"}, {"text": "路灯", "is_correct": false, "explanation": "搭配：“路灯”不是人，与“这个人”不能指同一对象，句子不成立。"}], "explanations": {"要人": "正确：指很重要、很有名的人，与“很有名”相符", "凡人": "语义：凡人指普通人，与“很有名”相矛盾", "草民": "语域：草民是旧时对平民的称呼，不用于描写现代有名的人", "路灯": "搭配：“路灯”不是人，与“这个人”不能指同一对象，句子不成立。"}, "sentence_index": 0, "correct_answer": "要人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只是个普通要人，没人认识他。", "explanation": "这里应该用〈普通人〉。要人指很重要、很有名的人，与“普通”和“没人认识”相矛盾"}, {"text": "要人每天都给我们上课，很辛苦。", "explanation": "这里应该用〈老师〉。要人指各界有名望的重要人物，不指教课的老师"}, {"text": "要人在地里辛苦地干活。", "explanation": "这里应该用〈农民〉。要人指很重要、很有名的人，不指在田间劳动的人"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86573, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要人", "is_correct": true, "explanation": "要人（yào rén）：很重要、很有名的人，泛指各界有名望的人物"}, {"text": "有人", "is_correct": false, "explanation": "yǒu 与 yào 韵母不同（ou 与 ao），有人指存在某个人"}, {"text": "诱人", "is_correct": false, "explanation": "yòu 与 yào 韵母不同（ou 与 ao），诱人指有吸引力"}, {"text": "瑶人", "is_correct": false, "explanation": "yáo（第二声）与 yào（第四声）声调不同，瑶人指瑶族的人"}], "explanations": {"要人": "要人（yào rén）：很重要、很有名的人，泛指各界有名望的人物", "有人": "yǒu 与 yào 韵母不同（ou 与 ao），有人指存在某个人", "诱人": "yòu 与 yào 韵母不同（ou 与 ao），诱人指有吸引力", "瑶人": "yáo（第二声）与 yào（第四声）声调不同，瑶人指瑶族的人"}, "sentence_index": null, "correct_answer": "要人"}, "level_3": {"options": [{"text": "要人", "is_correct": true, "explanation": "正确：指各界有名望的重要人物，与“来学校看我们”的语境相符"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不是有名望的人，来学校看我们与常理不符"}, {"text": "鬼", "is_correct": false, "explanation": "语义：鬼是虚构的事物，不能来学校看我们"}, {"text": "草民", "is_correct": false, "explanation": "语域：草民是旧时用语，不用于指现代到校访问的人"}], "explanations": {"要人": "正确：指各界有名望的重要人物，与“来学校看我们”的语境相符", "小偷": "语义：小偷不是有名望的人，来学校看我们与常理不符", "鬼": "语义：鬼是虚构的事物，不能来学校看我们", "草民": "语域：草民是旧时用语，不用于指现代到校访问的人"}, "sentence_index": 6, "correct_answer": "要人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天我们学校来了一只要人。", "explanation": "这里应该用〈位〉。“只”多用于动物或细小的东西，不用来数人，指人应用“位”"}, {"text": "这座城市常有一头要人来访。", "explanation": "这里应该用〈位〉。“头”多用于牲畜，不能用来数要人"}, {"text": "那个路口走来一条要人。", "explanation": "这里应该用〈位〉。“条”用于细长的东西，不能用来数要人"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的朋友里有一只要人。", "corrected_sentence": "他的朋友里有一位要人。", "error_description": "量词错误：“要人”指人，应说“一位要人”，不能用“一只”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一只有名的要人，大家都认识他。", "corrected_sentence": "他是个有名的要人，大家都认识他。", "error_description": "量词错误：“要人”指人，量词应用“个”，不能用“只”（“只”多用于动物或细小的东西）", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
