INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指地位高、有重要影响的人物，多指政界人物。", "primary_collocate": null, "pronunciation": "yào rén", "ipa": "jɑʊ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "会议开始前，几位要人先到了。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位要人常常在电视上说话。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，有一位要人明天来我们市。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家的要人参加了这次会议。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里来了不少要人，警察也很多。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在政府工作，认识很多要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些要人下车后，走进了大楼。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位要人说，明年会有新办法。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者们等着采访那几位要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的政界要人。", "target_word": "要人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "政界要人", "label": "复合"}], "register": "书面", "sense_fingerprint": "要人：地位高、影响大的人物，多指政界，常见于新闻和会议场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5c8e8d-5cbc-49a4-af4d-6ec1f2b6d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86574, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要人", "is_correct": true, "explanation": "要人（yào rén）：地位高、影响大的人物，多指政界人物"}, {"text": "咬人", "is_correct": false, "explanation": "声调混淆：yǎo（第三声）与 yào（第四声）声调不同，咬人指用牙齿咬别人"}, {"text": "邀人", "is_correct": false, "explanation": "声调混淆：yāo（第一声）与 yào（第四声）声调不同，邀人指邀请别人"}, {"text": "妖人", "is_correct": false, "explanation": "声调混淆：yāo（第一声）与 yào（第四声）声调不同，妖人指行邪术、害人的人"}, {"text": "摇人", "is_correct": false, "explanation": "声调混淆：yáo（第二声）与 yào（第四声）声调不同，摇人指号召别人来帮忙"}], "explanations": {"要人": "要人（yào rén）：地位高、影响大的人物，多指政界人物", "咬人": "声调混淆：yǎo（第三声）与 yào（第四声）声调不同，咬人指用牙齿咬别人", "邀人": "声调混淆：yāo（第一声）与 yào（第四声）声调不同，邀人指邀请别人", "妖人": "声调混淆：yāo（第一声）与 yào（第四声）声调不同，妖人指行邪术、害人的人", "摇人": "声调混淆：yáo（第二声）与 yào（第四声）声调不同，摇人指号召别人来帮忙"}, "sentence_index": null, "correct_answer": "要人"}, "level_3": {"options": [{"text": "要人", "is_correct": true, "explanation": "正确：指地位高、影响大的人物，与“会议”“几位”的语境相符"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不是人，“几位”计数的是人，句子不成立"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不能来会议场所先到，与语境不符"}, {"text": "信号", "is_correct": false, "explanation": "搭配：“几位”只能计数人，不能与“信号”搭配"}], "explanations": {"要人": "正确：指地位高、影响大的人物，与“会议”“几位”的语境相符", "花瓶": "语义：花瓶不是人，“几位”计数的是人，句子不成立", "老虎": "语义：老虎不能来会议场所先到，与语境不符", "信号": "搭配：“几位”只能计数人，不能与“信号”搭配"}, "sentence_index": 0, "correct_answer": "要人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只是个普通要人，平时很少出门。", "explanation": "这里应该用〈普通人〉。要人指地位高、影响大的人物，与“普通”相矛盾"}, {"text": "他是一位有名的要人，经常在电影里演主角。", "explanation": "这里应该用〈明星〉。要人指政界等地位高的人物，不指影视演员，应说“明星”"}, {"text": "工厂里的要人们正在忙着干活。", "explanation": "这里应该用〈工人〉。要人指地位高的人物，不指在工厂干活的劳动者"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86574, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要人", "is_correct": true, "explanation": "要人（yào rén）：地位高、影响大的人物，多指政界人物"}, {"text": "有人", "is_correct": false, "explanation": "yǒu 与 yào 韵母不同（ou 与 ao），有人指存在某个人"}, {"text": "诱人", "is_correct": false, "explanation": "yòu 与 yào 韵母不同（ou 与 ao），诱人指有吸引力"}, {"text": "瑶人", "is_correct": false, "explanation": "yáo（第二声）与 yào（第四声）声调不同，瑶人指瑶族的人"}], "explanations": {"要人": "要人（yào rén）：地位高、影响大的人物，多指政界人物", "有人": "yǒu 与 yào 韵母不同（ou 与 ao），有人指存在某个人", "诱人": "yòu 与 yào 韵母不同（ou 与 ao），诱人指有吸引力", "瑶人": "yáo（第二声）与 yào（第四声）声调不同，瑶人指瑶族的人"}, "sentence_index": null, "correct_answer": "要人"}, "level_3": {"options": [{"text": "要人", "is_correct": true, "explanation": "正确：指身份高、有影响的人物，能下车并走进大楼"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能下车，也不会走进大楼"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件不会下车，也不会自己走进大楼"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会自己下车，也不会走进大楼"}], "explanations": {"要人": "正确：指身份高、有影响的人物，能下车并走进大楼", "石头": "语义：石头不能下车，也不会走进大楼", "文件": "语义：文件不会下车，也不会自己走进大楼", "桌子": "语义：桌子不会自己下车，也不会走进大楼"}, "sentence_index": 6, "correct_answer": "要人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一只有名的政界要人。", "explanation": "这里应该用〈位〉。“只”多用于动物或细小的东西，不用来数人，指人应用“位”"}, {"text": "他是一头有名的政界要人。", "explanation": "这里应该用〈位〉。“头”多用于牲畜，不能用来数要人"}, {"text": "他是一条有名的政界要人。", "explanation": "这里应该用〈位〉。“条”用于细长的东西，不能用来数要人"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天有三条要人来到了机场。", "corrected_sentence": "昨天有三位要人来到了机场。", "error_description": "量词错误：“要人”指人，应说“三位要人”，“条”用于细长的东西，不能用来数人", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请来了一把政界要人。", "corrected_sentence": "我们请来了一位政界要人。", "error_description": "量词错误：“要人”指人，应说“一位政界要人”，“把”用于有柄的器物，不能用来数人", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19cff2b4-f35e-4a47-90b2-454a707e75d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
