INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86575, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "那里是离我们比较远的那个地方。", "primary_collocate": null, "pronunciation": "nà lǐ", "ipa": "na˥˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "那里是我出生的地方。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的山很高，风景很美。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去那里看看。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在那里等着我们。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里没有地铁，只能坐公交车。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里很吵，那里很安静。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在了那里。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的饭菜又便宜又好吃。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很久没去那里了。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里就是我们明天要去的公园。", "target_word": "那里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那儿", "label": "口语变体"}], "register": "中性", "sense_fingerprint": "那里：离说话人较远的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”是疑问代词，句子会变成疑问，不能陈述“我出生的地方”。"}, {"text": "那里", "is_correct": true, "explanation": "指离说话人较远的那个地方，作主语，句意通顺。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能作“我出生的地方”的主语。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指群体，不能与“出生的地方”构成同位关系。"}], "explanations": {"哪里": "语义：“哪里”是疑问代词，句子会变成疑问，不能陈述“我出生的地方”。", "那里": "指离说话人较远的那个地方，作主语，句意通顺。", "谁": "语义：“谁”指人，不能作“我出生的地方”的主语。", "大家": "搭配：“大家”指群体，不能与“出生的地方”构成同位关系。"}, "sentence_index": 0, "correct_answer": "那里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你把那里给我拿过来。", "explanation": "这里应该用〈那个〉。那里指地方，不能指要拿的东西，指东西要用那个。"}, {"text": "那里是我们的老师，他很严格。", "explanation": "这里应该用〈那位〉。那里只指处所，不能用来指人。"}, {"text": "那里不喜欢吃辣的。", "explanation": "这里应该用〈他〉。那里指地方，不能作“喜欢”的主语，指人要用他。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那里", "is_correct": true, "explanation": "表示处所，作“停在”的宾语，句意通顺。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”是疑问代词，“停在了哪里”作陈述不成立，只能用于提问。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，不指地方，不能作“停在”的处所宾语，句意不通。"}, {"text": "自己", "is_correct": false, "explanation": "配价：“自己”指自身，不能作“停在”的处所宾语，“停在了自己”句意不通。"}], "explanations": {"那里": "表示处所，作“停在”的宾语，句意通顺。", "哪里": "语义：“哪里”是疑问代词，“停在了哪里”作陈述不成立，只能用于提问。", "别人": "语义：“别人”指他人，不指地方，不能作“停在”的处所宾语，句意不通。", "自己": "配价：“自己”指自身，不能作“停在”的处所宾语，“停在了自己”句意不通。"}, "sentence_index": 6, "correct_answer": "那里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那里，我们走吧。", "explanation": "这里应该用〈那么〉。那里是处所词，不能用来表示承接的语气。"}, {"text": "我们不能那里做。", "explanation": "这里应该用〈那样〉。那里只表示处所，不能修饰“做”的方式。"}, {"text": "那里我还是个孩子。", "explanation": "这里应该用〈那时〉。那里指地点，表示过去的时间要用那时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天在那里去。", "corrected_sentence": "我们明天到那里去。", "error_description": "错误：“去”表示前往某处，要用“到”引出目的地，不能用“在”。应改为“我们明天到那里去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在在那里做饭。", "corrected_sentence": "妈妈在那里做饭。", "error_description": "错误：“在”重复出现。“在那里”中的“在”只用一次，应改为“妈妈在那里做饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
