INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今年是现在这一年。", "primary_collocate": null, "pronunciation": "jīn nián", "ipa": "tɕin˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "今年是我学中文的第三年。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年快五十岁了。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的生日，我想和朋友去爬山。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我们搬到了新家。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年北京下了三次大雪。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今年的目标是每天跑步。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的考试比去年难。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶今年身体很好。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年九月，我们要去海边玩。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店今年开了两家分店。", "target_word": "今年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "现在这一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89977fd-f280-49cb-8f9f-d28e7bd372bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今年", "is_correct": true, "explanation": "正确：「今年」指现在这一年，「是我学中文的第三年」说的正是当前这一年。"}, {"text": "今天", "is_correct": false, "explanation": "语义：「今天」指一天，「今天是我学中文的第三年」与以年为单位的说法矛盾。"}, {"text": "每年", "is_correct": false, "explanation": "语义：「每年」表示重复的年份，不能说「每年是第三年」。"}, {"text": "明天", "is_correct": false, "explanation": "语义：「明天」指一天，不能说「明天是我学中文的第三年」，与以年为单位的说法矛盾。"}], "explanations": {"今年": "正确：「今年」指现在这一年，「是我学中文的第三年」说的正是当前这一年。", "今天": "语义：「今天」指一天，「今天是我学中文的第三年」与以年为单位的说法矛盾。", "每年": "语义：「每年」表示重复的年份，不能说「每年是第三年」。", "明天": "语义：「明天」指一天，不能说「明天是我学中文的第三年」，与以年为单位的说法矛盾。"}, "sentence_index": 0, "correct_answer": "今年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在2010年的今年结了婚。", "explanation": "「今年」指现在这一年，不能指过去的某一年，应该用〈那一年〉。"}, {"text": "以后的今年，我要考上大学。", "explanation": "这里应该用〈明年〉。今年指现在这一年，不能指以后的某一年，与「以后」矛盾。"}, {"text": "今年的他出生在三十年前。", "explanation": "这里应该用〈当年〉。今年指现在这一年，不能指三十年前的某一年；说过去的人或事要用〈当年〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今年", "is_correct": true, "explanation": "正确：「今年」指现在这一年，与「比去年难」的比较相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：「昨天」指一天，「昨天的考试比去年难」时间上不相称。"}, {"text": "去年", "is_correct": false, "explanation": "语义：「去年的考试比去年难」是拿去年跟自己比，说不通。"}, {"text": "贵方", "is_correct": false, "explanation": "语域：「贵方」是敬称对方的一方，用来说明考试难度不合适。"}], "explanations": {"今年": "正确：「今年」指现在这一年，与「比去年难」的比较相符。", "昨天": "语义：「昨天」指一天，「昨天的考试比去年难」时间上不相称。", "去年": "语义：「去年的考试比去年难」是拿去年跟自己比，说不通。", "贵方": "语域：「贵方」是敬称对方的一方，用来说明考试难度不合适。"}, "sentence_index": 6, "correct_answer": "今年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的今年很大。", "explanation": "这里应该用〈面积〉或〈规模〉。今年是时间，不能用来描述店铺的大小。"}, {"text": "今年上午我去了银行。", "explanation": "这里应该用〈今天〉。今年指一整年，不能指一天中的上午。"}, {"text": "今年的晚上我们在家吃饭。", "explanation": "这里应该用〈今晚〉。今年指一整年，不能指一天中的晚上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今年了在北京工作。", "corrected_sentence": "我今年在北京工作。", "error_description": "错误：「今年」后多加了「了」。「了」表示完成，不能紧跟时间词「今年」；正确形式是「我今年在北京工作」，「今年」直接作时间状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司今年的招了三个新员工。", "corrected_sentence": "我们公司今年招了三个新员工。", "error_description": "错误：「今年」后多加了「的」，「今年的招了」不通。正确形式是「今年招了三个新员工」，「今年」作时间状语直接修饰动作，不加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86579, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
