INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86579, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指不是这个，而是另外的。", "primary_collocate": null, "pronunciation": "bié de", "ipa": "pjɛ˧˥ tə", "syllable_count": 2, "sentences": [{"text": "这个不是我的，别的才是我的。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔不好用，换别的吧。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只会说中文，不会说别的话。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红的卖完了，还有别的吗？", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别的人都走了，只有我在。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喝咖啡，请给我别的饮料。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路太远，我们走别的路吧。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了这个，别的我都不想要。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法不行，我们想想别的。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天没有时间，别的以后再说。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不是这个，是另外的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86579, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "别的", "is_correct": true, "explanation": "正确答案。别的 bié de，指不是这个而是另外的。"}, {"text": "憋得", "is_correct": false, "explanation": "bié（第二声）与 biē（第一声）声调不同，意思是“憋得”（气闷到某种程度）。"}, {"text": "瘪的", "is_correct": false, "explanation": "bié（第二声）与 biě（第三声）声调不同，意思是“瘪的”（向内凹下去）。"}, {"text": "叠得", "is_correct": false, "explanation": "bié 与 dié 声母不同（b 与 d），意思是“叠得”（折叠得整齐）。"}], "explanations": {"别的": "正确答案。别的 bié de，指不是这个而是另外的。", "憋得": "bié（第二声）与 biē（第一声）声调不同，意思是“憋得”（气闷到某种程度）。", "瘪的": "bié（第二声）与 biě（第三声）声调不同，意思是“瘪的”（向内凹下去）。", "叠得": "bié 与 dié 声母不同（b 与 d），意思是“叠得”（折叠得整齐）。"}, "sentence_index": null, "correct_answer": "别的"}, "level_3": {"options": [{"text": "别的", "is_correct": true, "explanation": "正确。“别的”指与“这个”不同的另一个，与前句“这个不是我的”呼应。"}, {"text": "这个", "is_correct": false, "explanation": "语义：前句已说“这个不是我的”，再说“这个才是我的”自相矛盾。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”指人，不能与“是……的”所属对象对应，“自己才是我的”不通。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”是集合名称，不能指单个物品，“大家才是我的”不成立。"}], "explanations": {"别的": "正确。“别的”指与“这个”不同的另一个，与前句“这个不是我的”呼应。", "这个": "语义：前句已说“这个不是我的”，再说“这个才是我的”自相矛盾。", "自己": "搭配：“自己”指人，不能与“是……的”所属对象对应，“自己才是我的”不通。", "大家": "搭配：“大家”是集合名称，不能指单个物品，“大家才是我的”不成立。"}, "sentence_index": 0, "correct_answer": "别的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想要别的一杯咖啡。", "explanation": "这里应该用〈另一杯〉。“别的”后面不能接“一＋量词”，要说“另一杯”。"}, {"text": "这件事我别的告诉你。", "explanation": "这里应该用〈另外〉。“别的”是代词，不能放在动词前作状语。"}, {"text": "你别的哭了，好吗？", "explanation": "这里应该用〈别〉。劝人不要做某事用“别”，不能用“别的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别的", "is_correct": true, "explanation": "正确。“别的路”指与“这条路”不同的另一条路，与前句的“太远”形成换路的语境。"}, {"text": "此", "is_correct": false, "explanation": "语域：“此路”是书面语，口语语境中不用，且“此”指前文所说的路，与“换”一条路的意思冲突。"}, {"text": "这", "is_correct": false, "explanation": "语义：“这路”指前句的“这条路”，与“太远”后要换路的语境矛盾。"}, {"text": "某", "is_correct": false, "explanation": "语义：“某路”指不确定的路，与前句已明确的“这条路”所指不一致。"}], "explanations": {"别的": "正确。“别的路”指与“这条路”不同的另一条路，与前句的“太远”形成换路的语境。", "此": "语域：“此路”是书面语，口语语境中不用，且“此”指前文所说的路，与“换”一条路的意思冲突。", "这": "语义：“这路”指前句的“这条路”，与“太远”后要换路的语境矛盾。", "某": "语义：“某路”指不确定的路，与前句已明确的“这条路”所指不一致。"}, "sentence_index": 6, "correct_answer": "别的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "别的一个人也来了。", "explanation": "这里应该用〈另一个〉。“别的”后面不能接“一个”，要说“另一个人”。"}, {"text": "他别的问了我一个问题。", "explanation": "这里应该用〈又〉。“别的”是代词，不能修饰动词“问”。"}, {"text": "你别的走，等等我。", "explanation": "这里应该用〈别〉。表示劝阻用“别”，不能用“别的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支笔不好用，还有别的的吗？", "corrected_sentence": "这支笔不好用，还有别的吗？", "error_description": "错误：“别的”后多加一个“的”，写成“别的的”。正确：应为“还有别的吗”，“别的”作代词本身已含“的”，重复不符合口语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们换别的个路吧。", "corrected_sentence": "我们换别的路吧。", "error_description": "错误：“别的”与“路”之间多加了量词“个”，写成“别的个路”。正确：应为“别的路”，“别的”作定语后直接接名词，中间不能加量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
