INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86580, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，另外的（人或事物）。", "primary_collocate": null, "pronunciation": "bié de", "ipa": "pjɛ˧˥ tə", "syllable_count": 2, "sentences": [{"text": "我只要这个，别的都不要。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你还有别的事吗？", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件太小了，我想看看别的。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了苹果，我还买了别的水果。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天先吃面条，别的事情明天再说。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店没有别的颜色了。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想去，你找别的人吧。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了数学，别的课我都喜欢。", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我看过了，有别的吗？", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想喝茶，还是喝别的？", "target_word": "别的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "指这个以外的另外的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '260eacad-2f60-4e4d-8b4e-8536845f9063') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86580, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "别的", "is_correct": true, "explanation": "正确答案。别的 bié de，指除这个以外的人或事物。"}, {"text": "憋得", "is_correct": false, "explanation": "bié（第二声）与 biē（第一声）声调不同，意思是“憋得”（气闷到某种程度）。"}, {"text": "瘪的", "is_correct": false, "explanation": "bié（第二声）与 biě（第三声）声调不同，意思是“瘪的”（向内凹下去）。"}, {"text": "叠得", "is_correct": false, "explanation": "bié 与 dié 声母不同（b 与 d），意思是“叠得”（折叠得整齐）。"}], "explanations": {"别的": "正确答案。别的 bié de，指除这个以外的人或事物。", "憋得": "bié（第二声）与 biē（第一声）声调不同，意思是“憋得”（气闷到某种程度）。", "瘪的": "bié（第二声）与 biě（第三声）声调不同，意思是“瘪的”（向内凹下去）。", "叠得": "bié 与 dié 声母不同（b 与 d），意思是“叠得”（折叠得整齐）。"}, "sentence_index": null, "correct_answer": "别的"}, "level_3": {"options": [{"text": "别的", "is_correct": true, "explanation": "正确。“别的”指除“这个”以外的东西，与前句“只要这个”形成对照。"}, {"text": "这个", "is_correct": false, "explanation": "语义：前句已说“只要这个”，若说“这个都不要”就与之自相矛盾。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个都不要”是任何一个都不要，包括“这个”在内，与“只要这个”冲突。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”指人，不能作“都不要”的事物对象，“自己都不要”不成立。"}], "explanations": {"别的": "正确。“别的”指除“这个”以外的东西，与前句“只要这个”形成对照。", "这个": "语义：前句已说“只要这个”，若说“这个都不要”就与之自相矛盾。", "哪个": "语义：“哪个都不要”是任何一个都不要，包括“这个”在内，与“只要这个”冲突。", "自己": "搭配：“自己”指人，不能作“都不要”的事物对象，“自己都不要”不成立。"}, "sentence_index": 0, "correct_answer": "别的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我还买了别的一个苹果。", "explanation": "这里应该用〈另一个〉。“别的”后面不能接“一个”。"}, {"text": "我别的买了一些水果。", "explanation": "这里应该用〈另外〉。“别的”是代词，不能放在动词前作状语。"}, {"text": "你别的买了，太多了。", "explanation": "这里应该用〈别〉。劝阻用“别”，不能用“别的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别的", "is_correct": true, "explanation": "正确。“别的人”指除“他”以外的人，与“他不想去”形成对照。"}, {"text": "哪个", "is_correct": false, "explanation": "语法：“哪个人”是疑问，不能用在“你找……吧”这样的建议句中。"}, {"text": "此", "is_correct": false, "explanation": "语义：“此人”指前文的“他”，与“你找”另一个人的语境相反。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：“每个人”强调逐一，不能用来表示“他”之外的另一个人，与“你找”的意思不合。"}], "explanations": {"别的": "正确。“别的人”指除“他”以外的人，与“他不想去”形成对照。", "哪个": "语法：“哪个人”是疑问，不能用在“你找……吧”这样的建议句中。", "此": "语义：“此人”指前文的“他”，与“你找”另一个人的语境相反。", "每个": "搭配：“每个人”强调逐一，不能用来表示“他”之外的另一个人，与“你找”的意思不合。"}, "sentence_index": 6, "correct_answer": "别的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你想喝别的一杯茶吗？", "explanation": "这里应该用〈另一杯〉。“别的”后面不能接“一杯”。"}, {"text": "他喝了一杯茶，然后又喝了别的人。", "explanation": "这里应该用〈别的东西〉。“别的人”不能作“喝”的宾语，搭配不当。"}, {"text": "你别的喝了，already太晚了。", "explanation": "这里应该用〈别〉。劝阻用“别”，不能用“别的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "除了苹果，我还买了别的个东西。", "corrected_sentence": "除了苹果，我还买了别的东西。", "error_description": "错误：“别的”与“东西”之间多加了量词“个”，写成“别的个东西”。正确：应为“别的东西”，“别的”作定语直接修饰名词，中间不能加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法不行，我们换别的的吧。", "corrected_sentence": "这个办法不行，我们换别的吧。", "error_description": "错误：“别的”后多加一个“的”，写成“别的的”。正确：应为“换别的吧”，“别的”作代词本身已含“的”，不能再加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba55d9bf-ce9a-448d-a6e0-d67c2c83f6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
