INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86583, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "以为是心里这样想，可是想得不一定对。", "primary_collocate": null, "pronunciation": "yǐ wéi", "ipa": "i˨˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我以为今天是星期五，原来是星期四。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以为我生气了，其实我只是累了。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为你已经回家了。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以为这件事很容易吗？", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还以为他是中国人呢。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都以为她会来，可是她没来。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到灯亮着，我以为你在家。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以为那是盐，结果是糖。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为明天下雨，就带了伞。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别以为学中文很难，你会喜欢的。", "target_word": "以为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "以為", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里这样想，但想得不一定对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89977fd-f280-49cb-8f9f-d28e7bd372bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86583, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以为", "is_correct": true, "explanation": "正确答案：以为（yǐ wéi），表示心里这样想，但想得不一定对。"}, {"text": "意味", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，wéi 与 wèi 声调也不同，意思是“意味”。"}, {"text": "一位", "is_correct": false, "explanation": "yǐ 与 yí、wéi 与 wèi 声调不同，意思是“一位”（一个人）。"}, {"text": "意为", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是“表示……的意思”。"}], "explanations": {"以为": "正确答案：以为（yǐ wéi），表示心里这样想，但想得不一定对。", "意味": "yǐ（第三声）与 yì（第四声）声调不同，wéi 与 wèi 声调也不同，意思是“意味”。", "一位": "yǐ 与 yí、wéi 与 wèi 声调不同，意思是“一位”（一个人）。", "意为": "yǐ（第三声）与 yì（第四声）声调不同，意思是“表示……的意思”。"}, "sentence_index": null, "correct_answer": "以为"}, "level_3": {"options": [{"text": "以为", "is_correct": true, "explanation": "正确：以为表示心里这样想，后来发现想得不对，与“原来是星期四”相合。"}, {"text": "知道", "is_correct": false, "explanation": "语义：“知道”表示确知，与后半句“原来是星期四”的意外发现矛盾。"}, {"text": "听见", "is_correct": false, "explanation": "配价：「听见」后接的是声音或所听到的话，不能直接接「今天是星期五」这样的判断小句。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”要带接收的人，不能直接接“今天是星期五”这样的判断小句。"}], "explanations": {"以为": "正确：以为表示心里这样想，后来发现想得不对，与“原来是星期四”相合。", "知道": "语义：“知道”表示确知，与后半句“原来是星期四”的意外发现矛盾。", "听见": "配价：「听见」后接的是声音或所听到的话，不能直接接「今天是星期五」这样的判断小句。", "通知": "配价：“通知”要带接收的人，不能直接接“今天是星期五”这样的判断小句。"}, "sentence_index": 0, "correct_answer": "以为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我以为地球是绕着太阳转的，这是科学事实。", "explanation": "这里应该用〈知道〉。以为表示心里这样想、但不一定对，不能用来陈述已经证实的科学事实。"}, {"text": "医生以为他得了肺炎，检查报告已经出来了。", "explanation": "这里应该用〈诊断〉。以为只表示没有把握的猜测，不能用于已有检查报告作依据的确诊。"}, {"text": "我以为这个数字是正确的，我十分确定，不可能有错。", "explanation": "这里应该用〈确信〉。以为表示没有把握，与「十分确定，不可能有错」的语气矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以为", "is_correct": true, "explanation": "正确：以为表示凭所见作出的判断，但没有把握，与“看到灯亮着”相合。"}, {"text": "梦见", "is_correct": false, "explanation": "语义：“梦见”说的是梦中的情况，与“看到灯亮着”的实际所见矛盾。"}, {"text": "听说", "is_correct": false, "explanation": "语义：“听说”表示从别人那里得知，与“看到灯亮着”的亲眼所见不符。"}, {"text": "认出", "is_correct": false, "explanation": "配价：“认出”带的宾语是人或事物，不能接“你在家”这样的小句。"}], "explanations": {"以为": "正确：以为表示凭所见作出的判断，但没有把握，与“看到灯亮着”相合。", "梦见": "语义：“梦见”说的是梦中的情况，与“看到灯亮着”的实际所见矛盾。", "听说": "语义：“听说”表示从别人那里得知，与“看到灯亮着”的亲眼所见不符。", "认出": "配价：“认出”带的宾语是人或事物，不能接“你在家”这样的小句。"}, "sentence_index": 6, "correct_answer": "以为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我以为明年去中国，已经买好了机票。", "explanation": "这里应该用〈打算〉。以为是对情况的判断，不能用来说自己的安排；“已经买好了机票”说明这是计划。"}, {"text": "我以为明天准时到，这一点我向你保证。", "explanation": "这里应该用〈保证〉。以为只表示判断，不能用来向对方许诺；「向你保证」说明这是确定的承诺。"}, {"text": "组长以为大家明天必须到场，这是硬性规定。", "explanation": "这里应该用〈要求〉。以为只表示猜测，不能用于明确的硬性规定；“这是硬性规定”说明这是确定的要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她以为了事情已经结束。", "corrected_sentence": "她以为事情已经结束。", "error_description": "错误：“以为了”。正确：“以为”后不能带“了”，应为“她以为事情已经结束”。“了”表示完成或变化，与心理判断“以为”不相容。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以为着她已经睡了。", "corrected_sentence": "我以为她已经睡了。", "error_description": "错误：“以为着”。正确：“以为”后不加“着”。“着”表示动作或状态的持续，而“以为”是心理判断，不能带“着”，应为“我以为她已经睡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
