INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86585, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "啥是什么的另一种说法。", "primary_collocate": null, "pronunciation": "shá", "ipa": "ʂa˧˥", "syllable_count": 1, "sentences": [{"text": "你说啥？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你在看啥？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他啥也不想吃。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字是啥意思？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你昨天买了啥？", "target_word": "啥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上吃啥？我饿死了。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我没听清，不知道他说啥。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你想喝点啥？我去买。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他今天啥都没做。", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个菜叫啥名字？", "target_word": "啥", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "啥：“什么”的口语说法，用于询问事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d125fbf-5287-4485-9a68-7d0834fbb130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86585, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啥", "is_correct": true, "explanation": "啥（shá，第二声）：口语疑问代词，相当于“什么”。"}, {"text": "傻", "is_correct": false, "explanation": "shǎ（第三声）与 shá（第二声）声调不同，意思是“笨”。"}, {"text": "沙", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。"}, {"text": "杀", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“杀”。"}, {"text": "蛇", "is_correct": false, "explanation": "shé 与 shá 韵母不同（e/a），意思是“蛇”。"}], "explanations": {"啥": "啥（shá，第二声）：口语疑问代词，相当于“什么”。", "傻": "shǎ（第三声）与 shá（第二声）声调不同，意思是“笨”。", "沙": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。", "杀": "shā（第一声）与 shá（第二声）声调不同，意思是“杀”。", "蛇": "shé 与 shá 韵母不同（e/a），意思是“蛇”。"}, "sentence_index": null, "correct_answer": "啥"}, "level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能作“说”的宾语，“你说非常？”不成句。"}, {"text": "啥", "is_correct": true, "explanation": "啥：口语疑问代词，相当于“什么”，问说的内容。“你说啥？”自然。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是副词，不能作“说”的宾语，“你说很？”不成句。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，不能作宾语，“你说已经？”不成句。"}], "explanations": {"非常": "语法：“非常”是程度副词，不能作“说”的宾语，“你说非常？”不成句。", "啥": "啥：口语疑问代词，相当于“什么”，问说的内容。“你说啥？”自然。", "很": "语法：“很”是副词，不能作“说”的宾语，“你说很？”不成句。", "已经": "语法：“已经”是副词，不能作宾语，“你说已经？”不成句。"}, "sentence_index": 0, "correct_answer": "啥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家在啥？", "explanation": "这里应该用〈哪儿〉。问处所要用“哪儿”，“啥”问的是事物，不能问地点。"}, {"text": "你家有啥口人？", "explanation": "这里应该用〈几〉。问数量要用“几”，“啥”不能用来问人数。"}, {"text": "这个苹果啥钱？", "explanation": "这里应该用〈多少〉。问价钱要用“多少钱”，“啥钱”不能用来问价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86585, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啥", "is_correct": true, "explanation": "啥（shá，第二声）：口语疑问代词，相当于“什么”。"}, {"text": "沙", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。"}, {"text": "纱", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“纱布”。"}, {"text": "鲨", "is_correct": false, "explanation": "shā（第一声）与 shá（第二声）声调不同，意思是“鲨鱼”。"}], "explanations": {"啥": "啥（shá，第二声）：口语疑问代词，相当于“什么”。", "沙": "shā（第一声）与 shá（第二声）声调不同，意思是“沙子”。", "纱": "shā（第一声）与 shá（第二声）声调不同，意思是“纱布”。", "鲨": "shā（第一声）与 shá（第二声）声调不同，意思是“鲨鱼”。"}, "sentence_index": null, "correct_answer": "啥"}, "level_3": {"options": [{"text": "正在", "is_correct": false, "explanation": "语法：“正在”是副词，表示动作进行，不能作“说”的宾语，“他说正在”不通。"}, {"text": "啥", "is_correct": true, "explanation": "啥：口语疑问代词，相当于“什么”。“不知道他说啥”指不清楚他说了什么。"}, {"text": "从", "is_correct": false, "explanation": "语法：“从”是介词，后面要带地点或时间，不能单独作“说”的宾语，“他说从”不成句。"}, {"text": "比较", "is_correct": false, "explanation": "语法：“比较”在这里是程度副词，不能作“说”的宾语，“他说比较”不通。"}], "explanations": {"正在": "语法：“正在”是副词，表示动作进行，不能作“说”的宾语，“他说正在”不通。", "啥": "啥：口语疑问代词，相当于“什么”。“不知道他说啥”指不清楚他说了什么。", "从": "语法：“从”是介词，后面要带地点或时间，不能单独作“说”的宾语，“他说从”不成句。", "比较": "语法：“比较”在这里是程度副词，不能作“说”的宾语，“他说比较”不通。"}, "sentence_index": 6, "correct_answer": "啥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的作者是啥？", "explanation": "这里应该用〈谁〉。问人要用“谁”，“啥”只问事物，不能用来问作者这样的人。"}, {"text": "这件事你要啥样办？", "explanation": "这里应该用〈怎样〉。问办法要用“怎样”，“啥样”只问事物的样子，不能用来问办事的方式。"}, {"text": "他啥哭了一天。", "explanation": "这里应该用〈为啥〉。问原因时要把“为啥 / 为什么”放在动词前，单用“啥”放在动词前不成句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
