INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86587, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学院是大哥哥大姐姐学本领的地方。", "primary_collocate": null, "pronunciation": "xué yuàn", "ipa": "ɕɥɛ˧˥ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "哥哥姐姐每天去学院学本领。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在学院里学做蛋糕。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学院里有很多大哥哥大姐姐。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥想去学院学开飞机。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院里的老师教大家做很多事。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐说学院是学本领的地方。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我长大以后也要去学院。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥从学院回来，给我讲了很多新鲜事。", "target_word": "学院", "complexity_tier": "T3", "furigana": "gē ge cóng xué yuàn huí lái, gěi wǒ jiǎng le hěn duō xīn xiān shì。", "sentence_source": "generated"}, {"text": "学院门口有一棵大树。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在学院学会了画画。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "音乐学院", "label": "复合"}], "register": "中性", "sense_fingerprint": "大哥哥大姐姐学本领的地方（儿童视角）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86587, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学院", "is_correct": true, "explanation": "正确：xué yuàn，指大哥哥大姐姐学本领的地方。"}, {"text": "学员", "is_correct": false, "explanation": "学员 xué yuán 与 xué yuàn 的第二音节声调不同（第二声与第四声），意思是学习的人，不是地方。"}, {"text": "雪原", "is_correct": false, "explanation": "雪原 xuě yuán 与 xué yuàn 两个音节的声调都不同（第三声、第二声），意思是雪地。"}, {"text": "血缘", "is_correct": false, "explanation": "血缘 xuè yuán 与 xué yuàn 两个音节的声调都不同（第四声、第二声），意思是血统关系。"}], "explanations": {"学院": "正确：xué yuàn，指大哥哥大姐姐学本领的地方。", "学员": "学员 xué yuán 与 xué yuàn 的第二音节声调不同（第二声与第四声），意思是学习的人，不是地方。", "雪原": "雪原 xuě yuán 与 xué yuàn 两个音节的声调都不同（第三声、第二声），意思是雪地。", "血缘": "血缘 xuè yuán 与 xué yuàn 两个音节的声调都不同（第四声、第二声），意思是血统关系。"}, "sentence_index": null, "correct_answer": "学院"}, "level_3": {"options": [{"text": "学院", "is_correct": true, "explanation": "正确：学院是学本领的地方，与句中的“学本领”相符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是买东西的地方，去那里学本领说不通。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是吃饭的地方，不是学本领的地方。"}, {"text": "电影院", "is_correct": false, "explanation": "搭配：“学本领”不与电影院搭配，电影院是看电影的地方。"}], "explanations": {"学院": "正确：学院是学本领的地方，与句中的“学本领”相符。", "超市": "语义：超市是买东西的地方，去那里学本领说不通。", "饭店": "语义：饭店是吃饭的地方，不是学本领的地方。", "电影院": "搭配：“学本领”不与电影院搭配，电影院是看电影的地方。"}, "sentence_index": 0, "correct_answer": "学院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天在学院读小学。", "explanation": "这里应该用〈学校〉。读小学要说学校，学院指学本领的地方。"}, {"text": "我下班后常去学院买菜。", "explanation": "这里的「学院」被当作菜市场来用，学院指学本领的地方，不是买菜的地方。"}, {"text": "这家学院每天生产一千双鞋。", "explanation": "这里的「学院」被当作工厂来用，学院不生产东西，它指学本领的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86587, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "学院", "is_correct": true, "explanation": "正确：xué yuàn，指学本领的地方。"}, {"text": "雪冤", "is_correct": false, "explanation": "雪冤 xuě yuān 与 xué yuàn 两个音节的声调都不同（第三声、第一声），意思是洗清冤屈，不是地方。"}, {"text": "学园", "is_correct": false, "explanation": "学园 xué yuán 与 xué yuàn 的第二音节声调不同（第二声与第四声），指学习、游乐的园地。"}, {"text": "学运", "is_correct": false, "explanation": "学运 xué yùn 与 xué yuàn 的第二音节韵母不同（yùn 与 yuàn），意思是学生运动，不是地方。"}], "explanations": {"学院": "正确：xué yuàn，指学本领的地方。", "雪冤": "雪冤 xuě yuān 与 xué yuàn 两个音节的声调都不同（第三声、第一声），意思是洗清冤屈，不是地方。", "学园": "学园 xué yuán 与 xué yuàn 的第二音节声调不同（第二声与第四声），指学习、游乐的园地。", "学运": "学运 xué yùn 与 xué yuàn 的第二音节韵母不同（yùn 与 yuàn），意思是学生运动，不是地方。"}, "sentence_index": null, "correct_answer": "学院"}, "level_3": {"options": [{"text": "学院", "is_correct": true, "explanation": "正确：“长大以后”要去学本领的地方，学院符合句意。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是地方，不能说“去苹果”。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，不是地方，不能说“去铅笔”。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服是穿的东西，不是地方，不能说“去衣服”。"}], "explanations": {"学院": "正确：“长大以后”要去学本领的地方，学院符合句意。", "苹果": "语义：苹果是水果，不是地方，不能说“去苹果”。", "铅笔": "语义：铅笔是文具，不是地方，不能说“去铅笔”。", "衣服": "语义：衣服是穿的东西，不是地方，不能说“去衣服”。"}, "sentence_index": 6, "correct_answer": "学院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟今年六岁，已经在学院读一年级了。", "explanation": "这里应该用〈小学〉。读一年级属于小学阶段，学院指学本领的地方，不是上学的阶段。"}, {"text": "我姐姐在学院看病，医生很和气。", "explanation": "这里应该用〈医院〉。看病要去医院，学院指学本领的地方，不能用来看病。"}, {"text": "我去学院取钱了。", "explanation": "这里应该用〈银行〉。取钱要去银行，学院不是存取钱的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐学院回来了，说学了很多本领。", "corrected_sentence": "姐姐从学院回来了，说学了很多本领。", "error_description": "错误：漏掉了介词“从”。正确形式是“从学院回来”，“从”引出动作的起点；“学院回来”缺少“从”，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹在一只学院里学会了游泳。", "corrected_sentence": "妹妹在一所学院里学会了游泳。", "error_description": "错误：量词用错。“学院”是机构，量词应用“所”。“一只”不能用于机构，正确是“一所学院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
