INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高等教育机构的一种，可以独立设置，也可以是大学的组成部分。", "primary_collocate": null, "pronunciation": "xué yuàn", "ipa": "ɕɥɛ˧˥ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们学院在学校的东边。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在学院学了四年设计。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学院有很多外国学生。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院的院长今天要开会。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想报考这所学院的法律专业。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院的图书馆晚上十点才关门。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院里有很多系，每个系有自己的老师。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院每年夏天都举行毕业典礼。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从这个学院毕业后去了北京工作。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院给成绩好的学生发奖学金。", "target_word": "学院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "医学院", "label": "复合"}], "register": "中性", "sense_fingerprint": "高等教育机构，独立设置或属于大学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86588, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学院", "is_correct": true, "explanation": "正确：xué yuàn，指高等教育机构或大学的组成部分。"}, {"text": "学员", "is_correct": false, "explanation": "学员 xué yuán 与 xué yuàn 的第二音节声调不同（第二声与第四声），意思是学习的人，不是机构。"}, {"text": "雪原", "is_correct": false, "explanation": "雪原 xuě yuán 与 xué yuàn 两个音节的声调都不同（第三声、第二声），意思是雪地。"}, {"text": "血缘", "is_correct": false, "explanation": "血缘 xuè yuán 与 xué yuàn 两个音节的声调都不同（第四声、第二声），意思是血统关系。"}], "explanations": {"学院": "正确：xué yuàn，指高等教育机构或大学的组成部分。", "学员": "学员 xué yuán 与 xué yuàn 的第二音节声调不同（第二声与第四声），意思是学习的人，不是机构。", "雪原": "雪原 xuě yuán 与 xué yuàn 两个音节的声调都不同（第三声、第二声），意思是雪地。", "血缘": "血缘 xuè yuán 与 xué yuàn 两个音节的声调都不同（第四声、第二声），意思是血统关系。"}, "sentence_index": null, "correct_answer": "学院"}, "level_3": {"options": [{"text": "学院", "is_correct": true, "explanation": "正确：“我们学院”指所属的高等教育机构，能在学校的东边。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不是场所，不能说“我们作业在学校的东边”。"}, {"text": "道理", "is_correct": false, "explanation": "语义：“道理”是抽象概念，不是场所，不能位于学校的东边。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“我们”后面不能接“天气”作为处所，与句意不搭。"}], "explanations": {"学院": "正确：“我们学院”指所属的高等教育机构，能在学校的东边。", "作业": "搭配：“作业”不是场所，不能说“我们作业在学校的东边”。", "道理": "语义：“道理”是抽象概念，不是场所，不能位于学校的东边。", "天气": "搭配：“我们”后面不能接“天气”作为处所，与句意不搭。"}, "sentence_index": 0, "correct_answer": "学院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学院的小学生每天早上六点起床跑步。", "explanation": "这里应该用〈小学〉。小学生属于小学阶段，学院指高等教育机构，不能用来指小学生的学校。"}, {"text": "我每天坐学院的火车去上班。", "explanation": "这里的「学院」被当作火车来用，学院不是交通工具，不能这样用。"}, {"text": "这家学院的鸡蛋很新鲜，每天都有人来买。", "explanation": "这里的「学院」被当作商店来用，学院是高等教育机构，不卖鸡蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86588, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "学院", "is_correct": true, "explanation": "正确：xué yuàn，指高等教育机构或大学的组成部分。"}, {"text": "雪冤", "is_correct": false, "explanation": "雪冤 xuě yuān 与 xué yuàn 两个音节的声调都不同（第三声、第一声），意思是洗清冤屈，不是机构。"}, {"text": "学园", "is_correct": false, "explanation": "学园 xué yuán 与 xué yuàn 的第二音节声调不同（第二声与第四声），指学习、游乐的园地。"}, {"text": "学运", "is_correct": false, "explanation": "学运 xué yùn 与 xué yuàn 的第二音节韵母不同（yùn 与 yuàn），意思是学生运动，不是机构。"}], "explanations": {"学院": "正确：xué yuàn，指高等教育机构或大学的组成部分。", "雪冤": "雪冤 xuě yuān 与 xué yuàn 两个音节的声调都不同（第三声、第一声），意思是洗清冤屈，不是机构。", "学园": "学园 xué yuán 与 xué yuàn 的第二音节声调不同（第二声与第四声），指学习、游乐的园地。", "学运": "学运 xué yùn 与 xué yuàn 的第二音节韵母不同（yùn 与 yuàn），意思是学生运动，不是机构。"}, "sentence_index": null, "correct_answer": "学院"}, "level_3": {"options": [{"text": "学院", "is_correct": true, "explanation": "正确：学院里设有“系”，符合句意。"}, {"text": "中学", "is_correct": false, "explanation": "语义：中学不设“系”，“系”是高校的组成单位，句子说不通。"}, {"text": "小学", "is_correct": false, "explanation": "语义：小学不设“系”，与“每个系有自己的老师”矛盾。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：超市不设“系”，“系”与超市不搭配。"}], "explanations": {"学院": "正确：学院里设有“系”，符合句意。", "中学": "语义：中学不设“系”，“系”是高校的组成单位，句子说不通。", "小学": "语义：小学不设“系”，与“每个系有自己的老师”矛盾。", "超市": "搭配：超市不设“系”，“系”与超市不搭配。"}, "sentence_index": 6, "correct_answer": "学院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学院给表现好的小朋友发小红花。", "explanation": "这里应该用〈幼儿园〉。给小朋友发小红花是幼儿园的做法，学院是高等教育机构，不面向小朋友。"}, {"text": "我今天头疼，去学院看病了。", "explanation": "这里应该用〈医院〉。看病要去医院，学院是高等教育机构，不能用来看病。"}, {"text": "我每天去学院理发。", "explanation": "这里应该用〈理发店〉。理发要去理发店，学院不是理发的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_us