INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学院学习了三年。", "corrected_sentence": "他在学院学习了三年。", "error_description": "错误：漏掉了介词“在”。正确是“在学院学习”，地点要用“在”引出；“学院学习”缺少“在”，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一只学院的院长。", "corrected_sentence": "他是一所学院的院长。", "error_description": "错误：量词用错。“学院”是机构，量词应用“所”。“一只”不能用于机构，正确是“一所学院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
