INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，以……为根据。", "primary_collocate": null, "pronunciation": "jī yú", "ipa": "tɕi˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "这个故事基于一件真实的事。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告基于大量的数据。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的看法基于多年的经验。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影基于一本有名的小说。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划基于今年的成绩。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的话基于检查的结果。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏基于中国的老故事。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的判断基于这些照片。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的价格基于成本来定。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结论基于三年的研究。", "target_word": "基于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "介词：以某事物为根据或基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b75bf49-c43f-4514-936d-2f7a6e455359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确答案。听到的就是“基于”（jī yú）。"}, {"text": "寄语", "is_correct": false, "explanation": "寄语（jì yǔ）两个音节的声调都与基于不同，意思是给人的话。"}, {"text": "低于", "is_correct": false, "explanation": "低于（dī yú）与基于的第一个音节声母不同（d 与 j），声调相同，意思是比……低。"}, {"text": "机油", "is_correct": false, "explanation": "机油（jī yóu）与基于的第二个音节韵母不同（yóu 与 yú），声调相同，意思是润滑用的油。"}, {"text": "急于", "is_correct": false, "explanation": "急于（jí yú）与基于的第一个音节声调不同，意思是迫切想要。"}], "explanations": {"基于": "正确答案。听到的就是“基于”（jī yú）。", "寄语": "寄语（jì yǔ）两个音节的声调都与基于不同，意思是给人的话。", "低于": "低于（dī yú）与基于的第一个音节声母不同（d 与 j），声调相同，意思是比……低。", "机油": "机油（jī yóu）与基于的第二个音节韵母不同（yóu 与 yú），声调相同，意思是润滑用的油。", "急于": "急于（jí yú）与基于的第一个音节声调不同，意思是迫切想要。"}, "sentence_index": null, "correct_answer": "基于"}, "level_3": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确。基于表示以某事物为根据或来源，这里说明故事的来源。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“向”引出方向或对象，“一件真实的事”不能作为故事的来源。"}, {"text": "除了", "is_correct": false, "explanation": "语义：“除了”表示排除，不能说明故事的来源。"}, {"text": "跟", "is_correct": false, "explanation": "配价：“跟”引出共同发生关系的对象，这里句子缺少谓语，说不通。"}], "explanations": {"基于": "正确。基于表示以某事物为根据或来源，这里说明故事的来源。", "向": "搭配：“向”引出方向或对象，“一件真实的事”不能作为故事的来源。", "除了": "语义：“除了”表示排除，不能说明故事的来源。", "跟": "配价：“跟”引出共同发生关系的对象，这里句子缺少谓语，说不通。"}, "sentence_index": 0, "correct_answer": "基于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他基于钥匙开门。", "explanation": "这里应该用〈用〉。基于表示以某事物为根据或来源，不表示用什么工具去做事。"}, {"text": "他基于父母生活。", "explanation": "这里应该用〈依靠〉。基于是介词，不表示依赖父母生活。"}, {"text": "她基于厨房做饭。", "explanation": "这里应该用〈在〉。基于表示根据，不表示动作发生的场所，应说“在厨房做饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确答案。听到的就是“基于”（jī yú）。"}, {"text": "急雨", "is_correct": false, "explanation": "急雨（jí yǔ）两个音节的声调都与基于不同，意思是突然下的雨。"}, {"text": "之于", "is_correct": false, "explanation": "之于（zhī yú）与基于的第一个音节声母不同（zh 与 j），声调相同，意思是对于。"}, {"text": "机遇", "is_correct": false, "explanation": "机遇（jī yù）与基于的第二个音节声调不同（yù 第四声，yú 第二声），意思是机会。"}, {"text": "利于", "is_correct": false, "explanation": "利于（lì yú）与基于的第一个音节声母和声调都不同（l 与 j，第四声），意思是有益于。"}], "explanations": {"基于": "正确答案。听到的就是“基于”（jī yú）。", "急雨": "急雨（jí yǔ）两个音节的声调都与基于不同，意思是突然下的雨。", "之于": "之于（zhī yú）与基于的第一个音节声母不同（zh 与 j），声调相同，意思是对于。", "机遇": "机遇（jī yù）与基于的第二个音节声调不同（yù 第四声，yú 第二声），意思是机会。", "利于": "利于（lì yú）与基于的第一个音节声母和声调都不同（l 与 j，第四声），意思是有益于。"}, "sentence_index": null, "correct_answer": "基于"}, "level_3": {"options": [{"text": "基于", "is_correct": true, "explanation": "正确。基于表示以某事物为根据或来源，这里说明游戏的来源。"}, {"text": "与", "is_correct": false, "explanation": "配价：“与”引出相关的对象，后面要有谓语说明关系，这里句子缺少谓语。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人做事，不能表示游戏的来源。"}, {"text": "随着", "is_correct": false, "explanation": "语义：“随着”表示伴随某种变化，不能表示游戏的来源。"}], "explanations": {"基于": "正确。基于表示以某事物为根据或来源，这里说明游戏的来源。", "与": "配价：“与”引出相关的对象，后面要有谓语说明关系，这里句子缺少谓语。", "替": "语义：“替”表示代替某人做事，不能表示游戏的来源。", "随着": "语义：“随着”表示伴随某种变化，不能表示游戏的来源。"}, "sentence_index": 6, "correct_answer": "基于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我基于地板睡觉。", "explanation": "这里应该用〈在〉。基于表示根据，不表示人躺或睡在什么地方，应说“在地板上睡觉”。"}, {"text": "孩子基于沙发躺着。", "explanation": "这里应该用〈躺在〉。基于表示根据，不能用来说明人躺在什么地方。"}, {"text": "我基于地铁上班。", "explanation": "这里应该用〈坐〉。基于表示根据，不表示乘坐某种交通工具，应说“坐地铁上班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章被基于一次真实的采访。", "corrected_sentence": "这篇文章基于一次真实的采访。", "error_description": "错误在“基于”前面加了“被”。基于是介词，不能用在“被”字句中，应去掉“被”，说“这篇文章基于一次真实的采访”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次调查的基于三百份问卷。", "corrected_sentence": "这次调查基于三百份问卷。", "error_description": "错误在“基于”前面加了“的”。“的”应接在名词或形容词后面，基于是介词，前面不能加“的”，应改为“这次调查基于三百份问卷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
