INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86591, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搞是动手去做一件事。", "primary_collocate": null, "pronunciation": "gǎo", "ipa": "kɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我们周末一起搞卫生吧。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想搞一次读书活动。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在院子里搞个小花园。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷最近在阳台搞了个小菜园。", "target_word": "搞", "complexity_tier": "T3", "furigana": "yé ye zuì jìn zài yáng tái gǎo le gè xiǎo cài yuán。", "sentence_source": "generated"}, {"text": "我们小组正在搞一个实验。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司明年要搞一次大活动。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在家里搞装修。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想搞一个新网站。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们搞小制作。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里准备搞一场比赛。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搞了", "label": "体标"}, {"form": "搞过", "label": "体标"}], "register": "口语", "sense_fingerprint": "动手去做、开展一件具体的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86591, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搞", "is_correct": true, "explanation": "正确：gǎo，动手去做一件具体的事。"}, {"text": "糕", "is_correct": false, "explanation": "糕 gāo 与 gǎo 声调不同（第一声与第三声），意思是糕点。"}, {"text": "考", "is_correct": false, "explanation": "考 kǎo 与 gǎo 声母不同（k 与 g），意思是考试。"}, {"text": "赶", "is_correct": false, "explanation": "赶 gǎn 与 gǎo 韵母不同（an 与 ao），意思是追赶。"}, {"text": "狗", "is_correct": false, "explanation": "狗 gǒu 与 gǎo 韵母不同（ou 与 ao），意思是狗。"}], "explanations": {"搞": "正确：gǎo，动手去做一件具体的事。", "糕": "糕 gāo 与 gǎo 声调不同（第一声与第三声），意思是糕点。", "考": "考 kǎo 与 gǎo 声母不同（k 与 g），意思是考试。", "赶": "赶 gǎn 与 gǎo 韵母不同（an 与 ao），意思是追赶。", "狗": "狗 gǒu 与 gǎo 韵母不同（ou 与 ao），意思是狗。"}, "sentence_index": null, "correct_answer": "搞"}, "level_3": {"options": [{"text": "搞", "is_correct": true, "explanation": "正确：“搞卫生”是动手做的意思，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“卫生”搭配，说不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“卫生”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“卫生”搭配，句子不通。"}], "explanations": {"搞": "正确：“搞卫生”是动手做的意思，符合句意。", "吃": "搭配：“吃”不能与“卫生”搭配，说不通。", "睡": "配价：“睡”是不及物动词，不能带“卫生”作宾语。", "唱": "搭配：“唱”不能与“卫生”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "搞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他搞了我一眼，没有说话。", "explanation": "这里的「搞」用作“看”，不能说“搞一眼”，应该用〈看〉。「搞」指动手去做一件事。"}, {"text": "他在我面前搞了一个喷嚏。", "explanation": "这里的「搞」用作“打”，不能说“搞一个喷嚏”，应该用〈打〉。「搞」指动手去做一件事。"}, {"text": "妈妈搞了一晚上的心，一直没睡好。", "explanation": "这里的「搞」用作“操”，不能说“搞心”，应该用〈操心〉。「搞」指动手去做一件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86591, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "搞", "is_correct": true, "explanation": "正确：gǎo，动手去做一件具体的事。"}, {"text": "高", "is_correct": false, "explanation": "高 gāo 与 gǎo 声调不同（第一声与第三声），意思是高矮的高。"}, {"text": "烤", "is_correct": false, "explanation": "烤 kǎo 与 gǎo 声母不同（k 与 g），意思是用火加热食物。"}, {"text": "告", "is_correct": false, "explanation": "告 gào 与 gǎo 声调不同（第四声与第三声），意思是告诉。"}, {"text": "早", "is_correct": false, "explanation": "早 zǎo 与 gǎo 声母不同（z 与 g），意思是早上。"}], "explanations": {"搞": "正确：gǎo，动手去做一件具体的事。", "高": "高 gāo 与 gǎo 声调不同（第一声与第三声），意思是高矮的高。", "烤": "烤 kǎo 与 gǎo 声母不同（k 与 g），意思是用火加热食物。", "告": "告 gào 与 gǎo 声调不同（第四声与第三声），意思是告诉。", "早": "早 zǎo 与 gǎo 声母不同（z 与 g），意思是早上。"}, "sentence_index": null, "correct_answer": "搞"}, "level_3": {"options": [{"text": "搞", "is_correct": true, "explanation": "正确：“搞装修”是动手做的意思，符合句意。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能与“装修”搭配，句子不通。"}, {"text": "躺", "is_correct": false, "explanation": "配价：“躺”是不及物动词，不能带“装修”作宾语。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能与“装修”搭配，句子说不通。"}], "explanations": {"搞": "正确：“搞装修”是动手做的意思，符合句意。", "跳": "搭配：“跳”不能与“装修”搭配，句子不通。", "躺": "配价：“躺”是不及物动词，不能带“装修”作宾语。", "哭": "搭配：“哭”不能与“装修”搭配，句子说不通。"}, "sentence_index": 6, "correct_answer": "搞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上搞了一道彩虹。", "explanation": "这里的「搞」用作“出现”，彩虹不是人动手做出来的，应该用〈出现〉。「搞」指动手去做一件事。"}, {"text": "他搞了一个晚上的觉，早上才醒。", "explanation": "这里的「搞」用作“睡”，不能说“搞觉”，应该用〈睡〉。「搞」指动手去做一件事。"}, {"text": "这个箱子能搞很多书。", "explanation": "这里的「搞」用作“装”，不能这样说，应该用〈装〉。「搞」指动手去做一件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班搞了过一次运动会。", "corrected_sentence": "我们班搞过一次运动会。", "error_description": "错误：同时用了“了”和“过”。“搞过”表示曾经做过，只用“过”，不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把展览搞了好。", "corrected_sentence": "他把展览搞好了。", "error_description": "错误：结果补语“好”与“了”的位置颠倒。正确是“搞好了”，“好”紧跟动词作补语，“了”放在句末；“搞了好”语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
