INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86592, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "口语中泛指做、干、弄，可以代替许多具体的动词。", "primary_collocate": null, "pronunciation": "gǎo", "ipa": "kɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "你们在搞什么，这么吵？", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想搞点好吃的。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想搞一张音乐会的票。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑我搞了一下午也没搞好。", "target_word": "搞", "complexity_tier": "T3", "furigana": "zhè tái diàn nǎo wǒ gǎo le yí xiàwǔ yě méi gǎo hǎo。", "sentence_source": "generated"}, {"text": "爸爸在厨房搞晚饭。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别在这儿搞破坏。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们搞了一次大检查。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我来搞，你休息吧。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在院子里搞什么东西？", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搞了半天，还是没打开门。", "target_word": "搞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搞了", "label": "体标"}, {"form": "搞过", "label": "体标"}], "register": "口语", "sense_fingerprint": "口语泛指做、干、弄，可代替多种具体动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86592, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搞", "is_correct": true, "explanation": "正确：gǎo，口语中泛指做、干、弄。"}, {"text": "高", "is_correct": false, "explanation": "高 gāo 与 gǎo 声调不同（第一声与第三声），意思是高矮的高。"}, {"text": "考", "is_correct": false, "explanation": "考 kǎo 与 gǎo 声母不同（k 与 g），意思是考试。"}, {"text": "告", "is_correct": false, "explanation": "告 gào 与 gǎo 声调不同（第四声与第三声），意思是告诉。"}, {"text": "狗", "is_correct": false, "explanation": "狗 gǒu 与 gǎo 韵母不同（ou 与 ao），意思是狗。"}], "explanations": {"搞": "正确：gǎo，口语中泛指做、干、弄。", "高": "高 gāo 与 gǎo 声调不同（第一声与第三声），意思是高矮的高。", "考": "考 kǎo 与 gǎo 声母不同（k 与 g），意思是考试。", "告": "告 gào 与 gǎo 声调不同（第四声与第三声），意思是告诉。", "狗": "狗 gǒu 与 gǎo 韵母不同（ou 与 ao），意思是狗。"}, "sentence_index": null, "correct_answer": "搞"}, "level_3": {"options": [{"text": "搞", "is_correct": true, "explanation": "正确：“你们在搞什么”是口语泛指做事，符合句意。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能带“什么”作宾语，句子不成立。"}, {"text": "躺", "is_correct": false, "explanation": "配价：“躺”是不及物动词，不能带“什么”作宾语，句子不成立。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“什么”作宾语。"}], "explanations": {"搞": "正确：“你们在搞什么”是口语泛指做事，符合句意。", "咳嗽": "配价：“咳嗽”是不及物动词，不能带“什么”作宾语，句子不成立。", "躺": "配价：“躺”是不及物动词，不能带“什么”作宾语，句子不成立。", "睡": "配价：“睡”是不及物动词，不能带“什么”作宾语。"}, "sentence_index": 0, "correct_answer": "搞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班搞了三十个学生。", "explanation": "这里的「搞」表示“有、包括”，不能用来说班里有多少人，应该用〈有〉。「搞」原指做、干、弄。"}, {"text": "他搞了我一眼，没有说话。", "explanation": "这里的「搞」用作“看”，不能说“搞一眼”，应该用〈看〉。「搞」的意思是做、干、弄。"}, {"text": "他搞了一下午的觉，才醒过来。", "explanation": "这里的「搞」用作“睡”，不能说“搞觉”，应该用〈睡〉。「搞」的意思是做、干、弄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86592, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "搞", "is_correct": true, "explanation": "正确：gǎo，口语中泛指做、干、弄。"}, {"text": "糕", "is_correct": false, "explanation": "糕 gāo 与 gǎo 声调不同（第一声与第三声），意思是蛋糕一类的食品。"}, {"text": "烤", "is_correct": false, "explanation": "烤 kǎo 与 gǎo 声母不同（k 与 g），意思是用火加热食物。"}, {"text": "赶", "is_correct": false, "explanation": "赶 gǎn 与 gǎo 韵母不同（an 与 ao），意思是追赶。"}, {"text": "早", "is_correct": false, "explanation": "早 zǎo 与 gǎo 声母不同（z 与 g），意思是早上。"}], "explanations": {"搞": "正确：gǎo，口语中泛指做、干、弄。", "糕": "糕 gāo 与 gǎo 声调不同（第一声与第三声），意思是蛋糕一类的食品。", "烤": "烤 kǎo 与 gǎo 声母不同（k 与 g），意思是用火加热食物。", "赶": "赶 gǎn 与 gǎo 韵母不同（an 与 ao），意思是追赶。", "早": "早 zǎo 与 gǎo 声母不同（z 与 g），意思是早上。"}, "sentence_index": null, "correct_answer": "搞"}, "level_3": {"options": [{"text": "搞", "is_correct": true, "explanation": "正确：“搞了一次大检查”是口语泛指做事，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“大检查”搭配，说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌与“大检查”毫无关系，句子不成立。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“大检查”作宾语。"}], "explanations": {"搞": "正确：“搞了一次大检查”是口语泛指做事，符合句意。", "吃": "搭配：“吃”不能与“大检查”搭配，说不通。", "唱": "语义：唱歌与“大检查”毫无关系，句子不成立。", "跑": "配价：“跑”是不及物动词，不能带“大检查”作宾语。"}, "sentence_index": 6, "correct_answer": "搞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上搞了一道彩虹。", "explanation": "这里的「搞」用作“出现”，彩虹不是人动手做出来的，应该用〈出现〉。「搞」的意思是做、干、弄。"}, {"text": "他在我面前搞了一个哈欠。", "explanation": "这里的「搞」用作“打”，不能说“搞一个哈欠”，应该用〈打〉。「搞」的意思是做、干、弄。"}, {"text": "我每天搞一公里的路上学。", "explanation": "这里的「搞」用作“走”，不能说“搞一公里的路”，应该用〈走〉。「搞」的意思是做、干、弄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_versi