INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他搞了完这个任务，就回家了。", "corrected_sentence": "他搞完了这个任务，就回家了。", "error_description": "错误：“了”放在了结果补语“完”的前面。正确是“搞完”，结果补语要紧跟动词；“搞了完”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
