INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大多数是超过一半，很多很多。", "primary_collocate": null, "pronunciation": "dà duō shù", "ipa": "ta˥˩ two˥ ʂu˥˩", "syllable_count": 3, "sentences": [{"text": "大多数人都喜欢周末。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的大多数朋友住在北京。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里大多数学生会说汉语。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数员工坐地铁上班。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数商店九点开门。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里大多数人不开车。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数孩子爱吃甜的东西。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过大多数中国电影。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数同学今天都来了。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数老人早上六点就起床了。", "target_word": "大多数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大多數", "label": "繁体"}], "register": "通用", "sense_fingerprint": "名词：超过一半的、很多的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b75bf49-c43f-4514-936d-2f7a6e455359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大多数", "is_correct": true, "explanation": "正确。大多数修饰“人”，表示超过一半的人。"}, {"text": "东西", "is_correct": false, "explanation": "语义：“东西”不能喜欢周末，与“人都喜欢”不搭。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不是人，不能喜欢周末。"}, {"text": "动物", "is_correct": false, "explanation": "搭配：“动物人”不成词，动物不包括人，与“人都喜欢”不搭。"}], "explanations": {"大多数": "正确。大多数修饰“人”，表示超过一半的人。", "东西": "语义：“东西”不能喜欢周末，与“人都喜欢”不搭。", "汽车": "语义：“汽车”不是人，不能喜欢周末。", "动物": "搭配：“动物人”不成词，动物不包括人，与“人都喜欢”不搭。"}, "sentence_index": 0, "correct_answer": "大多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司大多数员工只有一个人。", "explanation": "这里“大多数”表示超过一半的很多人，不能用来说只有一个人。"}, {"text": "班里的大多数同学一个人也没来。", "explanation": "这里“大多数”表示超过一半的人，与“一个人也没来”矛盾。"}, {"text": "班里大多数同学就是全班同学。", "explanation": "这里“大多数”表示超过一半但不是全部，不能用来表示全部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大多数", "is_correct": true, "explanation": "正确。大多数修饰“孩子”，表示超过一半的孩子。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子孩子”说不通，桌子也不会爱吃甜的东西。"}, {"text": "书本", "is_correct": false, "explanation": "语义：“书本”不会爱吃甜的东西。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”不会爱吃甜的东西，这句话的主语必须是人。"}], "explanations": {"大多数": "正确。大多数修饰“孩子”，表示超过一半的孩子。", "桌子": "语义：“桌子孩子”说不通，桌子也不会爱吃甜的东西。", "书本": "语义：“书本”不会爱吃甜的东西。", "蔬菜": "语义：“蔬菜”不会爱吃甜的东西，这句话的主语必须是人。"}, "sentence_index": 6, "correct_answer": "大多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些钱的大多数正好一半。", "explanation": "这里“大多数”表示超过一半，不能用来表示正好一半。"}, {"text": "这块蛋糕大多数被我一个人吃了。", "explanation": "这里“大多数”表示占比例的部分，不能用来指计数的人或事物。"}, {"text": "这本书的大多数全部是空白。", "explanation": "这里“大多数”表示超过一半但不是全部，与“全部是空白”的说法不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多大多数同学都同意这个办法。", "corrected_sentence": "大多数同学都同意这个办法。", "error_description": "错误在“大多数”前面多加了“很多”。两者都表示数量多，重复使用，应删去“很多”，说“大多数同学都同意这个办法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
