INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大多数", "is_correct": true, "explanation": "正确。大多数表示公司员工中占很大比例的那部分人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“公司窗户的员工”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“公司天气的员工”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“公司颜色的员工”说不通。"}], "explanations": {"大多数": "正确。大多数表示公司员工中占很大比例的那部分人。", "窗户": "语义：“公司窗户的员工”说不通。", "天气": "语义：“公司天气的员工”说不通。", "颜色": "语义：“公司颜色的员工”说不通。"}, "sentence_index": 0, "correct_answer": "大多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些钱大多数全部都花光了。", "explanation": "这里“大多数”表示很大比例但不是全部，与“全部都花光了”矛盾。"}, {"text": "这些苹果的大多数只有一个。", "explanation": "这里“大多数”表示占很大比例的部分，不能用来说只有一个。"}, {"text": "这些钱的大多数正好一半。", "explanation": "这里“大多数”表示很大比例，不表示正好一半。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大多数", "is_correct": true, "explanation": "正确。大多数表示投票中占很大比例的人，作主语。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”不能投票，“选了第二个”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头选了”不搭，“选”的主语一般是人。"}, {"text": "树", "is_correct": false, "explanation": "语义：“树”不能投票，与“投票的结果是”不搭。"}], "explanations": {"大多数": "正确。大多数表示投票中占很大比例的人，作主语。", "小狗": "语义：“小狗”不能投票，“选了第二个”说不通。", "石头": "搭配：“石头选了”不搭，“选”的主语一般是人。", "树": "语义：“树”不能投票，与“投票的结果是”不搭。"}, "sentence_index": 6, "correct_answer": "大多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的大多数全部是空白。", "explanation": "这里“大多数”表示很大比例但不是全部，与“全部是空白”矛盾。"}, {"text": "这箱苹果的大多数只剩一个。", "explanation": "这里“大多数”表示很大比例，与“只剩一个”的数量矛盾。"}, {"text": "全班大多数同学正好是一半。", "explanation": "这里“大多数”表示很大比例，不表示正好一半。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很大多数人都喜欢这门课。", "corrected_sentence": "大多数人都喜欢这门课。", "error_description": "错误形式是「很大多数人」，正确形式是「大多数人」。「大多数」表示占很大比例的部分，本身已含程度意义，不能再受程度副词「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "投票的结果是，最大多数同意这个方案。", "corrected_sentence": "投票的结果是，大多数同意这个方案。", "error_description": "错误形式是「最大多数」，正确形式是「大多数」。「大多数」本身表示占很大比例的部分，不能再受表示最高级的「最」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
