INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86597, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "天天是每一天。", "primary_collocate": null, "pronunciation": "tiān tiān", "ipa": "tʰjɛn˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "爸爸天天开车送我上学。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我天天晚上给妈妈打电话。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明天天都带着一本书。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师天天让我们写日记。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天天在楼下的店买早饭。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天这里天天都很热。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐天天去健身房跑步。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我天天喝水，身体很好。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥天天忙着工作。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她天天给花浇水。", "target_word": "天天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天天", "label": "重叠"}], "register": "口语", "sense_fingerprint": "每一天，强调日复一日地做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天天", "is_correct": true, "explanation": "“天天”强调每天重复同一件事，与“送我上学”的日常习惯相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”强调至今一贯如此或从未如此，多与“都”或否定词连用，不表示每天重复。"}, {"text": "分别", "is_correct": false, "explanation": "语义：“分别”表示各自、分开，与“送我上学”这一共同行动矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，修饰形容词或心理动词，不能修饰“开车送我上学”这样的动作。"}], "explanations": {"天天": "“天天”强调每天重复同一件事，与“送我上学”的日常习惯相符。", "从来": "搭配：“从来”强调至今一贯如此或从未如此，多与“都”或否定词连用，不表示每天重复。", "分别": "语义：“分别”表示各自、分开，与“送我上学”这一共同行动矛盾。", "非常": "搭配：“非常”是程度副词，修饰形容词或心理动词，不能修饰“开车送我上学”这样的动作。"}, "sentence_index": 0, "correct_answer": "天天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸天天开车送我上学，有时候不送。", "explanation": "〈天天〉表示每天都送，与后半句“有时候不送”冲突。时断时续的情况不能用〈天天〉表达，要用〈偶尔〉之类的词。"}, {"text": "妹妹天天一次就考过了驾照。", "explanation": "〈天天〉表示每天重复，不能修饰“考过驾照”这种一次性的结果。这里表示每天练习的过程，应该说〈天天练习〉。"}, {"text": "那天晚上，他天天在家里做饭。", "explanation": "〈天天〉表示每一天的重复，与“那天晚上”这个特定时间冲突。指那一次的时候，应该说〈有一次〉，而不是〈天天〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天天", "is_correct": true, "explanation": "“天天”强调每天重复同一件事，与“去健身房跑步”的习惯相符。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”是程度副词，不能修饰“去健身房跑步”这样的动作。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与“都”或否定词连用，不能单独用在肯定句中表示每天的习惯。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”表示忽然发生一次，与日复一日的锻炼习惯相矛盾。"}], "explanations": {"天天": "“天天”强调每天重复同一件事，与“去健身房跑步”的习惯相符。", "十分": "搭配：“十分”是程度副词，不能修饰“去健身房跑步”这样的动作。", "从来": "搭配：“从来”多与“都”或否定词连用，不能单独用在肯定句中表示每天的习惯。", "猛然": "语义：“猛然”表示忽然发生一次，与日复一日的锻炼习惯相矛盾。"}, "sentence_index": 6, "correct_answer": "天天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花去年才种，她天天给它浇水，可是一次也没浇过。", "explanation": "〈天天〉表示每天都浇，与后半句“一次也没浇过”完全相反。〈天天〉只能用于确实每天发生的事，不能与完全否定的说法放在一起。"}, {"text": "她天天搬进了新家。", "explanation": "〈天天〉表示每天重复，而“搬进新家”只发生一次，两者不能搭配。这里应该说明搬家的时间，而不是每天的频率。"}, {"text": "这个星期她只去了一次公园，却天天都去。", "explanation": "〈天天〉说每天都去，与“只去了一次”矛盾。这里应该用〈偶尔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹天天天早上去公园跑步。", "corrected_sentence": "妹妹天天早上去公园跑步。", "error_description": "错误形式：“天天天早上”，多写了一个“天”；正确形式：“天天早上”。“天天”是一个整体副词，不能再加字，表示每天重复的习惯要用“天天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶天天给我做饭天天。", "corrected_sentence": "奶奶天天给我做饭。", "error_description": "错误：句末多出一个“天天”，副词“天天”不能放在动词短语“给我做饭”之后；删去多余的“天天”即为正确形式“奶奶天天给我做饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86599, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "空", "is_correct": true, "explanation": "正确：空与实构成反义，指里面没有东西，与“里面满满的”相对。"}, {"text": "甜", "is_correct": false, "explanation": "甜：形容词，指味道，与“实”不构成反义。"}, {"text": "快", "is_correct": false, "explanation": "快：形容词，指速度，与“实”的里面充满与否无关，不构成反义。"}, {"text": "长", "is_correct": false, "explanation": "长：形容词，指距离或时间，与“实”不构成反义。"}], "correct_answer": "空", "explanations": {"空": "正确：空与实构成反义，指里面没有东西，与“里面满满的”相对。", "甜": "甜：形容词，指味道，与“实”不构成反义。", "快": "快：形容词，指速度，与“实”的里面充满与否无关，不构成反义。", "长": "长：形容词，指距离或时间，与“实”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
